constexpr std::size_t kChatLogCapacity = 24;
constexpr std::size_t kChatTextCapacity = 80;
// EVERYONE, one thread per stored channel key, and room left for the people
// this deck is talking to directly. Eight was the whole budget when every
// thread was a person; with `kChannelKeyCapacity` keys each owning a thread of
// their own, eight would have meant a stored key evicting a correspondent.
constexpr std::size_t kChatPeerCapacity = 1U + kChannelKeyCapacity + 7U;
struct ChatLine {
    char from[8]{};
    char text[kChatTextCapacity]{};
    char when[6]{};
    std::uint32_t peer = 0xffffffffU;
    /// For a direct message this device sent with the want-ack bit: the
    /// packet id a Routing acknowledgement will name. Zero otherwise.
    std::uint32_t pending_id = 0;
    bool mine = false;
    /// The peer's radio confirmed delivery of this exact packet.
    bool acked = false;
    /// Arrived through the internet bridge rather than over the air. Shown on
    /// the line, because a message that did not cross the radio must never
    /// read like one that did.
    bool via_net = false;
    /// Name of the operator's stored channel key that opened this message, and
    /// empty for the ordinary case of the key every radio ships with. The name
    /// is copied rather than referenced by slot because the line outlives the
    /// key list: a key can be renamed, removed, or reordered afterwards, and a
    /// line that then pointed at a different key would be worse than one that
    /// records what actually opened it.
    char key_name[kChannelKeyNameCapacity]{};
    /// Fingerprint of that same key, and empty alongside an empty name. This
    /// is the field that decides which conversation the line belongs to, and
    /// the name is only what gets drawn, because a name can be typed twice.
    /// Rename a key and its history follows it; remove a key and add a
    /// different one under the old name and the old lines stay where they
    /// were, in a thread the new key does not seal. A message moving between
    /// threads is the one thing this file must never allow, and a digest of
    /// the key material is the only handle that cannot be made to move.
    char key_fp[kChannelKeyFingerprintDigits + 1]{};
};
struct ChatPeer {
    std::uint32_t node = 0xffffffffU;
    /// Long enough for a whole key name: a keyed thread is titled by its key,
    /// and a truncated title would name a channel the operator does not have.
    char name[kChannelKeyNameCapacity] = "EVERYONE";
    std::uint8_t unread = 0;
    /// Set for a thread that speaks under one of the operator's stored keys,
    /// empty for EVERYONE and for a direct message. Matched against
    /// `ChatLine::key_fp`, so what is drawn in a thread is exactly what that
    /// thread's key opened.
    char key_fp[kChannelKeyFingerprintDigits + 1]{};
};
// The log lives in RAM, so a power cycle used to wipe the conversation. NVS is
// flash with a finite write budget, so saving is debounced rather than done on
// every line that arrives.
constexpr std::uint32_t kChatSaveDebounceMs = 15000U;
bool chat_log_dirty = false;
std::uint32_t chat_log_save_due_ms = 0;
ChatLine chat_log[kChatLogCapacity]{};
std::size_t chat_log_count = 0;
std::size_t chat_log_start = 0;
ChatPeer chat_peers[kChatPeerCapacity] = {{0xffffffffU, "EVERYONE"}};
std::size_t chat_peer_count = 1;
std::size_t chat_peer_index = 0;
char chat_draft[kChatTextCapacity]{};
std::size_t chat_draft_len = 0;
// Which conversation the draft was typed in. A reviewer proved what its
// absence cost: type on a keyed thread, press TAB once, press ENTER, and the
// text goes out sealed under a DIFFERENT channel's key -- a different
// audience than the one the operator was looking at when they wrote it. And
// when a key is removed, the tab list rebuilds onto EVERYONE, so the same
// draft would have gone out under the default key, in public. The draft is
// discarded whenever the conversation under it changes; losing a half-typed
// line is a visible, harmless annoyance, and sending it to strangers is not.
std::uint32_t chat_draft_peer = 0xffffffffU;
char chat_draft_key_fp[8]{};

void chat_forget_draft_on_thread_change(std::uint32_t peer, const char *key_fp) noexcept
{
    const char *fp = key_fp != nullptr ? key_fp : "";
    if (chat_draft_len == 0U) {
        chat_draft_peer = peer;
        std::snprintf(chat_draft_key_fp, sizeof(chat_draft_key_fp), "%s", fp);
        return;
    }
    if (chat_draft_peer == peer && std::strcmp(chat_draft_key_fp, fp) == 0) return;
    chat_draft[0] = '\0';
    chat_draft_len = 0;
    chat_draft_peer = peer;
    std::snprintf(chat_draft_key_fp, sizeof(chat_draft_key_fp), "%s", fp);
}
