        case simulator::SimulatedProtocol::MeshCore: return "MCORE";
        case simulator::SimulatedProtocol::Reticulum: return "RNS";
        case simulator::SimulatedProtocol::Unknown:
        case simulator::SimulatedProtocol::Count:
