void draw_simulator_node_history(lv_obj_t *parent,
                                 const simulator::NodeSnapshot &node,
                                 lv_coord_t x, lv_coord_t y,
                                 lv_coord_t width, lv_coord_t height,
                                 lv_color_t color, bool rssi = false) noexcept
{
    const std::size_t sample_count = node.history_size < simulator::kNodeHistoryCapacity
        ? node.history_size : simulator::kNodeHistoryCapacity;
    if(sample_count == 0U) return;
    int values[simulator::kNodeHistoryCapacity]{};
    for(std::size_t index = 0U; index < sample_count; ++index) {
        const std::size_t age = sample_count - 1U - index;
        values[index] = rssi ? node.rssi(age) : node.snr(age);
    }
    const int low = rssi ? -1250 : -250;
    const int high = rssi ? -800 : 50;
    if (width >= 160) {
        draw_field_plot(parent, rssi ? 1 : 0, x, y, width, height, values, sample_count,
                        low, high, color, theme::text(), !rssi);
        return;
    }
    theme::rect(parent, x, y, width, height, lv_color_hex(0x040C0B));
    if (trace_buffer_index < trace_buffers.size()) {
        auto &points = trace_buffers[trace_buffer_index++];
        for (std::size_t index = 0; index < sample_count; ++index) {
            const int bar = plot_scale(values[index], low, high, height);
            points[index].x = sample_count == 1U ? 0 : static_cast<lv_coord_t>(
                (index * static_cast<std::size_t>(width - 1)) / (sample_count - 1U));
            points[index].y = static_cast<lv_coord_t>(height - 1 - bar);
        }
        lv_obj_t *line = lv_line_create(parent);
        theme::reset(line);
        lv_line_set_points(line, points.data(), static_cast<std::uint32_t>(sample_count));
        lv_obj_set_pos(line, x, y);
        lv_obj_set_size(line, width, height);
        lv_obj_set_style_line_color(line, color, 0);
        lv_obj_set_style_line_width(line, 2, 0);
    }
}
#endif

void ascii_upper(char *output, std::size_t capacity, const char *input) noexcept
{
    if (output == nullptr || capacity == 0U) return;
    std::size_t n = 0;
    if (input != nullptr) {
        for (; input[n] != '\0' && n + 1U < capacity; ++n) {
            const char c = input[n];
            output[n] = (c >= 'a' && c <= 'z') ? static_cast<char>(c - ('a' - 'A')) : c;
        }
    }
    output[n] = '\0';
}

lv_obj_t * put_label(lv_obj_t * parent, const char * value, lv_coord_t x, lv_coord_t y,
                     lv_color_t color = theme::text(), const lv_font_t * font = &font_condensed_12)
{
    lv_obj_t * object = theme::label(parent, value, color, font);
    lv_obj_set_pos(object, x, y);
    return object;
}

lv_obj_t * put_clipped_label(lv_obj_t * parent, const char * value, lv_coord_t x,
                             lv_coord_t y, lv_coord_t width,
                             lv_color_t color = theme::text(),
                             const lv_font_t * font = &font_condensed_12)
{
    lv_obj_t * object = put_label(parent, value, x, y, color, font);
    lv_obj_set_width(object, width);
    lv_obj_set_height(object, font->line_height);
    lv_label_set_long_mode(object, LV_LABEL_LONG_CLIP);
    return object;
}

void draw_outline_rect(lv_obj_t *parent, lv_coord_t x, lv_coord_t y, lv_coord_t width,
                       lv_coord_t height, lv_color_t color) noexcept
{
    theme::rule_line(parent, x, y, width, 1, color);
    theme::rule_line(parent, x, y + height - 1, width, 1, color);
    theme::rule_line(parent, x, y, 1, height, color);
    theme::rule_line(parent, x + width - 1, y, 1, height, color);
}

void draw_mode_chip(lv_obj_t *parent, lv_coord_t x, lv_coord_t y, lv_coord_t width,
                    lv_coord_t height, const char *label, bool selected,
                    bool enabled) noexcept
{
    const lv_color_t ink = !enabled ? theme::text_muted() :
                           (selected ? theme::pink() : theme::text());
    theme::rect(parent, x, y, width, height,
                selected && enabled ? lv_color_hex(0x180810) : lv_color_hex(0x050808));
    draw_outline_rect(parent, x, y, width, height, ink);
    const lv_coord_t text_w = static_cast<lv_coord_t>(std::strlen(label) * 6);
    put_label(parent, label, x + (width - text_w) / 2, y + 5, ink, &font_pixel_6x8);
}

void draw_spectrum_mode_chips(lv_obj_t *parent, bool enabled) noexcept
{
    const bool fast = spectrum_scan_mode == SpectrumScanMode::FastNarrow;
    draw_mode_chip(parent, kSpecFastX, kToolStripY, kSpecModeW, kToolChipH, "FAST",
                   fast, enabled);
    draw_mode_chip(parent, kSpecDeepX, kToolStripY, kSpecModeW, kToolChipH, "DEEP",
                   !fast, enabled);
}

/// Which destination a tap on the finished-capture row means. Kept pure and
/// beside the drawing constants so the boxes and the hit targets cannot drift
/// apart the way the chat scroll buttons once did.
Screen survey_action_screen(std::uint16_t x) noexcept
{
    if (x < static_cast<std::uint16_t>(8 + kSurveyActW)) return Screen::messages;
    if (x < static_cast<std::uint16_t>(8 + 2 * (kSurveyActW + 3))) return Screen::traffic;
    return Screen::nodes;
}

/// The three places a finished capture leads. Drawn only once there is
/// something to look at.
void draw_survey_result_actions(lv_obj_t *parent, bool ready) noexcept
{
    const lv_color_t ink = ready ? theme::pink() : theme::text_muted();
    // Not "FRAMES": that word is already a statistic three rows above, and a
    // button wearing the same label as a number reads like it shows that number.
    const std::array<const char *, 3> labels = {{"MESSAGES", "PACKETS", "NODES"}};
    for (std::size_t index = 0; index < labels.size(); ++index) {
        const lv_coord_t x = 8 + static_cast<lv_coord_t>(index) * (kSurveyActW + 3);
        draw_outline_rect(parent, x, kSurveyActY, kSurveyActW, kSurveyActH, ink);
        const lv_coord_t text_w = static_cast<lv_coord_t>(std::strlen(labels[index]) * 6);
        put_label(parent, labels[index], x + (kSurveyActW - text_w) / 2, kSurveyActY + 7,
                  ink, &font_pixel_6x8);
    }
}

void draw_start_stop_strip(lv_obj_t *parent, const char *status, lv_color_t status_color,
                           const char *chip, bool enabled, bool armed = false,
                           lv_coord_t status_x = 8) noexcept
{
    theme::rect(parent, 0, kToolStripY, 320, 20, lv_color_hex(0x050808));
    if (status != nullptr && status[0] != '\0') {
        put_clipped_label(parent, status, status_x, kToolStripY + 6,
                          kToolChipX - status_x - 4, status_color, &font_pixel_6x8);
    }
    const lv_color_t ink = !enabled ? theme::text_muted() :
                           (armed ? theme::amber() : theme::pink());
    const char *label = chip;
    if (std::strcmp(chip, "START") == 0) label = "START";
    else if (std::strcmp(chip, "STOP") == 0) label = "STOP";
    draw_outline_rect(parent, kToolChipX, kToolStripY, kToolChipW, kToolChipH, ink);
    const lv_coord_t text_w = static_cast<lv_coord_t>(std::strlen(label) * 6);
    put_label(parent, label, kToolChipX + (kToolChipW - text_w) / 2, kToolStripY + 5,
              ink, &font_pixel_6x8);
}

void draw_spectrum_action_strip(lv_obj_t *parent, const char *status, lv_color_t status_color,
                                const char *chip, bool enabled, bool armed,
                                bool modes_enabled) noexcept
{
    draw_start_stop_strip(parent, status, status_color, chip, enabled, armed, 118);
    draw_spectrum_mode_chips(parent, modes_enabled);
}

void draw_back_strip(lv_obj_t *parent, const char *note = nullptr) noexcept
{
    theme::rect(parent, 0, kEventBackY, 320, 20, lv_color_hex(0x050808));
    draw_outline_rect(parent, kEventBackX, kEventBackY, kEventBackW, kEventBackH, theme::pink());
    put_label(parent, "BACK", kEventBackX + 4, kEventBackY + 5, theme::pink(),
              &font_pixel_6x8);
    if (note != nullptr && note[0] != '\0') {
        put_clipped_label(parent, note, 72, kEventBackY + 6, 240,
                          theme::text_muted(), &font_pixel_6x8);
    }
}

bool field_chrome_active() noexcept
{
    const ShellRoute route = app_shell.route();
    if (route == ShellRoute::Splash || isOnboardingRoute(route)) return false;
    if (route == ShellRoute::SpectrumConfirmation ||
        route == ShellRoute::ResetConfirmation) {
        return false;
    }
    return true;
}

void add_field_nav(lv_obj_t *parent, FieldTab active) noexcept
{
    theme::rect(parent, 0, theme::nav_top, theme::screen_width, theme::nav_height,
                lv_color_hex(0x050808));
    theme::rule_line(parent, 0, theme::nav_top, theme::screen_width, 1, theme::pink());
    const char *labels[] = {"HOME", "NODES", "MAP", "CHAT", "RADIO"};
    if (active == FieldTab::Radio && app_shell.route() == ShellRoute::Analyzer &&
        !chat_open) {
        if (current_screen == Screen::spectrum) labels[4] = "SPEC";
        else if (current_screen == Screen::survey) labels[4] = "SURV";
        else if (current_screen == Screen::utilization) labels[4] = "AIR";
        else if (current_screen == Screen::events) labels[4] = "EVNT";
        else if (current_screen == Screen::protocols ||
                 current_screen == Screen::protocol_detail) {
            labels[4] = "PROTO";
        } else if (current_screen == Screen::timeline) labels[4] = "TIME";
        else if (current_screen == Screen::traffic_filter) labels[4] = "FILT";
    }
    const std::size_t active_index = static_cast<std::size_t>(active);
    for (std::size_t index = 0; index < 5U; ++index) {
        const lv_coord_t x = static_cast<lv_coord_t>(index) * theme::tab_width;
        const bool selected = index == active_index;
        if (selected) {
            draw_outline_rect(parent, x, theme::nav_top, theme::tab_width,
                              theme::nav_height, theme::pink());
        }
        const lv_coord_t text_w = static_cast<lv_coord_t>(std::strlen(labels[index]) * 6);
        const lv_coord_t text_x = x + (theme::tab_width - text_w) / 2;
        put_label(parent, labels[index], text_x, 229,
                  selected ? theme::pink() : theme::text_muted(),
                  &font_pixel_6x8);
        if (index == 3U && chat_unread > 0U) {
            const lv_coord_t badge_x = x + theme::tab_width - 14;
            theme::rect(parent, badge_x, 228, 12, 10, theme::pink());
            char badge[4]{};
            if (chat_unread < 10U) {
                std::snprintf(badge, sizeof(badge), "%u",
                              static_cast<unsigned>(chat_unread));
            } else {
                std::snprintf(badge, sizeof(badge), "+");
            }
            put_label(parent, badge, badge_x + 3, 229, theme::on_accent(),
                      &font_pixel_6x8);
        }
    }
}

void add_status_bar(lv_obj_t * parent, const char * title, const char * left_value = "BAT 100%",
                    const char * middle_value = "GPS LOCK", const char * right_value = "18 PKT/MIN")
{
    lv_color_t middle_color = theme::text();
    lv_color_t right_color = theme::text();
#if defined(LILYSHARK_DEVICE)
    left_value = live_battery_label;
    if(app_settings.simulate_mode) {
        middle_value = "SIM MODE";
        middle_color = theme::amber();
    } else {
        // The bar answers one question: do I have a position, yes or no.
        // "SEARCH" versus "FIX" versus "N/A" made the operator decode radio
        // states to find that out. Device Status still carries the detail.
        const GpsStatus &bar_gps = hardware_status.snapshot().gps;
        const bool located = bar_gps.state == GpsState::Fix && bar_gps.position_valid;
        middle_value = located ? "GPS ON" : "GPS OFF";
        middle_color = located ? theme::lime() : theme::fault();
    }
    // The web analyzer is attached to this device right now; say so where the
    // user is already looking, not only in the event log.
    if(analyzer_link_active) {
        right_value = "USB LINKED";
        right_color = theme::cyan();
    } else {
        right_value = live_radio_label;
    }
#endif
    lv_obj_t * bar = theme::rect(parent, 0, 0, theme::screen_width, theme::status_height, theme::surface());
    theme::rule_line(bar, 0, theme::status_height - 1, theme::screen_width);

#if defined(LILYSHARK_DEVICE)
    // An arrived message takes the whole bar until it expires or the operator
    // opens the conversation. Every screen draws this bar, so there is nowhere
    // to be standing where the alert does not reach.
    if(chat_notice_until_ms != 0U) {
        if(static_cast<std::int32_t>(millis() - chat_notice_until_ms) >= 0) {
            chat_notice_until_ms = 0;
            // One more redraw so the bar returns to battery/GPS/radio rather
            // than holding an expired alert until something else happens.
            live_data_dirty = true;
            if(std::strncmp(shell_notice, "NEW MESSAGE", 11) == 0) shell_notice[0] = '\0';
        } else if(std::strncmp(shell_notice, "NEW MESSAGE", 11) == 0) {
            theme::rect(bar, 0, 0, theme::screen_width, theme::status_height - 1,
                        theme::pink());
            put_clipped_label(bar, shell_notice, 6, 3, 236, theme::on_accent(),
                              &font_mono_semibold_12);
            put_label(bar, "CHAT", 266, 4, theme::on_accent(), &font_mono_semibold_12);
            return;
        }
    }
#endif

    put_clipped_label(bar, title, 4, 2, 86, theme::pink(), &font_condensed_bold_16);
    put_label(bar, left_value, 94, 4, theme::text(), &font_mono_semibold_12);
    theme::rule_line(bar, 160, 3, 1, 15, theme::rule());
    put_label(bar, middle_value, 170, 4, middle_color, &font_mono_semibold_12);
    theme::rule_line(bar, 236, 3, 1, 15, theme::rule());
    put_clipped_label(bar, right_value, 246, 4, 70, right_color, &font_mono_semibold_12);
}

void add_gear_status(lv_obj_t *parent, const char *title) noexcept
{
#if defined(LILYSHARK_DEVICE)
    add_status_bar(parent, title);
#else
    add_simulator_live_status_bar(parent, title);
#endif
}

