lv_obj_t * add_wordmark(lv_obj_t * parent, lv_coord_t x, lv_coord_t y,
                        std::uint32_t scale = LV_SCALE_NONE)
{
    lv_obj_t * logo = lv_image_create(parent);
    lv_image_set_src(logo, &lilyshark_wordmark_a8);
    lv_obj_set_style_image_recolor(logo, theme::pink(), 0);
    lv_obj_set_style_image_recolor_opa(logo, LV_OPA_COVER, 0);
    if(scale != LV_SCALE_NONE) lv_image_set_scale(logo, scale);
    lv_obj_set_pos(logo, x, y);
    return logo;
}

lv_obj_t * add_scaled_wordmark(lv_obj_t * parent, lv_coord_t left, lv_coord_t top,
                               lv_coord_t visual_width)
{
    const std::uint32_t scale = static_cast<std::uint32_t>(visual_width) * LV_SCALE_NONE /
                                LILYSHARK_WORDMARK_A8_WIDTH;
    const lv_coord_t visual_height = static_cast<lv_coord_t>(
        (LILYSHARK_WORDMARK_A8_HEIGHT * scale) / LV_SCALE_NONE);
    const lv_coord_t object_x = left -
        (static_cast<lv_coord_t>(LILYSHARK_WORDMARK_A8_WIDTH) - visual_width) / 2;
    const lv_coord_t object_y = top -
        (static_cast<lv_coord_t>(LILYSHARK_WORDMARK_A8_HEIGHT) - visual_height) / 2;
    return add_wordmark(parent, object_x, object_y, scale);
}

void draw_pixel_line(lv_obj_t * parent, lv_coord_t x, lv_coord_t y, lv_coord_t width,
                     lv_coord_t height, uint8_t seed, lv_color_t color, bool bars = false)
{
    if(width < 2 || height < 2) return;

    if(trace_buffer_index >= trace_buffers.size()) return;
    auto & points = trace_buffers[trace_buffer_index++];
    const lv_coord_t step = width > 150 ? 2 : 3;
    size_t point_count = 0;
    for(lv_coord_t px = 0; px < width && point_count < points.size(); px += step) {
        const uint32_t hash = static_cast<uint32_t>((px + seed * 17) * 1103515245u + seed * 12345u);
        const lv_coord_t jitter = static_cast<lv_coord_t>((hash >> 27) % static_cast<uint32_t>(height - 2));
        points[point_count++] = {px, static_cast<lv_coord_t>(1 + jitter)};
    }

    lv_obj_t * line = lv_line_create(parent);
    theme::reset(line);
    lv_line_set_points(line, points.data(), static_cast<uint32_t>(point_count));
    lv_obj_set_pos(line, x, y);
    lv_obj_set_size(line, width, height);
    lv_obj_set_style_line_color(line, color, 0);
    lv_obj_set_style_line_width(line, bars ? 1 : 1, 0);
    lv_obj_set_style_line_rounded(line, false, 0);

    if(bars) {
        for(size_t index = 0; index < point_count; index += 4) {
            const lv_coord_t bar_x = x + static_cast<lv_coord_t>(points[index].x);
            const lv_coord_t bar_y = y + static_cast<lv_coord_t>(points[index].y);
            theme::rect(parent, bar_x, bar_y, 1, y + height - bar_y, color);
        }
    }
}

void add_grid(lv_obj_t * parent, lv_coord_t x, lv_coord_t y, lv_coord_t width, lv_coord_t height,
              lv_coord_t x_step, lv_coord_t y_step)
{
    for(lv_coord_t px = x; px <= x + width; px += x_step) theme::rule_line(parent, px, y, 1, height, theme::grid());
    for(lv_coord_t py = y; py <= y + height; py += y_step) theme::rule_line(parent, x, py, width, 1, theme::grid());
}

int plot_scale(int value, int low, int high, int height) noexcept
{
    if (high <= low || height <= 1) return 0;
    int bar = ((value - low) * (height - 1)) / (high - low);
    if (bar < 0) bar = 0;
    if (bar > height - 1) bar = height - 1;
    return bar;
}

int plot_sample_at(const int *values, std::size_t count, int column, int columns) noexcept
{
    if (values == nullptr || count == 0U || columns <= 0) return 0;
    if (count == 1U) return values[0];
    if (columns == 1) return values[count - 1U];
    const int span = static_cast<int>(count - 1U);
    const int num = column * span;
    const int den = columns - 1;
    const int i0 = num / den;
    const int i1 = i0 + 1 < static_cast<int>(count) ? i0 + 1 : i0;
    const int frac = num - i0 * den;
    return (values[i0] * (den - frac) + values[i1] * frac) / den;
}

void draw_plot_columns(lv_obj_t *parent, lv_coord_t x, lv_coord_t y, lv_coord_t width,
                       lv_coord_t height, const int *values, std::size_t count,
                       int low, int high, lv_color_t fill, lv_color_t tip) noexcept
{
    if (count == 0U || width < 2 || height < 4) return;
    int columns = width;
    int col_w = 1;
    if (columns > 96) {
        col_w = 2;
        columns = width / 2;
    }
    if (columns > 120) columns = 120;
    int prev_top = -1;
    for (int column = 0; column < columns; ++column) {
        const int value = plot_sample_at(values, count, column, columns);
        const int bar = plot_scale(value, low, high, height);
        const lv_coord_t px = x + static_cast<lv_coord_t>((column * width) / columns);
        const lv_coord_t top = y + height - static_cast<lv_coord_t>(bar);
        if (prev_top >= 0) {
            const lv_coord_t lo = prev_top < top ? prev_top : top;
            const lv_coord_t hi = prev_top > top ? prev_top : top;
            theme::rect(parent, px, lo, static_cast<lv_coord_t>(col_w),
                        hi - lo + 1, fill);
        }
        theme::rect(parent, px, top, static_cast<lv_coord_t>(col_w), 2, tip);
        prev_top = top;
    }
}

void draw_field_plot(lv_obj_t *parent, int slot, lv_coord_t x, lv_coord_t y,
                     lv_coord_t width, lv_coord_t height, const int *values,
                     std::size_t count, int low, int high, lv_color_t fill,
                     lv_color_t tip, bool mark_zero) noexcept
{
    if (width < 8 || height < 8 || width > kPlotMaxW || height > kPlotMaxH) return;
    std::uint16_t *pixels = plot_pixels(slot);
    if (pixels == nullptr) {
        theme::rect(parent, x, y, width, height, lv_color_hex(0x040C0B));
        for (lv_coord_t gy = y + 8; gy < y + height; gy += 8) {
            theme::rect(parent, x, gy, width, 1, lv_color_hex(0x142826));
        }
        draw_plot_columns(parent, x, y, width, height, values, count, low, high, fill, tip);
        return;
    }
    const std::uint16_t bg = lv_color_to_u16(lv_color_hex(0x040C0B));
    const std::uint16_t grid = lv_color_to_u16(lv_color_hex(0x142826));
    const std::uint16_t axis = lv_color_to_u16(lv_color_hex(0x2A4A46));
    const std::uint16_t body = lv_color_to_u16(fill);
    const std::uint16_t cap = lv_color_to_u16(tip);
    const std::uint16_t stem = lv_color_to_u16(lv_color_mix(fill, lv_color_hex(0x040C0B), 160));
    const int stride = width;
    for (int row = 0; row < height; ++row) {
        std::uint16_t *line = pixels + row * stride;
        const std::uint16_t row_color = (row % 8 == 0) ? grid : bg;
        for (int col = 0; col < width; ++col) line[col] = row_color;
    }
    if (mark_zero && low < 0 && high > 0) {
        const int zero_y = height - 1 - plot_scale(0, low, high, height);
        if (zero_y >= 0 && zero_y < height) {
            std::uint16_t *line = pixels + zero_y * stride;
            for (int col = 0; col < width; ++col) line[col] = axis;
        }
    }
    if (count > 0U) {
        int prev_y = -1;
        for (int col = 0; col < width; ++col) {
            const int value = plot_sample_at(values, count, col, width);
            const int bar = plot_scale(value, low, high, height);
            const int y0 = height - 1 - bar;
            if (prev_y >= 0) {
                const int lo = prev_y < y0 ? prev_y : y0;
                const int hi = prev_y > y0 ? prev_y : y0;
                for (int row = lo; row <= hi && row < height; ++row) {
                    pixels[row * stride + col] = body;
                }
            }
            for (int row = y0; row <= y0 + 3 && row < height; ++row) {
                pixels[row * stride + col] = stem;
            }
            if (y0 >= 0 && y0 < height) pixels[y0 * stride + col] = cap;
            if (y0 > 0) pixels[(y0 - 1) * stride + col] = cap;
            prev_y = y0;
        }
    }
    lv_obj_t *canvas = lv_canvas_create(parent);
    theme::reset(canvas);
    lv_canvas_set_buffer(canvas, pixels, width, height, LV_COLOR_FORMAT_RGB565);
    lv_obj_set_pos(canvas, x, y);
}

void draw_linear_gauge(lv_obj_t *parent, lv_coord_t x, lv_coord_t y, lv_coord_t width,
                       lv_coord_t height, int value, int low, int high,
                       lv_color_t fill) noexcept
{
    theme::rect(parent, x, y, width, height, lv_color_hex(0x040C0B));
    draw_outline_rect(parent, x, y, width, height, theme::grid());
    const int fill_w = plot_scale(value, low, high, width);
    if (fill_w > 1) {
        theme::rect(parent, x + 1, y + 2, static_cast<lv_coord_t>(fill_w - 1),
                    height - 4, fill);
        theme::rect(parent, x + static_cast<lv_coord_t>(fill_w) - 1, y + 1, 2,
                    height - 2, theme::text());
    }
    for (int tick = 1; tick < 10; ++tick) {
        const lv_coord_t tx = x + static_cast<lv_coord_t>((tick * (width - 1)) / 10);
        theme::rect(parent, tx, y + height - 4, 1, 3, theme::rule());
    }
}

// The unit circle a ring is drawn from, as exact float literals.
//
// These points become an anti-aliased LVGL line, so a last-ulp difference in
// std::cos does not merely move a point -- it changes the coverage the
// rasteriser computes, and therefore the intensity of neighbouring pixels. On
// a test that hashes exact pixels that is the difference between passing on
// macOS and failing on Linux, which is precisely what Home's compass was
// doing. Literals parse identically everywhere; libm does not.
constexpr std::size_t kRingSegments = 36;
constexpr float kRingCos[kRingSegments + 1] = {
    1.0f, 0.9848077297210693f, 0.9396926164627075f, 0.8660253882408142f,
    0.7660444378852844f, 0.6427876353263855f, 0.5f, 0.3420201539993286f,
    0.1736481785774231f, 6.123234262925839e-17f, -0.1736481785774231f,
    -0.3420201539993286f, -0.5f, -0.6427876353263855f, -0.7660444378852844f,
    -0.8660253882408142f, -0.9396926164627075f, -0.9848077297210693f, -1.0f,
    -0.9848077297210693f, -0.9396926164627075f, -0.8660253882408142f, -0.7660444378852844f,
    -0.6427876353263855f, -0.5f, -0.3420201539993286f, -0.1736481785774231f,
    -1.8369701465288538e-16f, 0.1736481785774231f, 0.3420201539993286f, 0.5f,
    0.6427876353263855f, 0.7660444378852844f, 0.8660253882408142f, 0.9396926164627075f,
    0.9848077297210693f, 1.0f
};
constexpr float kRingSin[kRingSegments + 1] = {
    0.0f, 0.1736481785774231f, 0.3420201539993286f, 0.5f, 0.6427876353263855f,
    0.7660444378852844f, 0.8660253882408142f, 0.9396926164627075f, 0.9848077297210693f,
    1.0f, 0.9848077297210693f, 0.9396926164627075f, 0.8660253882408142f,
    0.7660444378852844f, 0.6427876353263855f, 0.5f, 0.3420201539993286f,
    0.1736481785774231f, 1.2246468525851679e-16f, -0.1736481785774231f,
    -0.3420201539993286f, -0.5f, -0.6427876353263855f, -0.7660444378852844f,
    -0.8660253882408142f, -0.9396926164627075f, -0.9848077297210693f, -1.0f,
    -0.9848077297210693f, -0.9396926164627075f, -0.8660253882408142f, -0.7660444378852844f,
    -0.6427876353263855f, -0.5f, -0.3420201539993286f, -0.1736481785774231f,
    -2.4492937051703357e-16f
};

void draw_map_ring(lv_obj_t *parent, lv_coord_t cx, lv_coord_t cy, lv_coord_t radius,
                   lv_color_t color, lv_coord_t width = 1) noexcept
{
    if (radius < 3 || trace_buffer_index >= trace_buffers.size()) return;
    auto &points = trace_buffers[trace_buffer_index++];
    constexpr std::size_t kSeg = kRingSegments;
    for (std::size_t index = 0; index <= kSeg; ++index) {
        points[index].x = static_cast<float>(cx) + static_cast<float>(radius) * kRingCos[index];
        points[index].y = static_cast<float>(cy) + static_cast<float>(radius) * kRingSin[index];
    }
    lv_obj_t *line = lv_line_create(parent);
    theme::reset(line);
    lv_line_set_points(line, points.data(), static_cast<std::uint32_t>(kSeg + 1U));
    lv_obj_set_pos(line, 0, 0);
    lv_obj_set_style_line_color(line, color, 0);
    lv_obj_set_style_line_width(line, width < 1 ? 1 : width, 0);
}

void draw_map_segment(lv_obj_t *parent, lv_coord_t x0, lv_coord_t y0, lv_coord_t x1,
                      lv_coord_t y1, lv_color_t color) noexcept
{
    if (trace_buffer_index >= trace_buffers.size()) return;
    auto &points = trace_buffers[trace_buffer_index++];
    points[0].x = static_cast<float>(x0);
    points[0].y = static_cast<float>(y0);
    points[1].x = static_cast<float>(x1);
    points[1].y = static_cast<float>(y1);
    lv_obj_t *line = lv_line_create(parent);
    theme::reset(line);
    lv_line_set_points(line, points.data(), 2U);
    lv_obj_set_pos(line, 0, 0);
    lv_obj_set_style_line_color(line, color, 0);
    lv_obj_set_style_line_width(line, 1, 0);
}

void draw_map_chevron(lv_obj_t *parent, lv_coord_t x, lv_coord_t y, double east_m,
                      double north_m) noexcept
{
    const double len = std::hypot(east_m, north_m);
    if (len < 1.0) return;
    const double ux = east_m / len;
    const double uy = -north_m / len;
    const lv_coord_t ax = static_cast<lv_coord_t>(std::lround(static_cast<double>(x) - ux * 7.0 + uy * 4.0));
    const lv_coord_t ay = static_cast<lv_coord_t>(std::lround(static_cast<double>(y) - uy * 7.0 - ux * 4.0));
    const lv_coord_t bx = static_cast<lv_coord_t>(std::lround(static_cast<double>(x) - ux * 7.0 - uy * 4.0));
    const lv_coord_t by = static_cast<lv_coord_t>(std::lround(static_cast<double>(y) - uy * 7.0 + ux * 4.0));
    draw_map_segment(parent, ax, ay, x, y, theme::pink());
    draw_map_segment(parent, bx, by, x, y, theme::pink());
}

/// A raw 1 Hz fix wanders by metres even when standing still, and at a zoom
/// where the screen is forty metres across that wander is the whole picture.
/// This averages the recent fixes so the marker sits still, and snaps to the
/// new position when the jump is too large to be noise — that is walking, not
/// jitter.
void map_smooth_position(double raw_lat, double raw_lon, double &out_lat,
                         double &out_lon) noexcept
{
    static double smooth_lat = 0.0;
    static double smooth_lon = 0.0;
    static bool have_smooth = false;

    if (!have_smooth) {
        smooth_lat = raw_lat;
        smooth_lon = raw_lon;
        have_smooth = true;
    } else {
        const double lat_rad = smooth_lat * 0.017453292519943295;
        const double de = (raw_lon - smooth_lon) * 111320.0 * std::cos(lat_rad);
        const double dn = (raw_lat - smooth_lat) * 110540.0;
        if (std::hypot(de, dn) > 15.0) {
            smooth_lat = raw_lat;
            smooth_lon = raw_lon;
        } else {
            constexpr double kBlend = 0.25;
            smooth_lat += (raw_lat - smooth_lat) * kBlend;
            smooth_lon += (raw_lon - smooth_lon) * kBlend;
        }
    }
    out_lat = smooth_lat;
    out_lon = smooth_lon;
}

double map_fix_accuracy_m(float hdop, std::uint8_t satellites) noexcept
{
    double meters = 0.0;
    if (hdop > 0.05f) {
        meters = static_cast<double>(hdop) * 5.0;
    } else if (satellites > 0U) {
        const int extra = satellites > 4U ? static_cast<int>(satellites) - 4 : 0;
        meters = 25.0 - static_cast<double>(extra) * 2.0;
        if (meters < 8.0) meters = 8.0;
    } else {
        return 0.0;
    }
    if (meters < 5.0) meters = 5.0;
    if (meters > 120.0) meters = 120.0;
    return meters;
}

void format_map_range(char *output, std::size_t capacity, double meters) noexcept
{
    if (output == nullptr || capacity == 0U) return;
    if (meters < 1.0) {
        std::snprintf(output, capacity, "<1M");
    } else if (meters >= 10000.0) {
        std::snprintf(output, capacity, "%.0fKM", meters / 1000.0);
    } else if (meters >= 1000.0) {
        std::snprintf(output, capacity, "%.1fKM", meters / 1000.0);
    } else {
        std::snprintf(output, capacity, "%.0fM", meters);
    }
}

void format_hemisphere_fix(char *output, std::size_t capacity, double lat,
                           double lon) noexcept
{
    if (output == nullptr || capacity == 0U) return;
    std::snprintf(output, capacity, "%.4f %c  %.3f %c",
                  std::abs(lat), lat >= 0.0 ? 'N' : 'S',
                  std::abs(lon), lon >= 0.0 ? 'E' : 'W');
}

double map_bearing_deg(double east_m, double north_m) noexcept
{
    double deg = std::atan2(east_m, north_m) * (180.0 / 3.141592653589793);
    if (deg < 0.0) deg += 360.0;
    return deg;
}

void field_local_meters(double from_lat, double from_lon, double to_lat, double to_lon,
                        double &east_m, double &north_m) noexcept
{
    const double lat_rad = from_lat * 0.017453292519943295;
    east_m = (to_lon - from_lon) * 111320.0 * std::cos(lat_rad);
    north_m = (to_lat - from_lat) * 110540.0;
}

bool field_peer_fix(std::size_t raw_index, double &lat, double &lon) noexcept
{
    if (raw_index >= kFieldPeers.size()) return false;
    lat = kFieldPeers[raw_index].lat;
    lon = kFieldPeers[raw_index].lon;
    return true;
}

