const char *spectrum_scan_mode_label() noexcept
{
    return spectrum_scan_mode == SpectrumScanMode::FastNarrow ? "FAST NARROW" : "DEEP BAND";
}

bool apply_spectrum_scan_mode(SpectrumScanMode next) noexcept
{
#if defined(LILYSHARK_DEVICE)
    if (radio_service.spectrumStatus().active()) return false;
#else
    if (simulator_spectrum_scanning) return false;
#endif
    if (next == spectrum_scan_mode) return false;
    spectrum_scan_mode = next;
#if defined(LILYSHARK_DEVICE)
    radio_service.clearSpectrumResult();
#else
    simulator_spectrum_partial_points = 0U;
    simulator_spectrum_cancelled = false;
    simulator_spectrum_started_ms = simulator_live_telemetry.elapsedMilliseconds();
#endif
    return true;
}

bool apply_map_layer(bool satellite, bool chart) noexcept
{
    if (chart) {
        if (map_chart) return false;
        map_chart = true;
        return true;
    }
    if (map_satellite == satellite && !map_chart) return false;
    map_satellite = satellite;
    map_chart = false;
    return true;
}

/// SAT -> ROADS -> GRID -> SAT. The chip shows where you are in that cycle.
bool cycle_map_layer() noexcept
{
    if (map_chart) return apply_map_layer(true, false);
    if (map_satellite) return apply_map_layer(false, false);
    return apply_map_layer(false, true);
}

bool apply_timeline_filter(std::size_t next) noexcept
{
    next %= 5U;
    if (next == timeline_filter_selection) return false;
    timeline_filter_selection = next;
    return true;
}

