void draw_radio_range_footer(lv_obj_t *parent, std::size_t first, std::size_t visible,
                             std::size_t count) noexcept
{
    if (count <= kRadioVisible) return;
    char line[24]{};
    std::snprintf(line, sizeof(line), "%u-%u / %u",
                  static_cast<unsigned>(first + 1U),
                  static_cast<unsigned>(first + visible),
                  static_cast<unsigned>(count));
    theme::rect(parent, 0, kRadioFooterY, 320, 18, lv_color_hex(0x050808));
    put_label(parent, line, 8, kRadioFooterY + 5, theme::pink(), &font_pixel_6x8);
    draw_up_down_chips(parent, kRadioFooterY + 3, first > 0U, first + visible < count);
}

void draw_radio_listen_card(lv_obj_t *parent, const char *title, lv_color_t title_color,
                            const RadioProfile &profile, const char *hint) noexcept
{
    draw_outline_rect(parent, 8, 40, 304, 148, theme::pink());
    put_label(parent, title, 16, 48, title_color, &font_pixel_6x8);
    put_clipped_label(parent, home_profile_tag(profile), 16, 64, 280, theme::text(),
                      &font_pixel_6x8);
    char freq[16]{};
    std::snprintf(freq, sizeof(freq), "%.3f",
                  static_cast<double>(profile.center_frequency_hz) / 1000000.0);
    put_label(parent, freq, 16, 78, theme::cyan(), &font_pixel_18x24);
    put_label(parent, "MHZ", 152, 90, theme::text_muted(), &font_pixel_6x8);
    char params[48]{};
    std::snprintf(params, sizeof(params), "BW %uk  SF%u  CR 4/%u  SYNC %04X",
                  static_cast<unsigned>(profile.bandwidth_hz / 1000U),
                  profile.spreading_factor, profile.coding_rate_denominator,
                  profile.sync_word);
    put_label(parent, params, 16, 110, theme::text(), &font_pixel_6x8);
    put_label(parent, hint, 16, 164, theme::text_muted(), &font_pixel_6x8);
}

void draw_radio_tools(lv_obj_t *parent) noexcept
{
    theme::rect(parent, 0, kRadioToolY, 320, 20, lv_color_hex(0x050808));
    const auto chip = [parent](lv_coord_t x, const char *label, bool selected = false) {
        draw_mode_chip(parent, x, kRadioToolY, kRadioToolW, kRadioToolH, label,
                       selected, true);
    };
    chip(4, "SPECTRUM");
    chip(66, "SURVEY");
    chip(128, "AIRTIME");
    chip(190, "EVENTS");
    chip(252, "FILTER", traffic_filter.active());
}

void open_radio_tool(Screen screen) noexcept
{
    current_screen = screen;
    if (screen == Screen::events) {
        events_scroll_offset = 0U;
        event_detail_open = false;
    }
    field_tab = FieldTab::Radio;
    app_shell.closeToAnalyzer();
    remember_primary_screen(current_screen);
    build_current_screen();
}

void build_traffic(lv_obj_t * parent)
{
#if defined(LILYSHARK_DEVICE)
    add_status_bar(parent, traffic_filter.active() ? "RADIO *" : "RADIO");
    constexpr lv_coord_t first_y = kRadioFirstY;
    constexpr lv_coord_t row_height = kRadioRowH;
    const auto &store = capture_runtime.frames();

    if(store.empty()) {
        draw_radio_listen_card(parent,
                               app_settings.simulate_mode ? "GENERATING SYNTHETIC FRAMES" :
                                                            "LISTENING FOR FRAMES",
                               app_settings.simulate_mode ? theme::amber() : theme::lime(),
                               radio_service.activeProfile(),
                               "NAMES APPEAR AFTER A PACKET LANDS.");
        draw_radio_tools(parent);
        return;
    }

    const TrafficFilterSnapshot filtered = trafficFilterSnapshot(store, traffic_filter);
    if(filtered.matching_frames == 0U) {
        put_centered_label(parent, "NO FRAMES MATCH THIS FILTER", 86,
                           theme::amber(), &font_pixel_6x8);
        char summary[64]{};
        (void)formatTrafficFilterSummary(summary, sizeof(summary), traffic_filter);
        put_centered_label(parent, summary, 108, theme::text_muted(), &font_mono_10);
        draw_radio_tools(parent);
        return;
    }
    draw_radio_headers(parent);
    const std::size_t selected_offset = resolve_traffic_selection();
    const std::size_t maximum_visible = filtered.matching_frames < kRadioVisible
        ? filtered.matching_frames : kRadioVisible;
    const std::size_t first_offset = selected_offset < maximum_visible
        ? 0 : selected_offset - maximum_visible + 1;
    const std::size_t visible = (filtered.matching_frames - first_offset) < maximum_visible
        ? filtered.matching_frames - first_offset : maximum_visible;
    for(std::size_t index = 0; index < visible; ++index) {
        const std::size_t offset = first_offset + index;
        const FrameRecord *record = newestMatchingFrame(store, traffic_filter, offset);
        if(record == nullptr) continue;
        const lv_coord_t y = first_y + static_cast<lv_coord_t>(index) * row_height;
        const bool selected = offset == selected_offset;
        if(selected) {
            theme::rect(parent, 0, y - 1, 320, row_height, lv_color_hex(0x0C1A18));
            theme::rect(parent, 0, y - 1, 3, row_height, theme::pink());
        }

        const bool malformed = record->decoded.state == DecodeState::Malformed;
        const lv_color_t row_color = selected ? theme::text() :
            ((record->raw.rf.crc == CrcStatus::Invalid || malformed)
                 ? theme::fault() : theme::lime());
        char time[12]{};
        char source[12]{};
        char destination[12]{};
        char hops[5]{};
        char snr[10]{};
        format_capture_time(time, sizeof(time), record->raw.rf.timestamp_us);
        format_radio_field_node(source, sizeof(source), record->decoded, FieldSource);
        format_radio_field_node(destination, sizeof(destination), record->decoded, FieldDestination);
        if(record->decoded.hasField(FieldHopStart) && record->decoded.hasField(FieldHopLimit) &&
           record->decoded.hop_start >= record->decoded.hop_limit) {
            std::snprintf(hops, sizeof(hops), "%u", record->decoded.hop_start - record->decoded.hop_limit);
        } else {
            std::snprintf(hops, sizeof(hops), "-");
        }
        std::snprintf(snr, sizeof(snr), "%+.1f", static_cast<double>(record->raw.rf.snr_db_x10) / 10.0);

        put_label(parent, time, kRadioTimeX, y, row_color, &font_mono_10);
        if(record->raw.rf.origin == FrameOrigin::Synthetic) {
            put_label(parent, "S", kRadioSrcX - 8, y,
                      selected ? theme::text() : theme::pink(), &font_mono_10);
        }
        put_clipped_label(parent, source, kRadioSrcX, y, kRadioSrcW, row_color, &font_mono_10);
        put_clipped_label(parent, destination, kRadioDstX, y, kRadioDstW, row_color,
                          &font_mono_10);
        put_label(parent, home_protocol_tag(record->decoded.protocol), kRadioPrX, y,
                  selected ? theme::pink() : theme::cyan(), &font_mono_10);
        put_label(parent, packetKindLabel(record->decoded), kRadioKindX, y, row_color,
                  &font_mono_10);
        put_label(parent, hops, kRadioHX, y, row_color, &font_mono_10);
        put_label(parent, snr, kRadioSnrX, y, row_color, &font_mono_10);
    }
    draw_radio_range_footer(parent, first_offset, visible, filtered.matching_frames);
    draw_radio_tools(parent);
#else
    add_simulator_live_status_bar(parent, traffic_filter.active() ? "RADIO *" : "RADIO");
    constexpr lv_coord_t first_y = kRadioFirstY;
    constexpr lv_coord_t row_height = kRadioRowH;
    const std::size_t matching_count = simulator_matching_sample_count();
    if(matching_count == 0U) {
        draw_radio_listen_card(parent,
                               traffic_filter.active() ? "NO FRAMES MATCH THIS FILTER" :
                                                         "LISTENING FOR FRAMES",
                               traffic_filter.active() ? theme::amber() : theme::lime(),
                               shell_active_profile(),
                               traffic_filter.active() ?
                                   "CLEAR THE FILTER TO SEE EVERY CAPTURED FRAME." :
                                   "NAMES APPEAR AFTER A PACKET LANDS.");
        draw_radio_tools(parent);
        return;
    }
    draw_radio_headers(parent);
    const std::size_t selected_offset = resolve_simulator_traffic_selection();
    const std::size_t maximum_visible = matching_count < kRadioVisible ? matching_count : kRadioVisible;
    const std::size_t first_offset = selected_offset < maximum_visible
        ? 0U : selected_offset - maximum_visible + 1U;
    const std::size_t visible = (matching_count - first_offset) < maximum_visible
        ? matching_count - first_offset : maximum_visible;
    for(std::size_t index = 0U; index < visible; ++index) {
        const std::size_t offset = first_offset + index;
        const simulator::TrafficSample *sample = simulator_matching_sample(offset);
        if(sample == nullptr) continue;
        const lv_coord_t y = first_y + static_cast<lv_coord_t>(index) * row_height;
        const bool selected = offset == selected_offset;
        if(selected) {
            theme::rect(parent, 0, y - 1, 320, row_height, lv_color_hex(0x0C1A18));
            theme::rect(parent, 0, y - 1, 3, row_height, theme::pink());
        }

        const bool malformed =
            sample->decode_outcome == simulator::SimulatedDecodeOutcome::Malformed;
        const lv_color_t row_color = selected ? theme::text() :
            ((!sample->crc_valid || malformed) ? theme::fault() :
             (sample->protocol == simulator::SimulatedProtocol::Unknown
                  ? theme::text_muted() : theme::lime()));
        char time[12]{};
        char source[12]{};
        char destination[12]{};
        char hops[5]{};
        char snr[10]{};
        const bool has_decoded_route =
            sample->source_node != simulator::kNoNode &&
            sample->decode_outcome != simulator::SimulatedDecodeOutcome::Raw &&
            sample->decode_outcome != simulator::SimulatedDecodeOutcome::Malformed;
        format_simulator_clock(time, sizeof(time), sample->timestamp_seconds_of_day);
        format_radio_endpoint(source, sizeof(source), sample->source_node, has_decoded_route);
        format_radio_endpoint(destination, sizeof(destination), sample->destination_node,
                              has_decoded_route);
        if(has_decoded_route) {
            std::snprintf(hops, sizeof(hops), "%u", static_cast<unsigned>(sample->hops));
        } else {
            std::snprintf(hops, sizeof(hops), "-");
        }
        std::snprintf(snr, sizeof(snr), "%+.1f",
                      static_cast<double>(sample->snr_db_x10) / 10.0);
        put_label(parent, time, kRadioTimeX, y, row_color, &font_mono_10);
        put_clipped_label(parent, source, kRadioSrcX, y, kRadioSrcW, row_color, &font_mono_10);
        put_clipped_label(parent, destination, kRadioDstX, y, kRadioDstW, row_color,
                          &font_mono_10);
        const char *pr = simulator_protocol_label(sample->protocol);
        if (std::strcmp(pr, "UNKNOWN") == 0) pr = "RF";
        put_label(parent, pr, kRadioPrX, y,
                  selected ? theme::pink() : theme::cyan(), &font_mono_10);
        put_label(parent, simulator_packet_kind_label(*sample), kRadioKindX, y,
                  row_color, &font_mono_10);
        put_label(parent, hops, kRadioHX, y, row_color, &font_mono_10);
        put_label(parent, snr, kRadioSnrX, y, row_color, &font_mono_10);
    }
    draw_radio_range_footer(parent, first_offset, visible, matching_count);
    draw_radio_tools(parent);
#endif
}

void build_traffic_filter(lv_obj_t *parent)
{
#if defined(LILYSHARK_DEVICE)
    add_status_bar(parent, "FILTER");
    const TrafficFilterSnapshot snapshot = trafficFilterSnapshot(
        capture_runtime.frames(), traffic_filter);
    const std::size_t retained = snapshot.retained_frames;
    const std::size_t matching = snapshot.matching_frames;
#else
    add_simulator_live_status_bar(parent, "FILTER");
    const std::size_t retained = simulator_live_telemetry.traffic().size;
    const std::size_t matching = simulator_matching_sample_count();
#endif
    char line[40]{};
    std::snprintf(line, sizeof(line), "MATCH  %u / %u",
                  static_cast<unsigned>(matching), static_cast<unsigned>(retained));
    put_label(parent, line, 8, 28,
              matching == 0U ? theme::amber() : theme::lime(), &font_pixel_6x8);
    put_label(parent, "CAPTURE FILES STAY COMPLETE.", 8, 40,
              theme::text_muted(), &font_pixel_6x8);

    struct FilterRow { const char *label; const char *value; };
    const std::array<FilterRow, 3> rows = {{
        {"PROTOCOL", trafficProtocolPredicateLabel(traffic_filter.protocol)},
        {"DECODE", trafficDecodePredicateLabel(traffic_filter.decode)},
        {"CRC", trafficCrcPredicateLabel(traffic_filter.crc)},
    }};
    for (std::size_t index = 0U; index < rows.size(); ++index) {
        const lv_coord_t y = kFiltFirstY + static_cast<lv_coord_t>(index) * kFiltRowH;
        const bool selected = traffic_filter_selection == index;
        if (selected) {
            theme::rect(parent, 0, y, 320, kFiltRowH, lv_color_hex(0x0C1A18));
            theme::rect(parent, 0, y, 3, kFiltRowH, theme::pink());
        }
        put_label(parent, rows[index].label, 10, y + 8,
                  selected ? theme::pink() : theme::text(), &font_pixel_6x8);
        lv_obj_t *value = theme::label(parent, rows[index].value,
            selected ? theme::lime() : theme::text_muted(), &font_mono_10);
        lv_obj_align_to(value, parent, LV_ALIGN_TOP_RIGHT, -8, y + 8);
        theme::rule_line(parent, 6, y + kFiltRowH - 1, 308, 1, theme::grid());
    }
    theme::rect(parent, 0, kToolStripY, 320, 20, lv_color_hex(0x050808));
    draw_outline_rect(parent, 8, kToolStripY, kEventBackW, kEventBackH, theme::pink());
    put_label(parent, "BACK", 12, kToolStripY + 5, theme::pink(), &font_pixel_6x8);
    put_label(parent, traffic_filter.active() ? "ACTIVE" : "ALL",
              72, kToolStripY + 6,
              traffic_filter.active() ? theme::pink() : theme::text_muted(),
              &font_pixel_6x8);
    put_label(parent, "L / R", 148, kToolStripY + 6, theme::text_muted(),
              &font_pixel_6x8);
    draw_outline_rect(parent, kToolChipX, kToolStripY, kToolChipW, kToolChipH, theme::pink());
    put_label(parent, "CLEAR", kToolChipX + 17, kToolStripY + 5, theme::pink(),
              &font_pixel_6x8);
}

void draw_nodes_range_footer(lv_obj_t *parent, std::size_t first, std::size_t visible,
                             std::size_t count) noexcept
{
    if (count <= kNodesVisible) return;
    char line[24]{};
    std::snprintf(line, sizeof(line), "%u-%u / %u",
                  static_cast<unsigned>(first + 1U),
                  static_cast<unsigned>(first + visible),
                  static_cast<unsigned>(count));
    theme::rect(parent, 0, kNodesFooterY, 320, 20, lv_color_hex(0x050808));
    put_label(parent, line, 8, kNodesFooterY + 6, theme::pink(), &font_pixel_6x8);
    draw_up_down_chips(parent, kNodesFooterY + 4, first > 0U, first + visible < count);
}

/// The local device, pinned above the peers. It is deliberately not part of
/// the selectable list — you cannot message yourself, and a self entry mixed
/// into the peer rows was what made every device look like it had a twin.
void draw_this_device_row(lv_obj_t *parent) noexcept
{
    constexpr lv_coord_t y = 46;
    theme::rect(parent, 0, y - 2, 320, 20, lv_color_hex(0x101820));
    theme::rect(parent, 0, y - 2, 3, 20, theme::cyan());

    char call[16]{};
#if defined(LILYSHARK_DEVICE)
    char short_name[8]{};
    formatLocalMeshtasticShortName(short_name, sizeof(short_name));
    std::snprintf(call, sizeof(call), "%s", short_name);
#else
    std::snprintf(call, sizeof(call), "LILY");
#endif
    put_clipped_label(parent, call, 8, y, 76, theme::cyan(), &font_mono_10);
    put_label(parent, "YOU", 88, y, theme::cyan(), &font_mono_10);
    put_label(parent, "NOW", 146, y, theme::text_muted(), &font_mono_10);
    put_label(parent, "--", 184, y, theme::text_muted(), &font_mono_10);

#if defined(LILYSHARK_DEVICE)
    const GpsStatus &self_gps = hardware_status.snapshot().gps;
    const bool fixed = self_gps.state == GpsState::Fix && self_gps.position_valid;
#else
    const bool fixed = app_settings.gps_enabled;
#endif
    put_label(parent, fixed ? "HERE" : "--", 226, y, theme::cyan(), &font_mono_10);
    // The identity moves right of the range column: "HERE" is four mono-10
    // characters and ran straight through an id line that started at 240.
    char id_line[20]{};
#if defined(LILYSHARK_DEVICE)
    std::snprintf(id_line, sizeof(id_line), "!%08lx",
                  static_cast<unsigned long>(localMeshtasticNodeNum()));
#else
    std::snprintf(id_line, sizeof(id_line), "!4b01a2e0");
#endif
    put_clipped_label(parent, id_line, 258, y, 56, theme::text_muted(), &font_pixel_6x8);
    theme::rule_line(parent, 6, y + 18, 308, 1, theme::cyan());
}

void build_nodes(lv_obj_t * parent)
{
#if defined(LILYSHARK_DEVICE)
    {
    add_status_bar(parent, "NODES");
    put_label(parent, "CALL", 8, 27, theme::pink(), &font_pixel_6x8);
    put_label(parent, "PROTO", 88, 27, theme::pink(), &font_pixel_6x8);
    put_label(parent, "LAST", 146, 27, theme::pink(), &font_pixel_6x8);
    put_label(parent, "SNR", 186, 27, theme::pink(), &font_pixel_6x8);
    put_label(parent, "RANGE", 224, 27, theme::pink(), &font_pixel_6x8);
    theme::rule_line(parent, 6, 43, 308, 1, theme::pink());
    draw_this_device_row(parent);

    std::array<LiveNodeSummary, 8> live_nodes{};
    const std::size_t count = collect_live_nodes(live_nodes);
    if(count == 0) {
        draw_nodes_empty(parent);
        return;
    }

    const std::size_t selected_index = resolve_node_selection(live_nodes, count);
    sync_nodes_scroll(selected_index, count);
    const std::size_t first = nodes_scroll_offset;
    const std::size_t visible = (count - first) < kNodesVisible ? (count - first) : kNodesVisible;
    for(std::size_t index = 0; index < visible; ++index) {
        const std::size_t node_index = first + index;
        const lv_coord_t y = kNodesFirstY + static_cast<lv_coord_t>(index) * kNodesRowH;
        const bool selected = node_index == selected_index;
        if(selected) {
            theme::rect(parent, 0, y - 2, 320, kNodesRowH, lv_color_hex(0x0C1A18));
            theme::rect(parent, 0, y - 2, 3, kNodesRowH, theme::pink());
        }
        const lv_color_t value_color = selected ? theme::pink() : theme::text();
        char age[10]{};
        char snr[10]{};
        format_age(age, sizeof(age), live_nodes[node_index].last_seen_us);
        // A node we have never heard on our own radio has no signal to report,
        // and printing one would present somebody else's reception as ours.
        const bool net_only = live_nodes[node_index].heard_via_net &&
                              !live_nodes[node_index].heard_on_radio;
        if (net_only) {
            std::snprintf(snr, sizeof(snr), "NET");
        } else {
            std::snprintf(snr, sizeof(snr), "%+.1f",
                          static_cast<double>(live_nodes[node_index].latest_snr_x10) / 10.0);
        }
        put_clipped_label(parent,
                          live_nodes[node_index].label[0] != '\0' ? live_nodes[node_index].label : "NODE",
                          8, y, 76, value_color, &font_mono_10);
        put_label(parent, home_protocol_tag(live_nodes[node_index].protocol), 88, y,
                  selected ? theme::pink() : theme::cyan(), &font_mono_10);
        put_label(parent, age, 146, y,
                  node_age_color(live_nodes[node_index].last_seen_us), &font_mono_10);
        put_label(parent, snr, 184, y,
                  net_only ? theme::cyan()
                           : (selected ? theme::pink() : theme::lime()), &font_mono_10);
        // How far away a neighbour is, not merely whether they said. In the
        // field that is the question this screen exists to answer.
        char range[12]{};
        {
            const GpsStatus &here = hardware_status.snapshot().gps;
            if (here.state == GpsState::Fix && here.position_valid &&
                live_nodes[node_index].has_position) {
                double east_m = 0.0;
                double north_m = 0.0;
                field_local_meters(here.latitude_degrees, here.longitude_degrees,
                                   live_nodes[node_index].latitude_degrees,
                                   live_nodes[node_index].longitude_degrees, east_m, north_m);
                format_map_range(range, sizeof(range), std::hypot(east_m, north_m));
            } else {
                std::snprintf(range, sizeof(range), "--");
            }
        }
        put_label(parent, range, 226, y,
                  selected ? theme::pink() : theme::text(), &font_mono_10);
        draw_live_node_history(parent, live_nodes[node_index], 268, y, 44, 14, false,
                               selected ? theme::pink() : theme::lime());
        theme::rule_line(parent, 6, y + 18, 308, 1, theme::grid());
    }
    draw_nodes_range_footer(parent, first, visible, count);
    return;
    }
#else
    add_simulator_live_status_bar(parent, "NODES");
    put_label(parent, "CALL", 8, 27, theme::pink(), &font_pixel_6x8);
    put_label(parent, "PROTO", 88, 27, theme::pink(), &font_pixel_6x8);
    put_label(parent, "LAST", 146, 27, theme::pink(), &font_pixel_6x8);
    put_label(parent, "SNR", 186, 27, theme::pink(), &font_pixel_6x8);
    put_label(parent, "RANGE", 224, 27, theme::pink(), &font_pixel_6x8);
    theme::rule_line(parent, 6, 43, 308, 1, theme::pink());
    draw_this_device_row(parent);

    const std::size_t count = simulator_established_node_count();
    if(count == 0U) {
        draw_nodes_empty(parent);
        return;
    }
    const std::size_t selected_index = resolve_simulator_node_selection();
    sync_nodes_scroll(selected_index, count);
    const std::size_t first = nodes_scroll_offset;
    const std::size_t visible = (count - first) < kNodesVisible ? (count - first) : kNodesVisible;
    for(std::size_t index = 0U; index < visible; ++index) {
        const std::size_t node_index = first + index;
        std::size_t raw_index = 0;
        const simulator::NodeSnapshot *node_pointer =
            simulator_established_node(node_index, &raw_index);
        if(node_pointer == nullptr) continue;
        const simulator::NodeSnapshot &node = *node_pointer;
        const lv_coord_t y = kNodesFirstY + static_cast<lv_coord_t>(index) * kNodesRowH;
        const bool selected = node_index == selected_index;
        if(selected) {
            theme::rect(parent, 0, y - 2, 320, kNodesRowH, lv_color_hex(0x0C1A18));
            theme::rect(parent, 0, y - 2, 3, kNodesRowH, theme::pink());
        }
        const lv_color_t value_color = selected ? theme::pink() : theme::text();
        char age[10]{};
        char snr[10]{};
        format_simulator_age(age, sizeof(age), node.last_seen_seconds);
        std::snprintf(snr, sizeof(snr), "%+.1f",
                      static_cast<double>(node.latest_snr_db_x10) / 10.0);
        put_clipped_label(parent, nodes[node_index % nodes.size()].name, 8, y, 76,
                          value_color, &font_mono_10);
        put_label(parent, simulator_protocol_label(node.protocol), 88, y,
                  selected ? theme::pink() : theme::cyan(), &font_mono_10);
        put_label(parent, age, 146, y, node_age_color_seconds(node.last_seen_seconds),
                  &font_mono_10);
        put_label(parent, snr, 184, y,
                  selected ? theme::pink() : theme::lime(), &font_mono_10);
        char range[12]{};
        double pin_lat = 0.0;
        double pin_lon = 0.0;
        if (field_peer_fix(raw_index, pin_lat, pin_lon)) {
            double you_lat = 0.0;
            double you_lon = 0.0;
            simulator_you_latlon(you_lat, you_lon);
            double east_m = 0.0;
            double north_m = 0.0;
            field_local_meters(you_lat, you_lon, pin_lat, pin_lon, east_m, north_m);
            format_map_range(range, sizeof(range), std::hypot(east_m, north_m));
        } else {
            std::snprintf(range, sizeof(range), "--");
        }
        put_label(parent, range, 226, y,
                  selected ? theme::pink() : theme::text(), &font_mono_10);
        draw_simulator_node_history(parent, node, 268, y, 44, 14,
                                    selected ? theme::pink() :
                                    (node.active ? theme::lime() : theme::text_muted()));
        theme::rule_line(parent, 6, y + 18, 308, 1, theme::grid());
    }
    draw_nodes_range_footer(parent, first, visible, count);
#endif
}

void build_spectrum(lv_obj_t * parent)
{
#if defined(LILYSHARK_DEVICE)
    {
    add_status_bar(parent, "SPECTRUM");
    if(app_settings.simulate_mode) {
        put_centered_label(parent, "LIVE RF SPECTRUM PAUSED", 72,
                           theme::amber(), &font_pixel_6x8);
        put_centered_label(parent, "SIMULATE MODE GENERATES PACKET TRAFFIC ONLY.", 101,
                           theme::text(), &font_pixel_6x8);
        put_centered_label(parent, "TURN IT OFF FOR AN SX1262 SPECTRAL SWEEP.", 119,
                           theme::text_muted(), &font_pixel_6x8);
        theme::rule_line(parent, 0, 198, 320);
        put_centered_label(parent, "SIMULATED / NOT AN RF MEASUREMENT", 207,
                           theme::amber(), &font_pixel_6x8);
        return;
    }
    const SpectrumSweepStatus &status = radio_service.spectrumStatus();
    const SpectrumSweepResult &result = radio_service.spectrumResult();
    const SpectrumSweepRequest planned_request = spectrum_request_for_profile(
        radio_service.activeProfile(), spectrum_scan_mode);
    constexpr lv_coord_t x = 7;
    constexpr lv_coord_t y = 30;
    constexpr lv_coord_t width = 306;
    constexpr lv_coord_t height = 145;

    if(spectrum_buffer == nullptr) {
        put_label(parent, "SPECTRUM BUFFER UNAVAILABLE", 16, 86,
                  theme::fault(), &font_pixel_6x8);
        put_label(parent, "PACKET CAPTURE REMAINS AVAILABLE", 16, 108,
                  theme::text_muted(), &font_pixel_6x8);
        return;
    }

    if(status.state == SpectrumSweepState::Idle && result.point_count == 0) {
        // Named before anything else on the screen. A band nobody has listened
        // to and a band that was listened to and found quiet are different
        // facts, and the operator has to be able to tell which one this is.
        put_centered_label(parent, "NOT SWEPT YET", 44, theme::amber(), &font_pixel_6x8);
        char title[48]{};
        std::snprintf(title, sizeof(title), "%s SPECTRAL SWEEP", spectrum_scan_mode_label());
        put_centered_label(parent, title, 62, theme::pink(), &font_pixel_6x8);
        char plan[72]{};
        std::snprintf(plan, sizeof(plan), "%.1f - %.1f MHz  /  %lu kHz steps",
                      static_cast<double>(planned_request.start_frequency_hz) / 1000000.0,
                      static_cast<double>(planned_request.end_frequency_hz) / 1000000.0,
                      static_cast<unsigned long>(planned_request.step_hz / 1000U));
        put_label(parent, plan, 36, 88, theme::cyan(), &font_mono_10);
        put_label(parent, "PACKET RECEIVE PAUSES WHILE THE SX1262 SCANS", 16, 113,
                  theme::amber(), &font_pixel_6x8);
        put_label(parent, "THE RADIO PROFILE IS RESTORED BEFORE RX RESUMES", 16, 130,
                  theme::text_muted(), &font_pixel_6x8);
        draw_spectrum_action_strip(parent, survey_running ? "SURVEY ACTIVE" : "",
                                   survey_running ? theme::amber() : theme::pink(),
                                   "START", !survey_running, false, !survey_running);
        return;
    }

    if(!status.active() && result.point_count == 0) {
        // A sweep that ended before its first frequency landed has no chart to
        // draw. Drawing the empty one anyway put a full band of heatmap ground
        // on screen, which is what a scanned and silent band looks like.
        put_centered_label(parent, "NO SPECTRUM WAS MEASURED", 52,
                           theme::fault(), &font_pixel_6x8);
        char reason[72]{};
        if(status.state == SpectrumSweepState::Cancelled) {
            std::snprintf(reason, sizeof(reason), "CANCELLED BEFORE THE FIRST FREQUENCY  RX %s",
                          status.restoration_succeeded ? "OK" : "FAILED");
        } else {
            std::snprintf(reason, sizeof(reason), "FAIL %s  RADIO %d  RX %s",
                          spectrum_failure_label(status.failure),
                          status.failure == SpectrumSweepFailure::RestoreFailed
                              ? status.restore_error : status.radio_error,
                          status.restoration_succeeded ? "OK" : "FAILED");
        }
        put_centered_label(parent, reason, 78, theme::amber(), &font_pixel_6x8);
        put_centered_label(parent, "THIS SAYS NOTHING ABOUT WHETHER THE BAND IS BUSY", 106,
                           theme::text_muted(), &font_pixel_6x8);
        put_centered_label(parent, "START THE SWEEP AGAIN TO MEASURE IT", 124,
                           theme::text_muted(), &font_pixel_6x8);
        draw_spectrum_action_strip(parent, survey_running ? "SURVEY ACTIVE" : "NOTHING MEASURED",
                                   survey_running ? theme::amber() : theme::fault(),
                                   "START", !survey_running, false, !survey_running);
        return;
    }

    lv_obj_t *canvas = lv_canvas_create(parent);
    theme::reset(canvas);
    lv_canvas_set_buffer(canvas, spectrum_buffer, width, height, LV_COLOR_FORMAT_RGB565);
    // The heatmap's own ground is painted per measured column below. Starting
    // from the screen background keeps unscanned frequencies visibly outside
    // the measurement rather than inside it at zero.
    lv_canvas_fill_bg(canvas, theme::background(), LV_OPA_COVER);
    lv_obj_set_pos(canvas, x, y);

    std::uint16_t maximum_count = 1;
    for(std::size_t point = 0; point < result.point_count; ++point) {
        for(std::size_t bin = 0; bin < kSpectrumPowerBinCount; ++bin) {
            if(result.points[point].counts[bin] > maximum_count) {
                maximum_count = result.points[point].counts[bin];
            }
        }
    }
    const std::uint16_t planned_point_count = status.points_total != 0U
        ? status.points_total : spectrum_request_point_count(planned_request);
    if(result.point_count > 0 && planned_point_count > 0U) {
        for(lv_coord_t px = 0; px < width; ++px) {
            const std::size_t point = static_cast<std::size_t>(px) * planned_point_count /
                                static_cast<std::size_t>(width);
            // A cancelled/in-progress scan is a partial result. Every unvisited
            // frequency column is hatched rather than filled, instead of
            // stretching the points collected so far across the full range.
            if(point >= result.point_count) {
                hatch_unswept_spectrum(canvas, px, static_cast<lv_coord_t>(px + 1), height);
                continue;
            }
            for(lv_coord_t py = 0; py < height; ++py) {
                std::size_t bin = static_cast<std::size_t>(py) * kSpectrumPowerBinCount /
                                  static_cast<std::size_t>(height);
                if(bin >= kSpectrumPowerBinCount) bin = kSpectrumPowerBinCount - 1;
                const std::uint16_t count = result.points[point].counts[bin];
                // Preserve the scan's full histogram instead of making rare
                // power buckets disappear behind the dominant noise-floor
                // bucket. Every observed bucket gets a cold pixel; repeated
                // samples then increase intensity linearly.
                const std::uint32_t scaled = count == 0 ? 0U :
                    20U + (static_cast<std::uint32_t>(count) * 235U) / maximum_count;
                lv_color_t color = theme::heat_deep();
                if(scaled > 210U) color = theme::heat_peak();
                else if(scaled > 160U) color = theme::heat_hot();
                else if(scaled > 110U) color = theme::heat_bright();
                else if(scaled > 62U) color = theme::heat_mid();
                else if(scaled > 12U) color = theme::heat_cold();
                lv_canvas_set_px(canvas, px, py, color, LV_OPA_COVER);
            }
        }
    }
    const SpectrumTraceStats traces = draw_spectrum_traces(canvas, result, planned_point_count,
                                                           width, height, spectrum_peak_hold);
    lv_obj_invalidate(canvas);
    add_grid(parent, x, y, width, height, 47, 29);
    theme::rule_line(parent, x, y, width);
    theme::rule_line(parent, x, y + height, width);
    draw_spectrum_axes(parent, x, y, width, height, planned_request.start_frequency_hz,
                       planned_request.end_frequency_hz);
    {
        const RadioProfile &tuned = radio_service.activeProfile();
        draw_spectrum_channel_marker(parent, x, y, width, height,
                                     planned_request.start_frequency_hz,
                                     planned_request.end_frequency_hz,
                                     tuned.center_frequency_hz, tuned.bandwidth_hz);
    }

    char line[72]{};
    if(status.active()) {
        const std::uint32_t percent = status.points_total == 0 ? 0 :
            (static_cast<std::uint32_t>(status.points_completed) * 100U) / status.points_total;
        std::snprintf(line, sizeof(line), "SCANNING %u/%u  %lu%%  %.3f MHZ",
                      status.points_completed, status.points_total,
                      static_cast<unsigned long>(percent),
                      static_cast<double>(status.current_frequency_hz) / 1000000.0);
        put_label(parent, line, 16, 189, theme::amber(), &font_pixel_6x8);
        // Loudest so far, while the rest of the band is still hatched as
        // unheard. The half that has been measured is a real measurement, but
        // a sweep that has not reached its first frequency has nothing to say
        // yet and the progress line above already says so.
        if(traces.measured) draw_spectrum_loudest_line(parent, traces, 177, true);
        draw_spectrum_action_strip(parent, "RX PAUSED", theme::text_muted(), "STOP",
                                   true, true, false);
    } else if(status.state == SpectrumSweepState::Failed) {
        const std::int16_t error = status.failure == SpectrumSweepFailure::RestoreFailed
            ? status.restore_error : status.radio_error;
        const bool receive_recovered = status.failure == SpectrumSweepFailure::RestoreFailed &&
                                       radio_service.status().receiving;
        std::snprintf(line, sizeof(line), "FAIL %s  RADIO %d  RX %s",
                      spectrum_failure_label(status.failure), error,
                      status.restoration_succeeded ? "OK" :
                      (receive_recovered ? "RECOVERED" : "FAILED"));
        put_label(parent, line, 16, 177, theme::fault(), &font_pixel_6x8);
        // The frequencies that did land are still measured ground. The failure
        // above says how much of the plan they cover.
        draw_spectrum_loudest_line(parent, traces, 189, true);
        draw_spectrum_action_strip(parent, survey_running ? "SURVEY ACTIVE" : "FAILED",
                                   survey_running ? theme::amber() : theme::fault(),
                                   "START", !survey_running, false, !survey_running);
    } else if(status.state == SpectrumSweepState::Cancelled) {
        std::snprintf(line, sizeof(line), "CANCELLED  %u OF %u BINS MEASURED  RX OK",
                      status.points_completed, status.points_total);
        put_label(parent, line, 16, 177, theme::amber(), &font_pixel_6x8);
        draw_spectrum_loudest_line(parent, traces, 189, true);
        draw_spectrum_action_strip(parent, survey_running ? "SURVEY ACTIVE" : "CANCELLED",
                                   survey_running ? theme::amber() : theme::text_muted(),
                                   "START", !survey_running, false, !survey_running);
    } else {
        // What the sweep measured, as a sentence first. The old footer was
        // four labelled numbers, which is the same data but leaves the reader
        // to work out that the number under AT is where the number under PEAK
        // came from -- and never distinguished a quiet band from a failed one.
        draw_spectrum_loudest_line(parent, traces, 177, false);
        draw_spectrum_floor_line(parent, traces, 189);
        draw_spectrum_action_strip(parent, survey_running ? "SURVEY ACTIVE" : "COMPLETE",
                                   survey_running ? theme::amber() : theme::pink(),
                                   "START", !survey_running, false, !survey_running);
    }
    return;
    }
#else
    add_simulator_live_status_bar(parent, "SPECTRUM");
    constexpr lv_coord_t x = 7;
    constexpr lv_coord_t y = 30;
    constexpr lv_coord_t width = 306;
    constexpr lv_coord_t height = 145;
    lv_obj_t * canvas = lv_canvas_create(parent);
    theme::reset(canvas);
    lv_canvas_set_buffer(canvas, spectrum_buffer, width, height, LV_COLOR_FORMAT_RGB565);
    // Same rule as the deck: the heatmap ground belongs only under frequencies
    // the sweep has actually reached.
    lv_canvas_fill_bg(canvas, theme::background(), LV_OPA_COVER);
    lv_obj_set_pos(canvas, x, y);

    const simulator::SpectrumSnapshot &spectrum = simulator_live_telemetry.spectrum();
    const SpectrumSweepRequest request = simulator_spectrum_request();
    const std::uint16_t total_points = simulator_spectrum_total_points();
    const std::uint32_t elapsed = simulator_live_telemetry.elapsedMilliseconds() -
                                  simulator_spectrum_started_ms;
    const std::uint16_t completed = simulator_spectrum_scanning
        ? static_cast<std::uint16_t>((elapsed / 50U) > total_points
                                        ? total_points : elapsed / 50U)
        : simulator_spectrum_partial_points;
    const lv_coord_t revealed_width = static_cast<lv_coord_t>(
        total_points == 0U ? 0U :
        (static_cast<std::uint32_t>(completed) * width) / total_points);
    using SimulatedSpectrumHistogram =
        std::array<std::array<std::uint16_t, kSpectrumPowerBinCount>,
                   simulator::kSpectrumColumnCount>;
    static SimulatedSpectrumHistogram histogram{};
    for(auto &column : histogram) column.fill(0U);
    std::uint16_t maximum_count = 1U;
    for(std::size_t column = 0U; column < simulator::kSpectrumColumnCount; ++column) {
        for(std::size_t age = 0U; age < simulator::kSpectrumHistoryRowCount; ++age) {
            const std::uint8_t intensity = spectrum.intensity(age, column);
            // Convert the recent time series into the same frequency-by-power
            // histogram the SX1262 returns on-device. A quiet sample clusters
            // near the simulated floor; stronger carriers move upward toward
            // the -11 dBm end of the 33 RadioLib power bins.
            const std::int32_t power_dbm = static_cast<std::int32_t>(
                spectrum.noise_floor_dbm - 6 +
                (static_cast<std::uint32_t>(intensity) * 88U) / 255U);
            std::int32_t power_bin = (-11 - power_dbm) / 4;
            if(power_bin < 0) power_bin = 0;
            if(power_bin >= static_cast<std::int32_t>(kSpectrumPowerBinCount)) {
                power_bin = static_cast<std::int32_t>(kSpectrumPowerBinCount - 1U);
            }
            std::uint16_t &count = histogram[column][static_cast<std::size_t>(power_bin)];
            if(count != UINT16_MAX) ++count;
            if(count > maximum_count) maximum_count = count;
        }
    }
    for(lv_coord_t px = 0; px < revealed_width; ++px) {
        const std::size_t column = static_cast<std::size_t>(px) *
                                   simulator::kSpectrumColumnCount /
                                   static_cast<std::size_t>(width);
        for(lv_coord_t py = 0; py < height; ++py) {
            std::size_t bin = static_cast<std::size_t>(py) * kSpectrumPowerBinCount /
                              static_cast<std::size_t>(height);
            if(bin >= kSpectrumPowerBinCount) bin = kSpectrumPowerBinCount - 1U;
            const std::uint16_t count = histogram[column][bin];
            const std::uint32_t scaled = count == 0U ? 0U :
                20U + (static_cast<std::uint32_t>(count) * 235U) / maximum_count;
            lv_color_t color = theme::heat_deep();
            if(scaled > 210U) color = theme::heat_peak();
            else if(scaled > 160U) color = theme::heat_hot();
            else if(scaled > 110U) color = theme::heat_bright();
            else if(scaled > 62U) color = theme::heat_mid();
            else if(scaled > 12U) color = theme::heat_cold();
            lv_canvas_set_px(canvas, px, py, color, LV_OPA_COVER);
        }
    }
    hatch_unswept_spectrum(canvas, revealed_width, width, height);
    // The same traces the device draws, from the same histogram shape, so the
    // preview shows what the hardware shows rather than an approximation of it.
    static SpectrumSweepResult preview{};
    preview.point_count = 0U;
    preview.request = request;
    const std::uint16_t revealed_columns = static_cast<std::uint16_t>(
        total_points == 0U ? 0U :
        (static_cast<std::uint32_t>(completed) * simulator::kSpectrumColumnCount) / total_points);
    for(std::size_t column = 0U;
        column < revealed_columns && column < simulator::kSpectrumColumnCount &&
        column < kMaxSpectrumSweepPoints;
        ++column) {
        // Columns span the whole request, not one step each: multiplying a
        // column index by step_hz walked the peak frequency clean off the
        // axis the chart was drawing.
        preview.points[column].frequency_hz = request.start_frequency_hz +
            static_cast<std::uint32_t>(
                (static_cast<std::uint64_t>(column) *
                 (request.end_frequency_hz - request.start_frequency_hz)) /
                (simulator::kSpectrumColumnCount > 1U
                     ? simulator::kSpectrumColumnCount - 1U : 1U));
        for(std::size_t bin = 0U; bin < kSpectrumPowerBinCount; ++bin) {
            preview.points[column].counts[bin] = histogram[column][bin];
        }
        preview.point_count = static_cast<std::uint16_t>(column + 1U);
    }
    // The full column plan, not the revealed prefix. Passing the prefix mapped
    // the frequencies scanned so far across the whole chart, so a sweep a
    // tenth of the way through drew traces over nine tenths of a band it had
    // not reached -- and reset the peak hold on every frame, because the hold
    // keys on the plan it is holding.
    const SpectrumTraceStats traces = draw_spectrum_traces(
        canvas, preview, static_cast<std::uint16_t>(simulator::kSpectrumColumnCount),
        width, height, spectrum_peak_hold);
    lv_obj_invalidate(canvas);

    add_grid(parent, x, y, width, height, 24, 16);
    theme::rule_line(parent, x, y, width);
    theme::rule_line(parent, x, y + height, width);
    draw_spectrum_axes(parent, x, y, width, height, request.start_frequency_hz,
                       request.end_frequency_hz);
    {
        const std::size_t profiles = builtinProfileCount();
        if(profiles != 0U) {
            const RadioProfile &tuned =
                builtinProfiles()[simulator_active_profile_index % profiles];
            draw_spectrum_channel_marker(parent, x, y, width, height,
                                         request.start_frequency_hz, request.end_frequency_hz,
                                         tuned.center_frequency_hz, tuned.bandwidth_hz);
        }
    }

    if(simulator_spectrum_scanning) {
        const lv_coord_t cursor = x + static_cast<lv_coord_t>(
            total_points == 0U ? 0U :
            (static_cast<std::uint32_t>(completed) * width) / total_points);
        theme::rule_line(parent, cursor, y, 1, height, theme::cyan());
        for(lv_coord_t tick = y + 7; tick < y + height; tick += 10) {
            theme::rule_line(parent, cursor - 5, tick, 11, 1, theme::cyan());
        }
    }

    if(simulator_spectrum_scanning) {
        theme::rect(parent, 0, 176, 320, 28, theme::background());
        char scan_line[64]{};
        const std::uint32_t percent = total_points == 0U ? 0U :
            (static_cast<std::uint32_t>(completed) * 100U) / total_points;
        const std::uint16_t current_point = total_points == 0U ? 0U
            : (completed < total_points ? completed : total_points - 1U);
        const std::uint32_t frequency_hz = request.start_frequency_hz +
            static_cast<std::uint32_t>(current_point) * request.step_hz;
        std::snprintf(scan_line, sizeof(scan_line), "SCANNING %u/%u  %lu%%  %.3f MHZ",
                      static_cast<unsigned>(completed), static_cast<unsigned>(total_points),
                      static_cast<unsigned long>(percent),
                      static_cast<double>(frequency_hz) / 1000000.0);
        put_label(parent, scan_line, 16, 189, theme::amber(), &font_pixel_6x8);
        if(traces.measured) draw_spectrum_loudest_line(parent, traces, 177, true);
        draw_spectrum_action_strip(parent, "RX PAUSED", theme::text_muted(), "STOP",
                                   true, true, false);
        return;
    }

    if(simulator_spectrum_cancelled) {
        char cancelled[56]{};
        std::snprintf(cancelled, sizeof(cancelled), "CANCELLED  %u OF %u BINS MEASURED",
                      static_cast<unsigned>(completed), static_cast<unsigned>(total_points));
        put_label(parent, cancelled, 16, 177, theme::amber(), &font_pixel_6x8);
        draw_spectrum_loudest_line(parent, traces, 189, true);
        draw_spectrum_action_strip(parent,
                                   simulator_survey_running ? "SURVEY ACTIVE" : "RX RESUMED",
                                   simulator_survey_running ? theme::amber() : theme::text_muted(),
                                   "START", !simulator_survey_running, false,
                                   !simulator_survey_running);
        return;
    }
    if(completed == 0U) {
        // The rule belongs only to this state: the two-line readout the other
        // states draw starts at 177 and a line at 182 runs through its letters.
        theme::rule_line(parent, 7, 182, 306);
        // Not "NO SWEEP CAPTURED", which reads as a sweep that found nothing.
        // Nothing has been measured here at all, and the hatched chart above
        // says the same thing in pixels.
        put_centered_label(parent, "NOT SWEPT YET - NOTHING HAS BEEN MEASURED", 184,
                           theme::amber(), &font_pixel_6x8);
        char mode_line[56]{};
        std::snprintf(mode_line, sizeof(mode_line), "%s  /  %u BINS",
                      spectrum_scan_mode_label(), static_cast<unsigned>(total_points));
        put_centered_label(parent, mode_line, 196, theme::pink(), &font_pixel_6x8);
        draw_spectrum_action_strip(parent,
                                   simulator_survey_running ? "SURVEY ACTIVE" : "",
                                   simulator_survey_running ? theme::amber() : theme::pink(),
                                   "START", !simulator_survey_running, false,
                                   !simulator_survey_running);
        return;
    }
    // The same sentence and the same supporting numbers the deck prints, from
    // the same traces, so the preview and the hardware cannot drift into
    // describing the band differently.
    draw_spectrum_loudest_line(parent, traces, 177, false);
    draw_spectrum_floor_line(parent, traces, 189);
    draw_spectrum_action_strip(parent,
                               simulator_survey_running ? "SURVEY ACTIVE" : "COMPLETE",
                               simulator_survey_running ? theme::amber() : theme::pink(),
                               "START", !simulator_survey_running, false,
                               !simulator_survey_running);
#endif
}

void build_node_detail(lv_obj_t * parent)
{
#if defined(LILYSHARK_DEVICE)
    {
    add_status_bar(parent, "NODE");
    std::array<LiveNodeSummary, 8> live_nodes{};
    const std::size_t count = collect_live_nodes(live_nodes);
    if(count == 0) {
        put_label(parent, "NO NODE SELECTED", 16, 90, theme::pink(), &font_pixel_6x8);
        put_label(parent, "CAPTURE A DECODED SOURCE FIRST", 16, 111,
                  theme::text_muted(), &font_pixel_6x8);
        draw_back_strip(parent);
        return;
    }

    if(!node_detail_selection_valid) {
        const LiveNodeSummary &selected = live_nodes[resolve_node_selection(live_nodes, count)];
        node_detail_protocol = selected.protocol;
        node_detail_id = selected.id;
        node_detail_selection_valid = true;
    }
    const LiveNodeSummary *selected_node = nullptr;
    for(std::size_t index = 0; index < count; ++index) {
        if(live_node_matches(live_nodes[index], node_detail_protocol, node_detail_id)) {
            selected_node = &live_nodes[index];
            break;
        }
    }
    if(selected_node == nullptr) {
        put_label(parent, "SELECTED NODE EXPIRED", 16, 90, theme::fault(), &font_pixel_6x8);
        put_label(parent, "ITS FRAMES LEFT THE CAPTURE BUFFER", 16, 108,
                  theme::text_muted(), &font_pixel_6x8);
        draw_back_strip(parent);
        return;
    }

    const LiveNodeSummary &node = *selected_node;
    char line[72]{};
    char age[12]{};
    format_age(age, sizeof(age), node.last_seen_us);
    put_label(parent, node.label[0] != '\0' ? node.label : "NODE", 8, 24,
              theme::text(), &font_pixel_18x24);
    std::snprintf(line, sizeof(line), "%08lX  %s  HEARD %s AGO  %u PACKETS",
                  static_cast<unsigned long>(node.id), home_protocol_tag(node.protocol), age,
                  static_cast<unsigned>(node.frames));
    put_label(parent, line, 9, 50, theme::text_muted(), &font_pixel_6x8);
    draw_outline_rect(parent, kNodeChatX, kNodeActionY, kNodeActionW, kNodeActionH, theme::pink());
    put_label(parent, "MESSAGE", kNodeChatX + 8, kNodeActionY + 5, theme::pink(), &font_pixel_6x8);
    draw_outline_rect(parent, kNodeMapX, kNodeActionY, kNodeActionW, kNodeActionH,
                      node.has_position ? theme::pink() : theme::text_muted());
    put_label(parent, "MAP", kNodeMapX + 11, kNodeActionY + 5,
              node.has_position ? theme::pink() : theme::text_muted(), &font_pixel_6x8);
    if (node.has_position) {
        const GpsStatus &gps = hardware_status.snapshot().gps;
        const bool have_you = gps.state == GpsState::Fix && gps.position_valid;
        draw_node_fix_strip(parent, node.latitude_degrees, node.longitude_degrees,
                            have_you, gps.latitude_degrees, gps.longitude_degrees);
    }
    theme::rule_line(parent, 6, 84, 308, 1, theme::pink());

    put_label(parent, "SNR", 8, 88, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%+.1f  AVG %+.1f",
                  static_cast<double>(node.latest_snr_x10) / 10.0,
                  node.frames == 0 ? 0.0 : static_cast<double>(node.snr_sum_x10) /
                      (10.0 * static_cast<double>(node.frames)));
    put_label(parent, line, 36, 88, theme::lime(), &font_mono_10);
    draw_live_node_history(parent, node, 8, 98, 304, 46);
    put_label(parent, "RSSI", 8, 146, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%.1f  CRC %u",
                  static_cast<double>(node.latest_rssi_x10) / 10.0,
                  static_cast<unsigned>(node.crc_errors));
    put_label(parent, line, 42, 146,
              node.crc_errors == 0 ? theme::cyan() : theme::fault(), &font_mono_10);
    draw_live_node_history(parent, node, 8, 156, 304, 44, true);
    draw_node_detail_axis_chips(parent);
    // What the peer says about itself, when it has said anything. Every field
    // is separately optional -- a node reporting voltage but no percentage is
    // ordinary, and printing 0% for it would invent a reading.
    {
        char telem[56]{};
        std::size_t used = 0;
        if (node.has_battery_level) {
            used += static_cast<std::size_t>(std::snprintf(
                telem + used, sizeof(telem) - used, "BAT %u%%",
                static_cast<unsigned>(node.battery_level)));
        }
        if (node.has_voltage && used < sizeof(telem)) {
            used += static_cast<std::size_t>(std::snprintf(
                telem + used, sizeof(telem) - used, "%s%.2fV", used ? "  " : "",
                static_cast<double>(node.voltage)));
        }
        if (node.has_channel_utilization && used < sizeof(telem)) {
            used += static_cast<std::size_t>(std::snprintf(
                telem + used, sizeof(telem) - used, "%sCH %.0f%%", used ? "  " : "",
                static_cast<double>(node.channel_utilization)));
        }
        if (node.has_temperature && used < sizeof(telem)) {
            (void)std::snprintf(telem + used, sizeof(telem) - used, "%s%.0fC",
                                used ? "  " : "", static_cast<double>(node.temperature_c));
        }
        if (telem[0] != '\0') {
            put_label(parent, "REPORTS", 8, 202, theme::pink(), &font_pixel_6x8);
            put_clipped_label(parent, telem, 60, 202, 252, theme::text(), &font_mono_10);
        }
    }
    draw_back_strip(parent);
    return;
    }
#else
    add_simulator_live_status_bar(parent, "NODE");
    const simulator::NodeSnapshot *selected_node = simulator_node_detail_selection_valid
        ? simulator_established_node_by_id(simulator_node_detail_id) : nullptr;
    if(selected_node == nullptr) {
        put_label(parent, "NO NODE SELECTED", 16, 90,
                  theme::pink(), &font_pixel_6x8);
        put_label(parent, "WAIT FOR A FRAME WITH A STABLE SOURCE", 16, 111,
                  theme::text_muted(), &font_pixel_6x8);
        draw_back_strip(parent);
        return;
    }
    const simulator::NodeSnapshot &live_node = *selected_node;
    char node_line[72]{};
    char age[10]{};
    format_simulator_age(age, sizeof(age), live_node.last_seen_seconds);
    const char *callsign = "NODE";
    for (std::size_t index = 0; index < simulator::kNodeCount; ++index) {
        if (simulator_live_telemetry.nodes().nodes[index].id != live_node.id) continue;
        callsign = nodes[index % nodes.size()].name;
        break;
    }
    put_label(parent, callsign, 8, 24, theme::text(), &font_pixel_18x24);
    std::snprintf(node_line, sizeof(node_line), "%08lX  %s  HEARD %s AGO  %u PACKETS",
                  static_cast<unsigned long>(live_node.id),
                  simulator_protocol_label(live_node.protocol), age,
                  static_cast<unsigned>(live_node.frame_count));
    put_label(parent, node_line, 9, 50, theme::text_muted(), &font_pixel_6x8);
    draw_outline_rect(parent, kNodeChatX, kNodeActionY, kNodeActionW, kNodeActionH, theme::pink());
    put_label(parent, "MESSAGE", kNodeChatX + 8, kNodeActionY + 5, theme::pink(), &font_pixel_6x8);
    draw_outline_rect(parent, kNodeMapX, kNodeActionY, kNodeActionW, kNodeActionH, theme::pink());
    put_label(parent, "MAP", kNodeMapX + 11, kNodeActionY + 5, theme::pink(), &font_pixel_6x8);
    {
        double fix_lat = 0.0;
        double fix_lon = 0.0;
        if (simulator_node_fix(live_node, fix_lat, fix_lon)) {
            double you_lat = 0.0;
            double you_lon = 0.0;
            const bool have_you = app_settings.gps_enabled;
            if (have_you) simulator_you_latlon(you_lat, you_lon);
            draw_node_fix_strip(parent, fix_lat, fix_lon, have_you, you_lat, you_lon);
        }
    }
    theme::rule_line(parent, 6, 84, 308);

    put_label(parent, "SNR", 8, 88, theme::pink(), &font_pixel_6x8);
    std::snprintf(node_line, sizeof(node_line), "%+.1f  AVG %+.1f",
                  static_cast<double>(live_node.latest_snr_db_x10) / 10.0,
                  static_cast<double>(live_node.mean_snr_db_x10) / 10.0);
    put_label(parent, node_line, 36, 88, theme::lime(), &font_mono_10);
    draw_simulator_node_history(parent, live_node, 8, 98, 304, 46, theme::lime());
    put_label(parent, "RSSI", 8, 146, theme::pink(), &font_pixel_6x8);
    std::snprintf(node_line, sizeof(node_line), "%.1f  CRC %u",
                  static_cast<double>(live_node.latest_rssi_dbm_x10) / 10.0,
                  static_cast<unsigned>(live_node.crc_errors));
    put_label(parent, node_line, 42, 146,
              live_node.crc_errors == 0U ? theme::cyan() : theme::fault(), &font_mono_10);
    draw_simulator_node_history(parent, live_node, 8, 156, 304, 44,
                                theme::cyan(), true);
    draw_node_detail_axis_chips(parent);
    draw_back_strip(parent);
#endif
}

constexpr std::array<const char *, 5> packet_detail_tabs = {{"PKT", "RF", "DEC", "HEX", "RAW"}};

void add_packet_detail_tabs(lv_obj_t *parent)
{
    theme::rect(parent, 0, 22, 38, 180, theme::surface());
    theme::rule_line(parent, 37, 22, 1, 180);
    for(std::size_t index = 0; index < packet_detail_tabs.size(); ++index) {
        const lv_coord_t y = 29 + static_cast<lv_coord_t>(index) * 37;
        if(index == packet_detail_tab) {
            theme::rect(parent, 1, y - 2, 35, 25, lv_color_hex(0x0C1A18));
            theme::rect(parent, 1, y - 2, 3, 25, theme::pink());
        }
        put_label(parent, packet_detail_tabs[index], 8, y + 4,
                  index == packet_detail_tab ? theme::pink() : theme::text_muted(),
                  &font_pixel_6x8);
    }
}

std::uint32_t packet_fingerprint(const std::uint8_t *bytes, std::size_t length) noexcept
{
    std::uint32_t hash = 2166136261U;
    for(std::size_t index = 0; index < length; ++index) {
        hash ^= bytes[index];
        hash *= 16777619U;
    }
    return hash;
}

void build_packet_detail(lv_obj_t * parent)
{
#if defined(LILYSHARK_DEVICE)
    {
    add_status_bar(parent, "PACKET");
    if(packet_detail_sequence == 0) select_current_frame_for_detail();
    const FrameRecord *record = find_live_frame(packet_detail_sequence);
    if(record == nullptr) {
        if(capture_runtime.frames().empty()) {
            put_label(parent, "NO CAPTURED FRAME", 16, 90,
                      theme::pink(), &font_pixel_6x8);
            put_label(parent, "OPEN TRAFFIC AND WAIT FOR RADIO ACTIVITY", 16, 112,
                      theme::text_muted(), &font_pixel_6x8);
        } else {
            put_label(parent, "SELECTED FRAME EXPIRED", 16, 90,
                      theme::fault(), &font_pixel_6x8);
            put_label(parent, "IT LEFT THE 64-FRAME CAPTURE BUFFER", 16, 112,
                      theme::text_muted(), &font_pixel_6x8);

        }
        draw_back_strip(parent);
        return;
    }

    add_packet_detail_tabs(parent);

    // Read the payload once for the whole screen, under the default key and
    // then under the operator's keys.
    MeshtasticPayload readable{};
    MeshtasticKeyState key_state{};
    const bool has_readable = read_frame_payload(*record, readable, key_state);
    const bool opened_by_stored_key = key_state.source == MeshtasticKeySource::StoredKey;
    // The decoder library only ever tries the published default key, so a
    // frame one of the operator's own keys opened still arrives from it marked
    // OPAQUE / HEADER. Printing that above the message this screen is about to
    // show would be the wrong kind of honest, so the labels state what the
    // deck as a whole made of the frame and the key line below names what did
    // it. A frame the default key opened is untouched, so it renders exactly
    // as it always has.
    DecodedPacket shown = record->decoded;
    if(opened_by_stored_key) {
        shown.kind = PacketKind::Data;
        shown.state = DecodeState::PayloadDecoded;
        shown.application_port = readable.portnum;
    }

    char source[12]{};
    char destination[12]{};
    char line[72]{};
    format_node(source, sizeof(source), record->decoded, FieldSource);
    format_node(destination, sizeof(destination), record->decoded, FieldDestination);
    put_label(parent, "SRC", 49, 29, theme::pink(), &font_pixel_6x8);
    put_label(parent, source, 73, 29, theme::text(), &font_pixel_6x8);
    put_label(parent, "DST", 161, 29, theme::pink(), &font_pixel_6x8);
    put_label(parent, destination, 185, 29, theme::text(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%s  %s  %s  %u B%s", protocolName(shown.protocol),
                  packetKindLabel(shown), decodeStateLabel(shown.state),
                  record->raw.captured_length,
                  record->raw.rf.origin == FrameOrigin::Synthetic ? "  SIM" : "");
    put_label(parent, line, 49, 50,
              shown.state == DecodeState::Malformed ? theme::fault() : theme::amber(),
              &font_mono_10);
    if(record->raw.rf.hasField(RfFieldCodingRate)) {
        std::snprintf(line, sizeof(line), "SF%u  BW %.1fk  CR4/%u  0x%04X",
                      record->raw.rf.spreading_factor,
                      static_cast<double>(record->raw.rf.bandwidth_hz) / 1000.0,
                      record->raw.rf.coding_rate_denominator, record->raw.rf.sync_word);
    } else {
        std::snprintf(line, sizeof(line), "SF%u  BW %.1fk  CR --  0x%04X",
                      record->raw.rf.spreading_factor,
                      static_cast<double>(record->raw.rf.bandwidth_hz) / 1000.0,
                      record->raw.rf.sync_word);
    }
    put_label(parent, line, 49, 67, theme::text(), &font_mono_10);
    std::snprintf(line, sizeof(line), "RSSI %.1f  SNR %+.1f DB  CRC %s",
                  static_cast<double>(record->raw.rf.rssi_dbm_x10) / 10.0,
                  static_cast<double>(record->raw.rf.snr_db_x10) / 10.0,
                  record->raw.rf.crc == CrcStatus::Valid ? "OK" :
                  (record->raw.rf.crc == CrcStatus::Invalid ? "BAD" : "--"));
    put_label(parent, line, 49, 84,
              record->raw.rf.crc == CrcStatus::Invalid ? theme::fault() : theme::lime(), &font_mono_10);
    theme::rule_line(parent, 47, 103, 266);

    auto format_protocol_detail = [&]() {
        const bool malformed_without_safe_fields =
            record->decoded.state == DecodeState::Malformed &&
            (record->decoded.present_fields & ~static_cast<std::uint32_t>(FieldPayload)) == 0U;
        if(malformed_without_safe_fields) {
            std::snprintf(line, sizeof(line), "STRUCTURE INVALID / NO SAFE HEADER FACTS");
        } else if(record->decoded.protocol == ProtocolId::MeshCore &&
                  record->decoded.state != DecodeState::Malformed) {
            std::snprintf(line, sizeof(line), "ROUTE %u  TYPE %s  PATH %ux%u",
                          static_cast<unsigned>(MeshCoreDecoder::routeType(record->decoded)),
                          packetKindLabel(record->decoded),
                          static_cast<unsigned>(MeshCoreDecoder::pathHashCount(record->decoded)),
                          static_cast<unsigned>(MeshCoreDecoder::pathHashSize(record->decoded)));
        } else if(record->decoded.protocol == ProtocolId::Reticulum &&
                  record->decoded.state != DecodeState::Malformed) {
            if(ReticulumDecoder::isIfacProtected(record->decoded)) {
                std::snprintf(line, sizeof(line), "IFAC MARKED / UNVERIFIED  HEADER OPAQUE");
            } else if(ReticulumDecoder::isRNodeSplitFrame(record->decoded)) {
                std::snprintf(line, sizeof(line), "RNODE SPLIT FRAME  REASSEMBLY PENDING");
            } else {
                std::snprintf(line, sizeof(line), "H%u  HOPS %u  DEST PREFIX %08lX",
                              ReticulumDecoder::headerType(record->decoded) == ReticulumHeaderType::HeaderTwo ? 2U : 1U,
                              static_cast<unsigned>(ReticulumDecoder::observedHops(record->decoded)),
                              static_cast<unsigned long>(ReticulumDecoder::destinationHashPrefix(record->decoded)));
            }
        } else if(record->decoded.hasField(FieldPacketId)) {
            std::snprintf(line, sizeof(line), "ID %08lX  CH HASH %02X  HOPS %u/%u",
                          static_cast<unsigned long>(record->decoded.packet_id),
                          static_cast<unsigned>(record->decoded.channel),
                          record->decoded.hop_limit, record->decoded.hop_start);
        } else {
            std::snprintf(line, sizeof(line), "FLAGS 0x%08lX  OFFSET %u",
                          static_cast<unsigned long>(record->decoded.protocol_flags),
                          record->decoded.payload_offset);
        }
    };

    if(packet_detail_tab == 0U) {
        format_protocol_detail();
        put_label(parent, line, 49, 114, theme::cyan(), &font_mono_10);
        std::snprintf(line, sizeof(line), "FRAME #%llu   CAPTURED %u / ORIGINAL %u",
                      static_cast<unsigned long long>(record->sequence),
                      record->raw.captured_length, record->raw.original_length);
        put_label(parent, line, 49, 139, theme::text(), &font_mono_10);
        std::snprintf(line, sizeof(line), "PAYLOAD OFFSET %u   LENGTH %u",
                      record->decoded.payload_offset, record->decoded.payload_length);
        put_label(parent, line, 49, 158, theme::text(), &font_mono_10);
        std::snprintf(line, sizeof(line), "MONOTONIC %llu us",
                      static_cast<unsigned long long>(record->raw.rf.timestamp_us));
        put_label(parent, line, 49, 177, theme::text_muted(), &font_mono_10);
    } else if(packet_detail_tab == 1U) {
        put_label(parent, "CENTER", 49, 112, theme::pink(), &font_pixel_6x8);
        std::snprintf(line, sizeof(line), "%.3f",
                      static_cast<double>(record->raw.rf.center_frequency_hz) / 1000000.0);
        put_label(parent, line, 49, 124, theme::cyan(), &font_pixel_18x24);
        put_label(parent, "MHZ", 180, 136, theme::text_muted(), &font_pixel_6x8);
        std::snprintf(line, sizeof(line), "BW %uk  SF%u  PRE %u",
                      static_cast<unsigned>(record->raw.rf.bandwidth_hz / 1000U),
                      record->raw.rf.spreading_factor, record->raw.rf.preamble_symbols);
        put_label(parent, line, 49, 154, theme::text(), &font_pixel_6x8);
        char coding_rate[8]{};
        if(record->raw.rf.hasField(RfFieldCodingRate)) {
            std::snprintf(coding_rate, sizeof(coding_rate), "4/%u",
                          record->raw.rf.coding_rate_denominator);
        } else {
            std::snprintf(coding_rate, sizeof(coding_rate), "--");
        }
        std::snprintf(line, sizeof(line), "CR %s  SYNC %04X  PRF %u",
                      coding_rate, record->raw.rf.sync_word, record->raw.rf.profile_id);
        put_label(parent, line, 49, 168, theme::text(), &font_pixel_6x8);
        char airtime[16]{};
        char frequency_error[20]{};
        if(record->raw.rf.hasField(RfFieldAirtime)) {
            std::snprintf(airtime, sizeof(airtime), "%.2fMS",
                          static_cast<double>(record->raw.rf.airtime_us) / 1000.0);
        } else {
            std::snprintf(airtime, sizeof(airtime), "--");
        }
        if(record->raw.rf.hasField(RfFieldFrequencyError)) {
            std::snprintf(frequency_error, sizeof(frequency_error), "%ldHZ",
                          static_cast<long>(record->raw.rf.frequency_error_hz));
        } else {
            std::snprintf(frequency_error, sizeof(frequency_error), "--");
        }
        std::snprintf(line, sizeof(line), "AIR %s  ERR %s", airtime, frequency_error);
        put_label(parent, line, 49, 182, theme::text(), &font_pixel_6x8);
        put_label(parent, "BLANK WHEN RADIO METADATA IS MISSING",
                  49, 196, theme::text_muted(), &font_pixel_6x8);
    } else if(packet_detail_tab == 2U) {
        const lv_color_t state_color =
            shown.state == DecodeState::Malformed ? theme::fault() :
            (opened_by_stored_key ? theme::amber() : theme::lime());
        put_label(parent, "STATE", 49, 112, theme::pink(), &font_pixel_6x8);
        put_label(parent, decodeStateLabel(shown.state), 49, 124,
                  state_color, &font_pixel_18x24);
        put_label(parent, "KIND", 49, 154, theme::pink(), &font_pixel_6x8);
        put_label(parent, packetKindLabel(shown), 85, 154,
                  theme::text(), &font_pixel_6x8);
        // A readable message gives its rows to the message: the port it was
        // addressed to, the key that opened it, and the text itself. The key is
        // stated so nobody mistakes a default-key read for broken encryption --
        // and so nobody mistakes a channel they were given the secret for for
        // one anybody within earshot could read. The default key stays lime
        // because it carries the stronger claim, that this traffic was never
        // private; a stored key gets the amber a via-net frame wears, the shade
        // this firmware uses for a result with a caveat attached.
        if(has_readable) {
            char provenance[8 + kChannelKeyNameCapacity]{};
            format_key_provenance(provenance, sizeof(provenance), key_state);
            put_label(parent, "PORT", 49, 168, theme::pink(), &font_pixel_6x8);
            std::snprintf(line, sizeof(line), "%s  %s",
                          meshtasticPortLabel(readable.portnum), provenance);
            put_label(parent, line, 85, 168,
                      opened_by_stored_key ? theme::amber() : theme::lime(), &font_pixel_6x8);
            if(readable.has_text) {
                put_label(parent, "MSG", 49, 182, theme::pink(), &font_pixel_6x8);
                lv_obj_t *message = put_label(parent, readable.text, 85, 182, theme::cyan(),
                                              &font_mono_10);
                lv_obj_set_width(message, theme::screen_width - 94);
                lv_label_set_long_mode(message, LV_LABEL_LONG_WRAP);
            } else {
                std::snprintf(line, sizeof(line), "%u B APP PAYLOAD",
                              static_cast<unsigned>(readable.payload_length));
                put_label(parent, line, 49, 182, theme::text(), &font_pixel_6x8);
            }
        }
        // A Reticulum payload is very often an LXMF message. Without this the
        // tab could say a data packet arrived and nothing about what it said.
        if(!has_readable && record->decoded.protocol == ProtocolId::Reticulum &&
           record->decoded.payload_length > 0U &&
           record->raw.captured_length >=
               static_cast<std::uint16_t>(record->decoded.payload_offset +
                                          record->decoded.payload_length)) {
            LxmfMessage lxmf{};
            if(readLxmfMessage(&record->raw.bytes[record->decoded.payload_offset],
                               record->decoded.payload_length, lxmf)) {
                put_label(parent, "LXMF", 49, 168, theme::pink(), &font_pixel_6x8);
                if(lxmf.has_title) {
                    put_clipped_label(parent, lxmf.title, 85, 168, 220, theme::lime(),
                                      &font_pixel_6x8);
                } else if(lxmf.field_count > 0U) {
                    std::snprintf(line, sizeof(line), "%u FIELDS",
                                  static_cast<unsigned>(lxmf.field_count));
                    put_label(parent, line, 85, 168, theme::lime(), &font_pixel_6x8);
                } else {
                    put_label(parent, "MESSAGE", 85, 168, theme::lime(), &font_pixel_6x8);
                }
                if(lxmf.has_content) {
                    put_label(parent, "MSG", 49, 182, theme::pink(), &font_pixel_6x8);
                    lv_obj_t *body = put_label(parent, lxmf.content, 85, 182, theme::cyan(),
                                               &font_mono_10);
                    lv_obj_set_width(body, theme::screen_width - 94);
                    lv_label_set_long_mode(body, LV_LABEL_LONG_WRAP);
                } else {
                    put_label(parent, "NO MESSAGE BODY", 49, 182, theme::text_muted(),
                              &font_pixel_6x8);
                }
            }
        }
        // A pointer frame gives its diagnostics rows to the pointer itself:
        // the same commitment the web analyzer resolves, decoded from the raw
        // bytes on the device, is the story this tab exists to tell.
        ShelbyPointer shelby_pointer{};
        if(decode_frame_shelby_pointer(*record, shelby_pointer)) {
            std::snprintf(line, sizeof(line), "SHELBY POINTER  %s  CHUNK %u/%u",
                          shelby_pointer.isCapture() ? "CAPTURE" : "BLOB",
                          static_cast<unsigned>(shelby_pointer.chunk_index) + 1U,
                          static_cast<unsigned>(shelby_pointer.chunk_count));
            put_label(parent, line, 49, 168, theme::cyan(), &font_pixel_6x8);
            std::snprintf(line, sizeof(line), "COMMIT 0x%02x%02x%02x%02x..%02x%02x%02x%02x",
                          shelby_pointer.commitment[0], shelby_pointer.commitment[1],
                          shelby_pointer.commitment[2], shelby_pointer.commitment[3],
                          shelby_pointer.commitment[28], shelby_pointer.commitment[29],
                          shelby_pointer.commitment[30], shelby_pointer.commitment[31]);
            put_label(parent, line, 49, 182, theme::text(), &font_mono_10);
            char expiry[16]{};
            format_unix_date(shelby_pointer.expires_at_unix, expiry, sizeof(expiry));
            std::snprintf(line, sizeof(line), "%lu B ON SHELBYNET  EXPIRES %s",
                          static_cast<unsigned long>(shelby_pointer.size_bytes), expiry);
            put_label(parent, line, 49, 196, theme::lime(), &font_pixel_6x8);
        } else if (!has_readable) {
            std::snprintf(line, sizeof(line), "FIELDS %08lX  ATTR %04X",
                          static_cast<unsigned long>(record->decoded.present_fields),
                          record->decoded.attributes);
            put_label(parent, line, 49, 168, theme::text(), &font_pixel_6x8);
            std::snprintf(line, sizeof(line), "PAY %u @ %u  FLAGS %08lX",
                          record->decoded.payload_length, record->decoded.payload_offset,
                          static_cast<unsigned long>(record->decoded.protocol_flags));
            put_label(parent, line, 49, 182, theme::text(), &font_pixel_6x8);
            format_protocol_detail();
            put_clipped_label(parent, line, 49, 196, 260, theme::cyan(),
                              &font_pixel_6x8);
        }
    } else if(packet_detail_tab == 3U) {
        constexpr std::size_t bytes_per_page = 40U;
        const std::size_t byte_count = record->raw.captured_length;
        const std::size_t page_count = byte_count == 0U ? 1U :
                                       (byte_count + bytes_per_page - 1U) / bytes_per_page;
        if(packet_detail_byte_offset >= byte_count && byte_count != 0U) {
            packet_detail_byte_offset = (page_count - 1U) * bytes_per_page;
        }
        const std::size_t page_index = packet_detail_byte_offset / bytes_per_page;
        const std::size_t last_byte = byte_count == 0U ? 0U :
                                      ((packet_detail_byte_offset + bytes_per_page) < byte_count
                                           ? packet_detail_byte_offset + bytes_per_page : byte_count);
        put_label(parent, "BYTES", 49, 112, theme::pink(), &font_pixel_6x8);
        std::snprintf(line, sizeof(line), "%u-%u/%u",
                      byte_count == 0U ? 0U : static_cast<unsigned>(packet_detail_byte_offset),
                      byte_count == 0U ? 0U : static_cast<unsigned>(last_byte - 1U),
                      static_cast<unsigned>(byte_count));
        put_label(parent, line, 49, 124, theme::cyan(), &font_pixel_18x24);
        for(std::size_t row = 0; row < 4; ++row) {
            char hex[48]{};
            std::size_t cursor = 0;
            for(std::size_t column = 0; column < 10; ++column) {
                const std::size_t offset = packet_detail_byte_offset + row * 10U + column;
                if(offset >= record->raw.captured_length || cursor + 4 >= sizeof(hex)) break;
                cursor += static_cast<std::size_t>(std::snprintf(
                    hex + cursor, sizeof(hex) - cursor, "%02X ", record->raw.bytes[offset]));
            }
            put_label(parent, hex, 49, 152 + static_cast<lv_coord_t>(row) * 12,
                      row == 0 ? theme::text() : theme::text_muted(), &font_mono_10);
        }
        std::snprintf(line, sizeof(line), "UP/DOWN  PAGE %u/%u",
                      static_cast<unsigned>(page_index + 1U), static_cast<unsigned>(page_count));
        put_label(parent, line, 49, 196, theme::pink(), &font_pixel_6x8);
    } else {
        const std::uint32_t fingerprint = packet_fingerprint(record->raw.bytes,
                                                              record->raw.captured_length);
        put_label(parent, "WRITER", 49, 112, theme::pink(), &font_pixel_6x8);
        put_label(parent, "STATE", 49, 124, theme::text(), &font_pixel_18x24);
        std::snprintf(line, sizeof(line), "FRAME #%llu  RADIO %u  ST %d",
                      static_cast<unsigned long long>(record->sequence),
                      record->raw.rf.radio_index, record->raw.rf.radio_status);
        put_label(parent, line, 49, 154, theme::text(), &font_pixel_6x8);
        std::snprintf(line, sizeof(line), "CAP %u  ORIG %u  %s",
                      record->raw.captured_length, record->raw.original_length,
                      record->raw.wasTruncated() ? "TRUNCATED" : "COMPLETE");
        put_label(parent, line, 49, 168,
                  record->raw.wasTruncated() ? theme::amber() : theme::lime(), &font_pixel_6x8);
        const char *origin = record->raw.rf.origin == FrameOrigin::Synthetic ? "SYNTHETIC" :
                             (record->raw.rf.origin == FrameOrigin::Net ? "NET" :
                              (record->raw.rf.origin == FrameOrigin::Radio ? "RADIO" : "UNKNOWN"));
        std::snprintf(line, sizeof(line), "ORIGIN %s%s", origin,
                      record->raw.rf.origin == FrameOrigin::Synthetic ||
                              record->raw.rf.origin == FrameOrigin::Net
                          ? " / NOT OTA" : "");
        put_label(parent, line, 49, 182, theme::text(), &font_pixel_6x8);
        if(record->raw.rf.origin == FrameOrigin::Synthetic) {
            std::snprintf(line, sizeof(line), "FNV32 %08lX   LSCAP %s  PCAP SKIP",
                          static_cast<unsigned long>(fingerprint),
                          native_capture_recording ? "SIM" : "OFF");
        } else {
            std::snprintf(line, sizeof(line), "FNV32 %08lX   LSCAP %s  PCAP %s",
                          static_cast<unsigned long>(fingerprint),
                          native_capture_recording ? "ON" : "OFF",
                          pcap_recording ? "ON" : "OFF");
        }
        put_label(parent, line, 49, 196, theme::cyan(), &font_pixel_6x8);
    }

    draw_back_strip(parent);
    return;
    }
#else
    if(!simulator_packet_detail_sample_valid) (void)select_simulator_packet_for_detail();
    const simulator::TrafficSample &selected_packet = simulator_packet_detail_sample;
    DecodedPacket simulated_decoded{};
    const bool simulator_decoder_attributed =
        decode_simulator_packet(selected_packet, simulated_decoded);
    const bool has_structural_decode =
        simulator_decoder_attributed && simulated_decoded.state != DecodeState::Malformed;
    const bool has_source_identity =
        has_structural_decode &&
        selected_packet.source_node != simulator::kNoNode &&
        selected_packet.source_node < simulator::kNodeCount;
    char packet_time[12]{};
    format_simulator_clock(packet_time, sizeof(packet_time),
                           selected_packet.timestamp_seconds_of_day);
    add_status_bar(parent, "PACKET", "BAT 87%",
                   app_settings.gps_enabled ? "GPS ON" : "GPS OFF", packet_time);
    add_packet_detail_tabs(parent);

    char detail_line[72]{};
    char source_id[12]{};
    char destination_id[12]{};
    format_simulator_node_id(source_id, sizeof(source_id), selected_packet.source_node, false);
    format_simulator_node_id(destination_id, sizeof(destination_id),
                             selected_packet.destination_node, has_source_identity);
    put_label(parent, "SRC", 49, 29, theme::pink(), &font_pixel_6x8);
    put_label(parent, has_source_identity ? source_id : "--", 73, 29,
              theme::text(), &font_pixel_6x8);
    put_label(parent, "DST", 161, 29, theme::pink(), &font_pixel_6x8);
    put_label(parent, has_source_identity ? destination_id : "--", 185, 29,
              theme::text(), &font_pixel_6x8);
    const char *packet_kind = simulator_packet_kind_label(selected_packet);
    std::snprintf(detail_line, sizeof(detail_line), "%s  %s  %s  %u B",
                  simulator_protocol_label(selected_packet.protocol),
                  packet_kind, decodeStateLabel(simulated_decoded.state),
                  static_cast<unsigned>(selected_packet.captured_bytes));
    put_label(parent, detail_line, 49, 50,
              simulated_decoded.state == DecodeState::Malformed
                  ? theme::fault() : theme::amber(), &font_mono_10);
    std::snprintf(detail_line, sizeof(detail_line), "SF%u  BW %.1fk  CR4/%u  0x%04X",
                  selected_packet.spreading_factor,
                  static_cast<double>(selected_packet.bandwidth_hz) / 1000.0,
                  selected_packet.coding_rate_denominator, selected_packet.sync_word);
    put_label(parent, detail_line, 49, 67, theme::text(), &font_mono_10);
    std::snprintf(detail_line, sizeof(detail_line), "RSSI %.1f  SNR %+.1f DB  CRC %s",
                  static_cast<double>(selected_packet.rssi_dbm_x10) / 10.0,
                  static_cast<double>(selected_packet.snr_db_x10) / 10.0,
                  selected_packet.crc_valid ? "OK" : "BAD");
    put_label(parent, detail_line, 49, 84,
              selected_packet.crc_valid ? theme::lime() : theme::fault(), &font_mono_10);
    theme::rule_line(parent, 47, 103, 266);
    constexpr std::size_t bytes_per_page = 40U;
    const std::size_t byte_count = selected_packet.captured_bytes;
    const std::size_t page_count = (byte_count + bytes_per_page - 1U) / bytes_per_page;
    auto simulated_byte = [&](std::size_t offset) {
        return selected_packet.byteAt(offset);
    };
    auto format_simulated_protocol_detail = [&]() {
        if(!simulator_decoder_attributed) {
            std::snprintf(detail_line, sizeof(detail_line), "UNCLASSIFIED / RAW BYTES ONLY");
        } else if(simulated_decoded.state == DecodeState::Malformed &&
                  (simulated_decoded.present_fields &
                   ~static_cast<std::uint32_t>(FieldPayload)) == 0U) {
            std::snprintf(detail_line, sizeof(detail_line), "STRUCTURE INVALID / NO SAFE HEADER FACTS");
        } else if(simulated_decoded.protocol == ProtocolId::MeshCore &&
                  simulated_decoded.state != DecodeState::Malformed) {
            std::snprintf(detail_line, sizeof(detail_line), "ROUTE %u  TYPE %s  PATH %ux%u",
                          static_cast<unsigned>(MeshCoreDecoder::routeType(simulated_decoded)),
                          packetKindLabel(simulated_decoded),
                          static_cast<unsigned>(MeshCoreDecoder::pathHashCount(simulated_decoded)),
                          static_cast<unsigned>(MeshCoreDecoder::pathHashSize(simulated_decoded)));
        } else if(simulated_decoded.protocol == ProtocolId::Reticulum &&
                  simulated_decoded.state != DecodeState::Malformed) {
            std::snprintf(detail_line, sizeof(detail_line), "H%u  HOPS %u  DEST PREFIX %08lX",
                          ReticulumDecoder::headerType(simulated_decoded) ==
                              ReticulumHeaderType::HeaderTwo ? 2U : 1U,
                          static_cast<unsigned>(ReticulumDecoder::observedHops(simulated_decoded)),
                          static_cast<unsigned long>(
                              ReticulumDecoder::destinationHashPrefix(simulated_decoded)));
        } else if(simulated_decoded.hasField(FieldPacketId)) {
            std::snprintf(detail_line, sizeof(detail_line), "ID %08lX  CH %02X  HOPS %u/%u",
                          static_cast<unsigned long>(simulated_decoded.packet_id),
                          static_cast<unsigned>(simulated_decoded.channel),
                          simulated_decoded.hop_limit, simulated_decoded.hop_start);
        } else {
            std::snprintf(detail_line, sizeof(detail_line), "FLAGS 0x%08lX  OFFSET %u",
                          static_cast<unsigned long>(simulated_decoded.protocol_flags),
                          simulated_decoded.payload_offset);
        }
    };
    if(packet_detail_tab == 0U) {
        format_simulated_protocol_detail();
        put_label(parent, detail_line, 49, 116, theme::cyan(), &font_mono_10);
        std::snprintf(detail_line, sizeof(detail_line), "FRAME #%llu   CAPTURED %u / ORIGINAL %u",
                      static_cast<unsigned long long>(selected_packet.sequence),
                      static_cast<unsigned>(selected_packet.captured_bytes),
                      static_cast<unsigned>(selected_packet.captured_bytes));
        put_label(parent, detail_line, 49, 139, theme::text(), &font_mono_10);
        if(has_structural_decode) {
            std::snprintf(detail_line, sizeof(detail_line), "PAYLOAD OFFSET %u   LENGTH %u",
                          static_cast<unsigned>(selected_packet.payload_offset),
                          static_cast<unsigned>(selected_packet.payload_bytes));
        } else {
            std::snprintf(detail_line, sizeof(detail_line), "PAYLOAD --   RAW CAPTURE %u B",
                          static_cast<unsigned>(selected_packet.captured_bytes));
        }
        put_label(parent, detail_line, 49, 158, theme::text(), &font_mono_10);
        std::snprintf(detail_line, sizeof(detail_line), "CAPTURE TIME %s", packet_time);
        put_label(parent, detail_line, 49, 181, theme::text_muted(), &font_mono_10);
    } else if(packet_detail_tab == 1U) {
        put_label(parent, "CENTER", 49, 112, theme::pink(), &font_pixel_6x8);
        std::snprintf(detail_line, sizeof(detail_line), "%.3f",
                      static_cast<double>(selected_packet.center_frequency_hz) / 1000000.0);
        put_label(parent, detail_line, 49, 124, theme::cyan(), &font_pixel_18x24);
        put_label(parent, "MHZ", 180, 136, theme::text_muted(), &font_pixel_6x8);
        std::snprintf(detail_line, sizeof(detail_line), "BW %uk  SF%u  PRE %u",
                      static_cast<unsigned>(selected_packet.bandwidth_hz / 1000U),
                      selected_packet.spreading_factor,
                      selected_packet.preamble_symbols);
        put_label(parent, detail_line, 49, 154, theme::text(), &font_pixel_6x8);
        std::snprintf(detail_line, sizeof(detail_line), "CR 4/%u  SYNC %04X  PRF %u",
                      selected_packet.coding_rate_denominator,
                      selected_packet.sync_word, selected_packet.profile_id);
        put_label(parent, detail_line, 49, 168, theme::text(), &font_pixel_6x8);
        char frequency_error[20]{};
        if(selected_packet.has_frequency_error) {
            std::snprintf(frequency_error, sizeof(frequency_error), "%ldHZ",
                          static_cast<long>(selected_packet.frequency_error_hz));
        } else {
            std::snprintf(frequency_error, sizeof(frequency_error), "--");
        }
        std::snprintf(detail_line, sizeof(detail_line), "AIR %.2fMS  ERR %s",
                      static_cast<double>(selected_packet.airtime_us) / 1000.0,
                      frequency_error);
        put_label(parent, detail_line, 49, 182, theme::text(), &font_pixel_6x8);
        put_label(parent, "RF VALUES STAY WITH THIS FRAME", 49, 196,
                  theme::text_muted(), &font_pixel_6x8);
    } else if(packet_detail_tab == 2U) {
        const lv_color_t state_color =
            simulated_decoded.state == DecodeState::Malformed
                ? theme::fault() : theme::lime();
        put_label(parent, "STATE", 49, 112, theme::pink(), &font_pixel_6x8);
        put_label(parent, decodeStateLabel(simulated_decoded.state), 49, 124,
                  state_color, &font_pixel_18x24);
        put_label(parent, "KIND", 49, 154, theme::pink(), &font_pixel_6x8);
        put_label(parent, packetKindLabel(simulated_decoded), 85, 154,
                  theme::text(), &font_pixel_6x8);
        std::snprintf(detail_line, sizeof(detail_line), "FIELDS %08lX  ATTR %04X",
                      static_cast<unsigned long>(simulated_decoded.present_fields),
                      simulated_decoded.attributes);
        put_label(parent, detail_line, 49, 168, theme::text(), &font_pixel_6x8);
        std::snprintf(detail_line, sizeof(detail_line), "PAY %u @ %u  FLAGS %08lX",
                      simulated_decoded.payload_length, simulated_decoded.payload_offset,
                      static_cast<unsigned long>(simulated_decoded.protocol_flags));
        put_label(parent, detail_line, 49, 182, theme::text(), &font_pixel_6x8);
        format_simulated_protocol_detail();
        put_clipped_label(parent, detail_line, 49, 196, 260, theme::cyan(),
                          &font_pixel_6x8);
    } else if(packet_detail_tab == 3U) {
        if(packet_detail_byte_offset >= byte_count) {
            packet_detail_byte_offset = (page_count - 1U) * bytes_per_page;
        }
        const std::size_t page_index = packet_detail_byte_offset / bytes_per_page;
        const std::size_t last_byte = (packet_detail_byte_offset + bytes_per_page) < byte_count
            ? packet_detail_byte_offset + bytes_per_page : byte_count;
        put_label(parent, "BYTES", 49, 112, theme::pink(), &font_pixel_6x8);
        std::snprintf(detail_line, sizeof(detail_line), "%u-%u/%u",
                      static_cast<unsigned>(packet_detail_byte_offset),
                      static_cast<unsigned>(last_byte - 1U), static_cast<unsigned>(byte_count));
        put_label(parent, detail_line, 49, 124, theme::cyan(), &font_pixel_18x24);
        for(std::size_t row = 0; row < 4U; ++row) {
            char hex[48]{};
            std::size_t cursor = 0U;
            for(std::size_t column = 0; column < 10U; ++column) {
                const std::size_t offset = packet_detail_byte_offset + row * 10U + column;
                if(offset >= byte_count || cursor + 4U >= sizeof(hex)) break;
                cursor += static_cast<std::size_t>(std::snprintf(
                    hex + cursor, sizeof(hex) - cursor, "%02X ", simulated_byte(offset)));
            }
            put_label(parent, hex, 49, 152 + static_cast<lv_coord_t>(row) * 12,
                      row == 0U ? theme::text() : theme::text_muted(), &font_mono_10);
        }
        std::snprintf(detail_line, sizeof(detail_line), "UP/DOWN  PAGE %u/%u",
                      static_cast<unsigned>(page_index + 1U), static_cast<unsigned>(page_count));
        put_label(parent, detail_line, 49, 196, theme::pink(), &font_pixel_6x8);
    } else {
        std::uint32_t fingerprint = 2166136261U;
        for(std::size_t offset = 0U; offset < byte_count; ++offset) {
            fingerprint ^= simulated_byte(offset);
            fingerprint *= 16777619U;
        }
        put_label(parent, "WRITER", 49, 112, theme::pink(), &font_pixel_6x8);
        put_label(parent, "STATE", 49, 124, theme::text(), &font_pixel_18x24);
        std::snprintf(detail_line, sizeof(detail_line), "FRAME #%llu  RADIO 0  RX",
                      static_cast<unsigned long long>(selected_packet.sequence));
        put_label(parent, detail_line, 49, 154, theme::text(), &font_pixel_6x8);
        std::snprintf(detail_line, sizeof(detail_line), "CAP %u  ORIG %u  COMPLETE",
                      static_cast<unsigned>(selected_packet.captured_bytes),
                      static_cast<unsigned>(selected_packet.captured_bytes));
        put_label(parent, detail_line, 49, 168, theme::lime(), &font_pixel_6x8);
        std::snprintf(detail_line, sizeof(detail_line), "FNV32 %08lX",
                      static_cast<unsigned long>(fingerprint));
        put_label(parent, detail_line, 49, 182, theme::text(), &font_pixel_6x8);
        put_label(parent,
                  app_settings.capture_enabled
                      ? "LSCAP REC  PCAP REC"
                      : "LSCAP OFF  PCAP OFF",
                  49, 196, app_settings.capture_enabled ? theme::cyan() : theme::amber(),
                  &font_pixel_6x8);
    }

    draw_back_strip(parent);
#endif
}

void build_map(lv_obj_t * parent)
{
#if defined(LILYSHARK_DEVICE)
    {
    add_status_bar(parent, "MAP");
    const GpsStatus &gps = hardware_status.snapshot().gps;
    std::array<LiveNodeSummary, 8> live_nodes{};
    const std::size_t count = collect_live_nodes(live_nodes);
    double origin_lat = 0.0;
    double origin_lon = 0.0;
    // Where the map is centred, best evidence first:
    //   1. this deck's own GPS -- it is the deck being placed, so its own
    //      receiver is the authority whenever it has a fix;
    //   2. the phone's, shared over Bluetooth. Indoors the deck's patch
    //      antenna frequently never fixes at all, and the map then had
    //      nothing better than the average of whatever nodes happened to
    //      report a position -- which is not where you are, and is why this
    //      screen could sit over the middle of the bay while you stood in a
    //      building;
    //   3. that average, still, when there is no fix anywhere.
    // The HUD says which of the three it is; a map that will not say where
    // its centre came from is guessing at the reader's expense.
    bool have_origin = gps.state == GpsState::Fix && gps.position_valid;
    const bool origin_from_phone = !have_origin && phone_fix_usable(millis());
    if (origin_from_phone) {
        map_smooth_position(phone_fix.latitude_degrees, phone_fix.longitude_degrees,
                            origin_lat, origin_lon);
        have_origin = true;
        if (map_panned) {
            const double pan_rad = origin_lat * 0.017453292519943295;
            origin_lat += map_pan_north_m / 110540.0;
            origin_lon += map_pan_east_m / (111320.0 * std::cos(pan_rad));
        }
    } else if (have_origin) {
        map_smooth_position(gps.latitude_degrees, gps.longitude_degrees,
                            origin_lat, origin_lon);
        if (map_panned) {
            // Shift the view by the drag, in metres, so the same ground stays
            // under the finger when the zoom changes.
            const double pan_rad = origin_lat * 0.017453292519943295;
            origin_lat += map_pan_north_m / 110540.0;
            origin_lon += map_pan_east_m / (111320.0 * std::cos(pan_rad));
        }
    } else {
        std::size_t positioned = 0;
        for (std::size_t index = 0; index < count; ++index) {
            if (!live_nodes[index].has_position) continue;
            origin_lat += live_nodes[index].latitude_degrees;
            origin_lon += live_nodes[index].longitude_degrees;
            ++positioned;
        }
        if (positioned > 0U) {
            origin_lat /= static_cast<double>(positioned);
            origin_lon /= static_cast<double>(positioned);
            have_origin = true;
        }
    }
    std::array<MapMark, 9> marks{};
    std::size_t mark_count = 0;
    std::size_t unfixed = 0;
    if (have_origin) {
        // Named for where the fix came from. "YOU" on a phone fix is close
        // enough to be useful and wrong enough to matter -- it is the phone
        // that is there, and the deck only probably.
        marks[mark_count++] = {origin_from_phone ? "PHONE" : "YOU",
                               0.0, 0.0, true, false, -1};
        const double lat_rad = origin_lat * 0.017453292519943295;
        const double m_per_lat = 110540.0;
        const double m_per_lon = 111320.0 * std::cos(lat_rad);
        const std::size_t selected = count == 0U ? 0U : resolve_node_selection(live_nodes, count);
        for (std::size_t index = 0; index < count; ++index) {
            if (!live_nodes[index].has_position) {
                ++unfixed;
                continue;
            }
            if (mark_count >= marks.size()) continue;
            MapMark mark{};
            mark.name = live_nodes[index].label[0] != '\0' ? live_nodes[index].label : "NODE";
            mark.east_m = (live_nodes[index].longitude_degrees - origin_lon) * m_per_lon;
            mark.north_m = (live_nodes[index].latitude_degrees - origin_lat) * m_per_lat;
            mark.selected = index == selected;
            mark.node_index = static_cast<int>(index);
            marks[mark_count++] = mark;
        }
    } else {
        for (std::size_t index = 0; index < count; ++index) {
            if (!live_nodes[index].has_position) ++unfixed;
        }
    }
    char fix_line[40]{};
    char detail[24]{};
    if (have_origin) {
        format_hemisphere_fix(fix_line, sizeof(fix_line), origin_lat, origin_lon);
        if (origin_from_phone) {
            // Said outright. These coordinates are the PHONE's, and a reader
            // deciding whether to walk somewhere is owed the difference
            // between a fix this radio took and one it was handed.
            const std::size_t used = std::strlen(fix_line);
            std::snprintf(fix_line + used, sizeof(fix_line) - used, "  VIA PHONE");
            std::snprintf(detail, sizeof(detail), "PHONE GPS");
        } else if (gps.state == GpsState::Fix && gps.position_valid) {
            if (unfixed > 0U) {
                std::snprintf(detail, sizeof(detail), "SAT %u +%u",
                              static_cast<unsigned>(gps.satellites),
                              static_cast<unsigned>(unfixed));
            } else {
                std::snprintf(detail, sizeof(detail), "SAT %u",
                              static_cast<unsigned>(gps.satellites));
            }
        } else if (unfixed > 0U) {
            std::snprintf(detail, sizeof(detail), "NET +%u", static_cast<unsigned>(unfixed));
        } else {
            std::snprintf(detail, sizeof(detail), "NET");
        }
        const double mpp = map_meters_per_pixel(origin_lat);
#if defined(ESP_PLATFORM)
        (void)ensure_field_map(origin_lat, origin_lon);
#endif
        const double accuracy_m = (gps.state == GpsState::Fix && gps.position_valid)
            ? map_fix_accuracy_m(gps.hdop, gps.satellites) : 0.0;
        plot_field_map(parent, marks.data(), mark_count, fix_line, detail, mpp,
                       origin_lat, origin_lon, accuracy_m, false);
    } else {
        // Same plain language as the status bar: the operator wants to know
        // whether a position exists, not which internal state the receiver is
        // in. Device Status still shows the detail.
        const char *reason = gps.state == GpsState::Disabled ? "GPS OFF"
                                                             : "FINDING GPS";
        // A black grid tells the operator nothing. While GPS acquires, show
        // the baked imagery for the area the device was provisioned for, and
        // only fall back to the muted grid when there is genuinely no map to
        // draw. The centre used to be hardcoded to San Francisco.
        // ensure_field_map needs the PSRAM tile buffer, which only exists on
        // the real board; the host device-shell tests build this file without
        // ESP_PLATFORM and simply get the muted grid.
        double fallback_lat = 37.775;
        double fallback_lon = -122.419;
        bool have_imagery = false;
#if defined(ESP_PLATFORM)
        if(::lilyshark::hasBakedMapTiles()) {
            fallback_lat = ::lilyshark::bakedMapTileLat();
            fallback_lon = ::lilyshark::bakedMapTileLon();
            have_imagery = ensure_field_map(fallback_lat, fallback_lon);
        }
#endif
        plot_field_map(parent, nullptr, 0, "NO FIX", reason,
                       map_meters_per_pixel(fallback_lat), fallback_lat,
                       fallback_lon, 0.0, !have_imagery);
    }
    return;
    }
#else
    add_simulator_live_status_bar(parent, "MAP");
    if (!app_settings.gps_enabled) {
        plot_field_map(parent, nullptr, 0, "NO FIX", "GPS OFF",
                       map_meters_per_pixel(37.775), 37.775, -122.419, 0.0, true);
        return;
    }
    double view_lat = 37.77490;
    double view_lon = -122.41940;
    simulator_you_latlon(view_lat, view_lon);
    const double lat_rad = view_lat * 0.017453292519943295;
    const double m_per_lat = 110540.0;
    const double m_per_lon = 111320.0 * std::cos(lat_rad);
    const std::size_t selected = resolve_simulator_node_selection();
    const std::size_t heard = simulator_established_node_count();
    std::array<MapMark, 9> marks{};
    std::size_t mark_count = 0;
    marks[mark_count++] = {"YOU", 0.0, 0.0, true, false, -1};
    const std::size_t shown = heard < kFieldPeers.size() ? heard : kFieldPeers.size();
    for (std::size_t index = 0; index < shown; ++index) {
        MapMark mark{};
        mark.name = kFieldPeers[index].name;
        mark.east_m = (kFieldPeers[index].lon - view_lon) * m_per_lon;
        mark.north_m = (kFieldPeers[index].lat - view_lat) * m_per_lat;
        mark.selected = index == selected;
        mark.node_index = static_cast<int>(index);
        marks[mark_count++] = mark;
    }
    char fix_line[40]{};
    char detail[20]{};
    format_hemisphere_fix(fix_line, sizeof(fix_line), view_lat, view_lon);
    const std::uint8_t sats = static_cast<std::uint8_t>(
        9U + static_cast<std::uint32_t>(simulator_live_telemetry.tick() / 4U) % 4U);
    std::snprintf(detail, sizeof(detail), "SAT %u", static_cast<unsigned>(sats));
    (void)ensure_field_map(view_lat, view_lon);
    plot_field_map(parent, marks.data(), mark_count, fix_line, detail,
                   map_meters_per_pixel(view_lat), view_lat, view_lon,
                   map_fix_accuracy_m(0.0f, sats), false);
#endif
}

void build_survey(lv_obj_t * parent)
{
#if defined(LILYSHARK_DEVICE)
    {
    add_status_bar(parent, "SURVEY");
    const std::uint32_t elapsed_ms = survey_running
        ? survey_elapsed_ms : (survey_has_result ? 60000U : 0U);
    const std::uint32_t bounded_ms = elapsed_ms > 60000U ? 60000U : elapsed_ms;
    const SurveySnapshot &survey = survey_accumulator.snapshot();

    put_label(parent, survey_running ? "CAPTURING" : (survey_has_result ? "COMPLETE" : "READY"),
              10, 40,
              survey_running ? theme::amber() : theme::lime(), &font_pixel_18x24);
    char line[64]{};
    std::snprintf(line, sizeof(line), "%luS/60S", static_cast<unsigned long>(bounded_ms / 1000U));
    put_label(parent, line, 248, 88, theme::lime(), &font_pixel_6x8);

    lv_obj_t *progress = theme::rect(parent, 9, 84, 221, 23, theme::background());
    lv_obj_set_style_border_width(progress, 1, 0);
    lv_obj_set_style_border_color(progress, theme::text_muted(), 0);
    const lv_coord_t fill = static_cast<lv_coord_t>((bounded_ms * 215ULL) / 60000ULL);
    if(fill > 0) theme::rect(progress, 3, 3, fill, 17, theme::lime());

    put_label(parent, "FRAMES", 10, 118, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%llu",
                  static_cast<unsigned long long>(survey.total_frames));
    put_label(parent, line, 10, 130, theme::text(), &font_pixel_18x24);
    put_label(parent, "SOURCES", 110, 118, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%u%s",
                  static_cast<unsigned>(survey.unique_sources),
                  survey.unique_sources_overflowed ? "+" : "");
    put_label(parent, line, 110, 130, theme::text(), &font_pixel_18x24);
    put_label(parent, "SNR", 220, 118, theme::pink(), &font_pixel_6x8);
    if (!survey.has_best_snr) std::snprintf(line, sizeof(line), "--");
    else std::snprintf(line, sizeof(line), "%+.1f",
                       static_cast<double>(survey.best_snr_db_x10) / 10.0);
    put_label(parent, line, 220, 130, theme::cyan(), &font_pixel_18x24);
    put_label(parent, "CRC", 10, 164, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%llu",
                  static_cast<unsigned long long>(survey.crc_invalid_frames));
    put_label(parent, line, 46, 164,
              survey.crc_invalid_frames == 0 ? theme::cyan() : theme::fault(),
              &font_pixel_6x8);
    draw_survey_result_actions(parent, survey_has_result && !survey_running);
    const bool spectrum_active = radio_service.spectrumStatus().active();
    const bool receive_paused = survey_running && !radio_service.status().receiving;
    const char *footer = spectrum_active ? "SPECTRUM SCANNING" :
        (receive_paused ? "RX PAUSED" :
         (survey_running ? "CAPTURING" :
          (survey_has_result ? "COMPLETE" : "READY")));
    draw_start_stop_strip(parent, footer,
                          spectrum_active || survey_running ? theme::amber() : theme::pink(),
                          survey_running ? "STOP" : "START",
                          !spectrum_active, survey_running);
    return;
    }
#else
    add_simulator_live_status_bar(parent, "SURVEY");
    const simulator::SurveySnapshot &survey = simulator_live_telemetry.survey();
    const char *state = survey.running ? "CAPTURING" : (survey.complete ? "COMPLETE" : "READY");
    put_label(parent, state, 10, 40,
              survey.running ? theme::amber() : theme::lime(),
              &font_pixel_18x24);
    char value[40]{};
    std::snprintf(value, sizeof(value), "%luS/60S",
                  static_cast<unsigned long>(survey.elapsed_ms / 1000U));
    put_label(parent, value, 248, 88, theme::lime(), &font_pixel_6x8);

    lv_obj_t * progress = theme::rect(parent, 9, 84, 221, 23, theme::background());
    lv_obj_set_style_border_width(progress, 1, 0);
    lv_obj_set_style_border_color(progress, theme::text_muted(), 0);
    const lv_coord_t fill = static_cast<lv_coord_t>(
        (static_cast<std::uint64_t>(survey.elapsed_ms) * 215ULL) / 60000ULL);
    if(fill > 0) theme::rect(progress, 3, 3, fill, 17, theme::lime());

    put_label(parent, "FRAMES", 10, 118, theme::pink(), &font_pixel_6x8);
    std::snprintf(value, sizeof(value), "%lu", static_cast<unsigned long>(survey.frames));
    put_label(parent, value, 10, 130, theme::text(), &font_pixel_18x24);
    put_label(parent, "SOURCES", 110, 118, theme::pink(), &font_pixel_6x8);
    std::snprintf(value, sizeof(value), "%u", static_cast<unsigned>(survey.nodes_heard));
    put_label(parent, value, 110, 130, theme::text(), &font_pixel_18x24);
    put_label(parent, "SNR", 220, 118, theme::pink(), &font_pixel_6x8);
    if (survey.frames == 0U) std::snprintf(value, sizeof(value), "--");
    else std::snprintf(value, sizeof(value), "%+.1f",
                       static_cast<double>(survey.best_snr_db_x10) / 10.0);
    put_label(parent, value, 220, 130, theme::cyan(), &font_pixel_18x24);
    put_label(parent, "CRC", 10, 164, theme::pink(), &font_pixel_6x8);
    std::snprintf(value, sizeof(value), "%lu",
                  static_cast<unsigned long>(survey.crc_invalid_frames));
    put_label(parent, value, 46, 164,
              survey.crc_invalid_frames == 0U ? theme::cyan() : theme::fault(),
              &font_pixel_6x8);
    draw_survey_result_actions(parent, survey.complete && !survey.running);
    const char *footer = simulator_spectrum_scanning ? "SPECTRUM SCANNING" :
        (survey.running ? "CAPTURING" :
         (survey.complete ? "COMPLETE" : "READY"));
    draw_start_stop_strip(parent, footer,
                          simulator_spectrum_scanning || survey.running ? theme::amber()
                                                                        : theme::pink(),
                          survey.running ? "STOP" : "START",
                          !simulator_spectrum_scanning, survey.running);
#endif
}

#if defined(LILYSHARK_DEVICE)
const char *runtime_event_type_label(RuntimeEventType type) noexcept
{
    switch(type) {
        case RuntimeEventType::System: return "SYSTEM";
        case RuntimeEventType::Radio: return "RADIO";
        case RuntimeEventType::Profile: return "PROFILE";
        case RuntimeEventType::Capture: return "CAPTURE";
        case RuntimeEventType::Storage: return "STORAGE";
        case RuntimeEventType::Spectrum: return "SPECTRUM";
        case RuntimeEventType::Screenshot: return "SCREENSHOT";
        case RuntimeEventType::Survey: return "SURVEY";
        case RuntimeEventType::Hardware: return "HARDWARE";
        case RuntimeEventType::Count: default: return "EVENT";
    }
}

lv_color_t runtime_event_color(RuntimeEventSeverity severity) noexcept
{
    switch(severity) {
        case RuntimeEventSeverity::Success: return theme::lime();
        case RuntimeEventSeverity::Warning: return theme::amber();
        case RuntimeEventSeverity::Error: return theme::fault();
        case RuntimeEventSeverity::Info:
        case RuntimeEventSeverity::Count:
        default: return theme::cyan();
    }
}

void record_runtime_event(RuntimeEventSeverity severity, RuntimeEventType type,
                          const char *message) noexcept
{
    DiagnosticObservation marker{};
    marker.timestamp_ms = static_cast<std::uint32_t>(esp_timer_get_time() / 1000ULL);
    marker.has_frame = false;
    marker.event_marker_count = 1U;
    (void)rolling_diagnostics.ingest(marker);
    const RuntimeEventAppendResult result = runtime_event_history.append(
        static_cast<std::uint64_t>(esp_timer_get_time()), severity, type, message);
    if(result != RuntimeEventAppendResult::Invalid &&
       app_shell.route() == ShellRoute::Analyzer && current_screen == Screen::events &&
       (events_scroll_offset > 0U || event_detail_open)) {
        constexpr std::size_t maximum_visible = kEventsVisible;
        const std::size_t maximum_offset = event_detail_open
            ? (runtime_event_history.empty() ? 0U : runtime_event_history.size() - 1U)
            : (runtime_event_history.size() > maximum_visible
                ? runtime_event_history.size() - maximum_visible : 0U);
        events_scroll_offset = events_scroll_offset < maximum_offset
            ? events_scroll_offset + 1U : maximum_offset;
    }
    live_data_dirty = true;
}
#endif

#if !defined(LILYSHARK_DEVICE)
const char *simulator_event_kind_label(simulator::SimulatedEventKind kind) noexcept
{
    switch(kind) {
        case simulator::SimulatedEventKind::NodeAppeared: return "NEW NODE";
        case simulator::SimulatedEventKind::HighUtilization: return "HIGH UTIL";
        case simulator::SimulatedEventKind::NodeSilent: return "NODE LOST";
        case simulator::SimulatedEventKind::Interference: return "STRONG INT";
        case simulator::SimulatedEventKind::TrafficBurst: return "RF BURST";
        case simulator::SimulatedEventKind::CaptureReady: return "CAPTURE";
        case simulator::SimulatedEventKind::SurveyComplete: return "SURVEY";
        default: return "EVENT";
    }
}

lv_color_t simulator_event_color(simulator::SimulatedEventSeverity severity) noexcept
{
    switch(severity) {
        case simulator::SimulatedEventSeverity::Success: return theme::lime();
        case simulator::SimulatedEventSeverity::Warning: return theme::amber();
        case simulator::SimulatedEventSeverity::Error: return theme::fault();
        case simulator::SimulatedEventSeverity::Info:
        default: return theme::cyan();
    }
}

void format_simulator_event_message(char *output, std::size_t capacity,
                                    const simulator::EventSample &event) noexcept
{
    switch(event.kind) {
        case simulator::SimulatedEventKind::NodeAppeared:
            std::snprintf(output, capacity, "%s APPEARED WITH SNR %+.1f DB",
                          simulator_node_name(event.node), static_cast<double>(event.value) / 10.0);
            break;
        case simulator::SimulatedEventKind::HighUtilization:
            std::snprintf(output, capacity, "CHANNEL UTILIZATION REACHED %ld%%",
                          static_cast<long>(event.value));
            break;
        case simulator::SimulatedEventKind::NodeSilent:
            std::snprintf(output, capacity, "%s SILENT FOR %ld MINUTES",
                          simulator_node_name(event.node), static_cast<long>(event.value));
            break;
        case simulator::SimulatedEventKind::Interference:
            std::snprintf(output, capacity, "INTERFERENCE SPIKE NEAR %.3f MHZ",
                          static_cast<double>(event.value) / 1000.0);
            break;
        case simulator::SimulatedEventKind::TrafficBurst:
            std::snprintf(output, capacity, "TRAFFIC BURST REACHED %ld PKT/MIN",
                          static_cast<long>(event.value));
            break;
        case simulator::SimulatedEventKind::SurveyComplete:
            std::snprintf(output, capacity, "60-SECOND SURVEY CAPTURED %ld FRAMES",
                          static_cast<long>(event.value));
            break;
        case simulator::SimulatedEventKind::CaptureReady:
        default:
            std::snprintf(output, capacity, "NATIVE CAPTURE AND PCAP WRITERS ARE READY");
            break;
    }
}
#endif

void build_event_detail(lv_obj_t *parent)
{
#if defined(LILYSHARK_DEVICE)
    add_status_bar(parent, "EVENT");
#else
    add_simulator_live_status_bar(parent, "EVENT");
#endif
    const char *time = "--:--";
    const char *kind = "EVENT";
    const char *message = "EVENT IS NO LONGER AVAILABLE.";
    lv_color_t color = theme::text_muted();
    char position[20]{};
#if !defined(LILYSHARK_DEVICE)
    char simulator_time[16]{};
    char simulator_message[112]{};
#endif
#if defined(LILYSHARK_DEVICE)
    const RuntimeEvent *event = runtime_event_history.newest(events_scroll_offset);
    if(event != nullptr) {
        const std::uint64_t uptime_seconds = event->timestamp_us / 1000000ULL;
        static char event_time[16]{};
        std::snprintf(event_time, sizeof(event_time), "%02llu:%02llu:%02llu",
                      static_cast<unsigned long long>((uptime_seconds / 3600ULL) % 100ULL),
                      static_cast<unsigned long long>((uptime_seconds / 60ULL) % 60ULL),
                      static_cast<unsigned long long>(uptime_seconds % 60ULL));
        time = event_time;
        kind = runtime_event_type_label(event->type);
        message = event->message;
        color = runtime_event_color(event->severity);
    }
    std::snprintf(position, sizeof(position), "EVENT %u OF %u",
                  static_cast<unsigned>(events_scroll_offset + 1U),
                  static_cast<unsigned>(runtime_event_history.size()));
#else
    const simulator::EventsSnapshot &events = simulator_live_telemetry.events();
    if(events.size == 0U) events_scroll_offset = 0U;
    else if(events_scroll_offset >= events.size) events_scroll_offset = events.size - 1U;
    const simulator::EventSample *event = events.newest(events_scroll_offset);
    if(event != nullptr) {
        format_simulator_clock(simulator_time, sizeof(simulator_time),
                               event->timestamp_seconds_of_day);
        format_simulator_event_message(simulator_message, sizeof(simulator_message), *event);
        time = simulator_time;
        kind = simulator_event_kind_label(event->kind);
        message = simulator_message;
        color = simulator_event_color(event->severity);
    }
    std::snprintf(position, sizeof(position), "EVENT %u OF %u",
                  static_cast<unsigned>(events_scroll_offset + 1U),
                  static_cast<unsigned>(events.size));
#endif

    put_label(parent, position, 8, 31, theme::pink(), &font_pixel_6x8);
    put_label(parent, time, 8, 46, color, &font_pixel_18x24);
    const lv_coord_t kind_x = 8 + static_cast<lv_coord_t>(std::strlen(time) * 18) + 10;
    put_label(parent, kind, kind_x > 200 ? 200 : kind_x, 56, color, &font_pixel_6x8);
    theme::rule_line(parent, 6, 76, 308, 1, theme::pink());
    char body[120]{};
    ascii_upper(body, sizeof(body), message);
    lv_obj_t *detail = theme::label(parent, body, theme::text(), &font_mono_10);
    lv_obj_set_pos(detail, 8, 88);
    lv_obj_set_size(detail, 304, 108);
    lv_label_set_long_mode(detail, LV_LABEL_LONG_WRAP);
    lv_obj_set_style_text_line_space(detail, 4, 0);
    draw_back_strip(parent);
    draw_outline_rect(parent, 72, kEventBackY, 32, kEventBackH, theme::pink());
    put_label(parent, "UP", 82, kEventBackY + 5, theme::pink(), &font_pixel_6x8);
    draw_outline_rect(parent, 112, kEventBackY, 40, kEventBackH, theme::pink());
    put_label(parent, "DOWN", 120, kEventBackY + 5, theme::pink(), &font_pixel_6x8);
}

void draw_events_range_footer(lv_obj_t *parent, std::size_t first, std::size_t visible,
                              std::size_t count) noexcept
{
    if (count <= kEventsVisible) return;
    char line[24]{};
    std::snprintf(line, sizeof(line), "%u-%u / %u",
                  static_cast<unsigned>(first + 1U),
                  static_cast<unsigned>(first + visible),
                  static_cast<unsigned>(count));
    theme::rect(parent, 0, kEventsFooterY, 320, 20, lv_color_hex(0x050808));
    put_label(parent, line, 8, kEventsFooterY + 6, theme::pink(), &font_pixel_6x8);
    draw_up_down_chips(parent, kEventsFooterY + 4, first > 0U, first + visible < count);
}

/// One line of the message log, filled from the capture store on hardware and
/// from the chat log in the simulator so both render the same way.
struct MessageRow {
    char who[16]{};
    char when[10]{};
    char route[8]{};
    char snr[10]{};
    const char *text = nullptr;
    bool mine = false;
    /// Set when one of the operator's stored channel keys opened this message,
    /// empty for the key every radio ships with.
    char key[kChannelKeyNameCapacity]{};
};

void draw_messages_empty(lv_obj_t *parent) noexcept
{
    draw_outline_rect(parent, 16, 84, 288, 92, theme::pink());
    put_label(parent, "NO MESSAGES HEARD YET", 28, 96, theme::pink(), &font_mono_semibold_12);
    put_label(parent, "EVERY TEXT MESSAGE THIS RADIO DECODES", 28, 120,
              theme::text_muted(), &font_pixel_6x8);
    put_label(parent, "LANDS HERE -- YOURS AND EVERYONE ELSE'S,", 28, 132,
              theme::text_muted(), &font_pixel_6x8);
    put_label(parent, "WITH WHO SENT IT AND HOW WELL IT ARRIVED.", 28, 144,
              theme::text_muted(), &font_pixel_6x8);
    put_label(parent, "START A CAPTURE ON SURVEY, OR JUST WAIT.", 28, 160,
              theme::text_muted(), &font_pixel_6x8);
}

void draw_message_rows(lv_obj_t *parent, const MessageRow *rows, std::size_t count,
                       std::size_t senders) noexcept
{
    // Summary panel, in the Home style: a labelled box with the numbers that
    // say whether the log is worth reading.
    draw_outline_rect(parent, 6, kMsgSummaryY, 308, 34, theme::pink());
    char value[24]{};
    put_label(parent, "MESSAGES", 12, kMsgSummaryY + 4, theme::pink(), &font_pixel_6x8);
    std::snprintf(value, sizeof(value), "%u", static_cast<unsigned>(count));
    put_label(parent, value, 12, kMsgSummaryY + 15, theme::text(), &font_mono_semibold_12);
    put_label(parent, "SENDERS", 116, kMsgSummaryY + 4, theme::pink(), &font_pixel_6x8);
    std::snprintf(value, sizeof(value), "%u", static_cast<unsigned>(senders));
    put_label(parent, value, 116, kMsgSummaryY + 15, theme::cyan(), &font_mono_semibold_12);
    put_label(parent, "NEWEST", 220, kMsgSummaryY + 4, theme::pink(), &font_pixel_6x8);
    put_clipped_label(parent, count > 0 ? rows[0].when : "--", 220, kMsgSummaryY + 15, 88,
                      theme::text(), &font_mono_semibold_12);

    if (count == 0U) {
        draw_messages_empty(parent);
        return;
    }
    const std::size_t visible = count < kMsgVisible ? count : kMsgVisible;
    for (std::size_t index = 0; index < visible; ++index) {
        const MessageRow &row = rows[index];
        const lv_coord_t y = kMsgFirstY + static_cast<lv_coord_t>(index) * kMsgRowH;
        const bool keyed = row.key[0] != '\0';
        // The same left/right edge language the chat log uses, so a message
        // you sent looks the same wherever you meet it. A message one of the
        // operator's own keys opened wears the amber a via-net line wears, and
        // names the key beside the sender, so it can never be mistaken for
        // traffic anybody within earshot could read.
        theme::rect(parent, row.mine ? 310 : 4, y, 6, 28,
                    keyed ? theme::amber() : (row.mine ? theme::pink() : theme::cyan()));
        const lv_coord_t text_x = row.mine ? 58 : 14;
        char header[64]{};
        if(keyed) {
            std::snprintf(header, sizeof(header), "%s  %s  %s  KEY %s", row.when, row.who,
                          row.route, row.key);
        } else {
            std::snprintf(header, sizeof(header), "%s  %s  %s", row.when, row.who, row.route);
        }
        // A received row starts at x=14 and the SNR reading begins at 254, so
        // the wider clip a named key needs still stops short of it.
        put_clipped_label(parent, header, text_x, y, row.mine ? 190 : 236,
                          keyed ? theme::amber()
                                : (row.mine ? theme::pink() : theme::cyan()),
                          &font_pixel_6x8);
        if (row.snr[0] != '\0') {
            put_label(parent, row.snr, 254, y, theme::lime(), &font_pixel_6x8);
        }
        put_clipped_label(parent, row.text != nullptr ? row.text : "", text_x, y + 11,
                          row.mine ? 248 : 292, theme::text(), &font_mono_semibold_12);
        theme::rule_line(parent, 6, y + 30, 308, 1, theme::grid());
    }
    if (count > visible) {
        char more[28]{};
        std::snprintf(more, sizeof(more), "%u OLDER NOT SHOWN",
                      static_cast<unsigned>(count - visible));
        put_label(parent, more, 12, kToolStripY - 12, theme::text_muted(), &font_pixel_6x8);
    }
}

void build_messages(lv_obj_t * parent)
{
#if defined(LILYSHARK_DEVICE)
    add_status_bar(parent, "MESSAGES");
    std::array<LiveNodeSummary, 8> nodes{};
    const std::size_t node_count = collect_live_nodes(nodes);
    std::array<MessageRow, 16> rows{};
    std::array<char[kChatTextCapacity], 16> texts{};
    std::array<std::uint32_t, 16> senders{};
    std::size_t sender_count = 0;
    std::size_t count = 0;
    const auto &store = capture_runtime.frames();
    for (std::size_t age = 0; age < store.size() && count < rows.size(); ++age) {
        const FrameRecord *record = store.newest(age);
        if (record == nullptr) continue;
        if (record->decoded.payload_length == 0U) continue;
        if (record->raw.captured_length <
            static_cast<std::uint16_t>(record->decoded.payload_offset +
                                       record->decoded.payload_length)) {
            continue;
        }
        // Every kind of readable text lands here: a Meshtastic message under
        // the default key or under a key the operator stored, or an
        // unencrypted LXMF message inside a Reticulum frame. The screen says
        // "every text message heard", and without the other branches it was
        // quietly default-key Meshtastic only.
        char lxmf_text[kChatTextCapacity]{};
        MeshtasticPayload payload{};
        MeshtasticKeyState key_state{};
        bool is_lxmf = false;
        if (record->decoded.protocol == ProtocolId::Meshtastic) {
            if (!read_frame_payload(*record, payload, key_state)) continue;
            if (!payload.has_text) continue;
        } else if (record->decoded.protocol == ProtocolId::Reticulum) {
            LxmfMessage lxmf{};
            if (!readLxmfMessage(record->raw.bytes + record->decoded.payload_offset,
                                 record->decoded.payload_length, lxmf)) {
                continue;
            }
            if (!lxmf.has_content) continue;
            std::snprintf(lxmf_text, sizeof(lxmf_text), "%s", lxmf.content);
            is_lxmf = true;
        } else {
            continue;
        }
        MessageRow &row = rows[count];
        const char *key_name = stored_key_name(key_state);
        if (key_name != nullptr) std::snprintf(row.key, sizeof(row.key), "%s", key_name);
        row.mine = record->decoded.source == localMeshtasticNodeNum();
        if (row.mine) {
            std::snprintf(row.who, sizeof(row.who), "YOU");
        } else {
            const char *label = nullptr;
            for (std::size_t index = 0; index < node_count; ++index) {
                if (nodes[index].id == record->decoded.source && nodes[index].label[0] != '\0') {
                    label = nodes[index].label;
                    break;
                }
            }
            if (label != nullptr) {
                std::snprintf(row.who, sizeof(row.who), "%s", label);
            } else {
                std::snprintf(row.who, sizeof(row.who), "!%04lx",
                              static_cast<unsigned long>(record->decoded.source & 0xffffU));
            }
        }
        format_age(row.when, sizeof(row.when), record->raw.rf.timestamp_us);
        std::snprintf(row.route, sizeof(row.route), "%s",
                      is_lxmf ? "LXMF"
                              : (record->decoded.destination == 0xffffffffU ? "ALL" : "DM"));
        std::snprintf(row.snr, sizeof(row.snr), "%+.1f",
                      static_cast<double>(record->raw.rf.snr_db_x10) / 10.0);
        std::snprintf(texts[count], kChatTextCapacity, "%s",
                      is_lxmf ? lxmf_text : payload.text);
        row.text = texts[count];
        bool seen = false;
        for (std::size_t index = 0; index < sender_count; ++index) {
            if (senders[index] == record->decoded.source) { seen = true; break; }
        }
        if (!seen && sender_count < senders.size()) senders[sender_count++] = record->decoded.source;
        ++count;
    }
    draw_message_rows(parent, rows.data(), count, sender_count);
#else
    add_simulator_live_status_bar(parent, "MESSAGES");
    std::array<MessageRow, 16> rows{};
    std::array<std::uint32_t, 16> senders{};
    std::size_t sender_count = 0;
    std::size_t count = 0;
    for (std::size_t offset = 0; offset < chat_log_count && count < rows.size(); ++offset) {
        const std::size_t slot =
            (chat_log_start + chat_log_count - 1U - offset) % kChatLogCapacity;
        const ChatLine &line = chat_log[slot];
        if (line.text[0] == '\0') continue;
        MessageRow &row = rows[count];
        row.mine = line.mine;
        std::snprintf(row.key, sizeof(row.key), "%s", line.key_name);
        std::snprintf(row.who, sizeof(row.who), "%s", line.mine ? "YOU" : line.from);
        std::snprintf(row.when, sizeof(row.when), "%s",
                      line.when[0] != '\0' ? line.when : "--");
        std::snprintf(row.route, sizeof(row.route), "%s",
                      line.peer == 0xffffffffU ? "ALL" : "DM");
        row.text = line.text;
        bool seen = false;
        for (std::size_t index = 0; index < sender_count; ++index) {
            if (senders[index] == line.peer) { seen = true; break; }
        }
        if (!seen && sender_count < senders.size()) senders[sender_count++] = line.peer;
        ++count;
    }
    draw_message_rows(parent, rows.data(), count, sender_count);
#endif
}

void build_events(lv_obj_t * parent)
{
    if(event_detail_open) {
        build_event_detail(parent);
        return;
    }
#if defined(LILYSHARK_DEVICE)
    {
    add_status_bar(parent, "EVENTS");
    if(runtime_event_history.empty()) {
        draw_outline_rect(parent, 8, 70, 304, 88, theme::pink());
        put_label(parent, "NO EVENTS YET", 16, 86, theme::pink(), &font_pixel_6x8);
        put_label(parent, "HARDWARE AND ANALYZER ACTIONS APPEAR HERE.", 16, 108,
                  theme::text_muted(), &font_pixel_6x8);
        return;
    }

    const std::size_t maximum_offset = runtime_event_history.size() > kEventsVisible
        ? runtime_event_history.size() - kEventsVisible : 0U;
    if(events_scroll_offset > maximum_offset) events_scroll_offset = maximum_offset;
    const std::size_t remaining = runtime_event_history.size() - events_scroll_offset;
    const std::size_t visible = remaining < kEventsVisible ? remaining : kEventsVisible;
    put_label(parent, "TIME", 7, 26, theme::pink(), &font_pixel_6x8);
    put_label(parent, "KIND", 57, 26, theme::pink(), &font_pixel_6x8);
    theme::rule_line(parent, 6, 36, 308, 1, theme::pink());
    for(std::size_t index = 0; index < visible; ++index) {
        const RuntimeEvent *event = runtime_event_history.newest(events_scroll_offset + index);
        if(event == nullptr) continue;
        const std::uint64_t uptime_seconds = event->timestamp_us / 1000000ULL;
        char time[12]{};
        std::snprintf(time, sizeof(time), "%02llu:%02llu",
                      static_cast<unsigned long long>((uptime_seconds / 3600ULL) % 100ULL),
                      static_cast<unsigned long long>((uptime_seconds / 60ULL) % 60ULL));
        const lv_color_t color = runtime_event_color(event->severity);
        const lv_coord_t y = kEventsFirstY + static_cast<lv_coord_t>(index) * kEventsRowH;
        const bool selected = index == 0U;
        if(selected) {
            theme::rect(parent, 0, y - 2, 320, kEventsRowH, lv_color_hex(0x0C1A18));
            theme::rect(parent, 0, y - 2, 3, kEventsRowH, theme::pink());
        }
        const lv_color_t row_color = selected ? theme::pink() : color;
        put_label(parent, time, 7, y, row_color, &font_mono_10);
        put_label(parent, runtime_event_type_label(event->type), 57, y, row_color,
                  &font_pixel_6x8);
        char body[120]{};
        ascii_upper(body, sizeof(body), event->message);
        put_clipped_label(parent, body, 7, y + 15, 296,
                          selected ? theme::text() : theme::text(), &font_mono_10);
        if(selected) put_label(parent, ">", 306, y + 14, theme::pink(), &font_pixel_6x8);
        theme::rule_line(parent, 6, y + 28, 308, 1, theme::grid());
    }
    draw_events_range_footer(parent, events_scroll_offset, visible,
                             runtime_event_history.size());
    return;
    }
#else
    add_simulator_live_status_bar(parent, "EVENTS");
    const simulator::EventsSnapshot &events = simulator_live_telemetry.events();
    if (events.size == 0U) {
        draw_outline_rect(parent, 8, 70, 304, 88, theme::pink());
        put_label(parent, "NO EVENTS YET", 16, 86, theme::pink(), &font_pixel_6x8);
        put_label(parent, "HARDWARE AND ANALYZER ACTIONS APPEAR HERE.", 16, 108,
                  theme::text_muted(), &font_pixel_6x8);
        return;
    }
    const std::size_t maximum_offset = events.size > kEventsVisible
        ? events.size - kEventsVisible : 0U;
    if(events_scroll_offset > maximum_offset) events_scroll_offset = maximum_offset;
    const std::size_t remaining = events.size - events_scroll_offset;
    const std::size_t visible = remaining < kEventsVisible ? remaining : kEventsVisible;
    put_label(parent, "TIME", 7, 26, theme::pink(), &font_pixel_6x8);
    put_label(parent, "KIND", 61, 26, theme::pink(), &font_pixel_6x8);
    theme::rule_line(parent, 6, 36, 308, 1, theme::pink());
    for(std::size_t index = 0U; index < visible; ++index) {
        const simulator::EventSample *event = events.newest(events_scroll_offset + index);
        if(event == nullptr) continue;
        const lv_coord_t y = kEventsFirstY + static_cast<lv_coord_t>(index) * kEventsRowH;
        const bool selected = index == 0U;
        if(selected) {
            theme::rect(parent, 0, y - 2, 320, kEventsRowH, lv_color_hex(0x0C1A18));
            theme::rect(parent, 0, y - 2, 3, kEventsRowH, theme::pink());
        }
        const lv_color_t row_color = selected ? theme::pink() :
                                                simulator_event_color(event->severity);
        char time[16]{};
        char detail[112]{};
        format_simulator_clock(time, sizeof(time), event->timestamp_seconds_of_day);
        format_simulator_event_message(detail, sizeof(detail), *event);
        ascii_upper(detail, sizeof(detail), detail);
        put_label(parent, time, 7, y, row_color, &font_mono_10);
        put_label(parent, simulator_event_kind_label(event->kind), 61, y,
                  row_color, &font_pixel_6x8);
        put_clipped_label(parent, detail, 7, y + 15, 296, theme::text(), &font_mono_10);
        if(selected) put_label(parent, ">", 306, y + 14, theme::pink(), &font_pixel_6x8);
        theme::rule_line(parent, 6, y + 28, 308, 1, theme::grid());
    }
    draw_events_range_footer(parent, events_scroll_offset, visible, events.size);

#endif
}

void build_utilization(lv_obj_t * parent)
{
#if defined(LILYSHARK_DEVICE)
    {
    add_status_bar(parent, "AIRTIME");
    const auto &store = capture_runtime.frames();
    if(store.empty()) {
        draw_outline_rect(parent, 8, 70, 304, 88, theme::pink());
        put_label(parent, "NO AIRTIME SAMPLES", 16, 86, theme::pink(), &font_pixel_6x8);
        put_label(parent, "WAITING FOR RECEIVED LORA FRAMES.", 16, 108,
                  theme::text_muted(), &font_pixel_6x8);
        return;
    }

    const std::uint64_t now_us = static_cast<std::uint64_t>(esp_timer_get_time());
    const std::uint64_t window_start_us = now_us > 60000000ULL ? now_us - 60000000ULL : 0;
    std::uint64_t airtime_us = 0;
    std::uint32_t frame_count = 0;
    std::uint32_t airtime_sample_count = 0;
    std::uint32_t crc_errors = 0;
    std::uint64_t first_timestamp = now_us;
    for(std::size_t index = 0; index < store.size(); ++index) {
        const FrameRecord *record = store.at(index);
        if(record == nullptr || record->raw.rf.timestamp_us < window_start_us) continue;
        if(record->raw.rf.timestamp_us < first_timestamp) first_timestamp = record->raw.rf.timestamp_us;
        if(record->raw.rf.hasField(RfFieldAirtime)) {
            airtime_us += record->raw.rf.airtime_us;
            ++airtime_sample_count;
        }
        if(record->raw.rf.crc == CrcStatus::Invalid) ++crc_errors;
        ++frame_count;
    }
    std::uint64_t observed_us = now_us > first_timestamp ? now_us - first_timestamp : 1000000ULL;
    if(observed_us < 1000000ULL) observed_us = 1000000ULL;
    std::uint32_t utilization = static_cast<std::uint32_t>((airtime_us * 100ULL) / observed_us);
    if(utilization > 100U) utilization = 100U;
    const std::uint32_t packets_per_minute = static_cast<std::uint32_t>(
        (static_cast<std::uint64_t>(frame_count) * 60000000ULL) / observed_us);
    const std::uint32_t crc_percent = frame_count == 0 ? 0 : (crc_errors * 100U) / frame_count;
    const bool airtime_complete = airtime_sample_count == frame_count;
    const bool airtime_available = frame_count == 0 || airtime_sample_count != 0;

    char line[48]{};
    if(airtime_available) {
        std::snprintf(line, sizeof(line), "%lu%%", static_cast<unsigned long>(utilization));
    } else {
        std::snprintf(line, sizeof(line), "--");
    }
    put_label(parent, line, 8, 28, theme::text(), &font_pixel_18x24);
    put_label(parent, airtime_complete ? "AIRTIME  60S" : "PARTIAL", 72, 36,
              airtime_complete ? theme::text_muted() : theme::amber(), &font_pixel_6x8);
    const lv_color_t util_color = !airtime_complete ? theme::amber() :
        (utilization > 60 ? theme::fault() :
         (utilization > 25 ? theme::amber() : theme::lime()));
    draw_linear_gauge(parent, 8, 54, 304, 22,
                      airtime_available ? static_cast<int>(utilization) : 0, 0, 100,
                      util_color);

    put_label(parent, "PKT/M", 8, 90, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%lu", static_cast<unsigned long>(packets_per_minute));
    put_label(parent, line, 48, 88, theme::text(), &font_mono_10);
    put_label(parent, "CRC", 120, 90, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%lu%%", static_cast<unsigned long>(crc_percent));
    put_label(parent, line, 150, 88, crc_percent == 0 ? theme::cyan() : theme::fault(),
              &font_mono_10);
    put_label(parent, "FRAMES", 210, 90, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%lu", static_cast<unsigned long>(frame_count));
    put_label(parent, line, 256, 88, theme::text(), &font_mono_10);

    put_label(parent, "RECENT AIRTIME", 8, 106, theme::pink(), &font_pixel_6x8);
    int air_vals[64]{};
    std::size_t air_count = 0;
    std::uint32_t maximum_airtime = 1;
    const std::size_t visible = store.size() < 64 ? store.size() : 64;
    for(std::size_t index = 0; index < visible; ++index) {
        const FrameRecord *record = store.newest(visible - 1 - index);
        if(record == nullptr || !record->raw.rf.hasField(RfFieldAirtime)) continue;
        air_vals[air_count++] = static_cast<int>(record->raw.rf.airtime_us);
        if(record->raw.rf.airtime_us > maximum_airtime) {
            maximum_airtime = record->raw.rf.airtime_us;
        }
    }
    draw_field_plot(parent, 0, 8, 116, 304, 50, air_vals, air_count, 0,
                    static_cast<int>(maximum_airtime), theme::lime(), theme::text(),
                    false);
    put_label(parent, maximum_airtime >= 1000U ? "MS" : "US", 300, 106,
              theme::text_muted(), &font_pixel_6x8);
    draw_airtime_axis_chips(parent, maximum_airtime);
    theme::rect(parent, 0, 204, 320, 20, lv_color_hex(0x050808));
    put_label(parent, "OLDEST", 8, 210, theme::text_muted(), &font_pixel_6x8);
    put_label(parent, "NEWEST", 268, 210, theme::text_muted(), &font_pixel_6x8);
    return;
    }
#else
    add_simulator_live_status_bar(parent, "AIRTIME");
    const simulator::AirtimeSnapshot &airtime = simulator_live_telemetry.airtime();
    const simulator::ProtocolMixSnapshot &mix = simulator_live_telemetry.protocolMix();
    std::uint32_t crc_failures = 0U;
    for(const std::uint16_t count : mix.crc_failures_last_minute) {
        crc_failures += count;
    }
    const std::uint32_t crc_percent = mix.total_last_minute == 0U ? 0U :
        (crc_failures * 100U) / mix.total_last_minute;
    char metric[24]{};
    std::snprintf(metric, sizeof(metric), "%u%%",
                  static_cast<unsigned>(airtime.utilization_percent));
    put_label(parent, metric, 8, 28, theme::text(), &font_pixel_18x24);
    put_label(parent, "AIRTIME  60S", 72, 36, theme::text_muted(), &font_pixel_6x8);
    const lv_color_t util_color =
        airtime.utilization_percent > 60U ? theme::fault() :
        (airtime.utilization_percent > 35U ? theme::amber() : theme::lime());
    draw_linear_gauge(parent, 8, 54, 304, 22,
                      static_cast<int>(airtime.utilization_percent), 0, 100, util_color);

    put_label(parent, "PKT/M", 8, 90, theme::pink(), &font_pixel_6x8);
    std::snprintf(metric, sizeof(metric), "%u",
                  static_cast<unsigned>(simulator_live_telemetry.traffic().packets_per_minute));
    put_label(parent, metric, 48, 88, theme::text(), &font_mono_10);
    put_label(parent, "CRC", 120, 90, theme::pink(), &font_pixel_6x8);
    std::snprintf(metric, sizeof(metric), "%u%%", static_cast<unsigned>(crc_percent));
    put_label(parent, metric, 150, 88,
              crc_percent == 0U ? theme::cyan() : theme::fault(), &font_mono_10);
    put_label(parent, "FRAMES", 210, 90, theme::pink(), &font_pixel_6x8);
    std::snprintf(metric, sizeof(metric), "%u",
                  static_cast<unsigned>(mix.total_last_minute));
    put_label(parent, metric, 256, 88, theme::text(), &font_mono_10);

    put_label(parent, "RECENT AIRTIME", 8, 106, theme::pink(), &font_pixel_6x8);
    int air_vals[simulator::kAirtimeBarCount]{};
    std::uint32_t maximum_airtime = 1U;
    for(std::size_t index = 0U; index < simulator::kAirtimeBarCount; ++index) {
        air_vals[index] = static_cast<int>(airtime.bars_airtime_us[index]);
        if (airtime.bars_airtime_us[index] > maximum_airtime) {
            maximum_airtime = airtime.bars_airtime_us[index];
        }
    }
    draw_field_plot(parent, 0, 8, 116, 304, 50, air_vals, simulator::kAirtimeBarCount, 0,
                    static_cast<int>(maximum_airtime), theme::lime(), theme::text(),
                    false);
    put_label(parent, maximum_airtime >= 1000U ? "MS" : "US", 300, 106,
              theme::text_muted(), &font_pixel_6x8);
    draw_airtime_axis_chips(parent, maximum_airtime);
    theme::rect(parent, 0, 204, 320, 20, lv_color_hex(0x050808));
    put_label(parent, "OLDEST", 8, 210, theme::text_muted(), &font_pixel_6x8);
    put_label(parent, "NEWEST", 268, 210, theme::text_muted(), &font_pixel_6x8);
#endif
}

constexpr std::array<const char *, 6> protocol_health_labels = {{
    "MESHTASTIC", "MESHCORE", "RETICULUM", "CUSTOM / APP", "UNKNOWN / RAW", "MALFORMED",
}};

struct ProtocolHealthSnapshot {
    std::array<std::uint32_t, 6> rows{};
    std::array<std::uint32_t, 6> crc_bad_by_row{};
    std::array<std::int16_t, 6> mean_snr_db_x10{};
    std::array<bool, 6> health_metrics_available{};
    std::uint32_t total = 0U;
    std::uint32_t decoded = 0U;
    std::uint32_t crc_bad = 0U;
};

ProtocolHealthSnapshot current_protocol_health() noexcept
{
    ProtocolHealthSnapshot snapshot{};
#if defined(LILYSHARK_DEVICE)
    const DiagnosticCounters &counters = rolling_diagnostics.snapshot().counters;
    const DiagnosticProtocolMetrics meshtastic = counters.protocolMetrics(ProtocolId::Meshtastic);
    const DiagnosticProtocolMetrics meshcore = counters.protocolMetrics(ProtocolId::MeshCore);
    const DiagnosticProtocolMetrics reticulum = counters.protocolMetrics(ProtocolId::Reticulum);
    const DiagnosticProtocolMetrics unknown = counters.protocolMetrics(ProtocolId::Unknown);
    const DiagnosticProtocolMetrics custom = counters.protocolMetrics(ProtocolId::Custom);
    snapshot.rows[0] = static_cast<std::uint32_t>(meshtastic.frames - meshtastic.malformed_frames);
    snapshot.rows[1] = static_cast<std::uint32_t>(meshcore.frames - meshcore.malformed_frames);
    snapshot.rows[2] = static_cast<std::uint32_t>(reticulum.frames - reticulum.malformed_frames);
    snapshot.rows[3] = static_cast<std::uint32_t>(custom.frames - custom.malformed_frames);
    snapshot.rows[4] = static_cast<std::uint32_t>(unknown.frames - unknown.malformed_frames);
    snapshot.rows[5] = static_cast<std::uint32_t>(counters.malformed_frames);
    const std::array<DiagnosticProtocolMetrics, 5> metrics = {{
        meshtastic, meshcore, reticulum, custom, unknown,
    }};
    for(std::size_t index = 0U; index < metrics.size(); ++index) {
        snapshot.crc_bad_by_row[index] = static_cast<std::uint32_t>(
            metrics[index].nonmalformed_crc_invalid_frames);
        snapshot.mean_snr_db_x10[index] = metrics[index].nonmalformedMeanSnrDbX10();
        snapshot.health_metrics_available[index] = snapshot.rows[index] != 0U &&
            metrics[index].hasNonmalformedMeanSnr();
    }
    snapshot.total = static_cast<std::uint32_t>(counters.total_frames);
    snapshot.decoded = snapshot.rows[0] + snapshot.rows[1] + snapshot.rows[2] + snapshot.rows[3];
    snapshot.crc_bad = static_cast<std::uint32_t>(counters.crc_invalid_frames);
#else
    const simulator::ProtocolMixSnapshot &mix = simulator_live_telemetry.protocolMix();
    const auto nonmalformed = [&](simulator::SimulatedProtocol protocol) noexcept {
        const std::size_t index = static_cast<std::size_t>(protocol);
        return static_cast<std::uint32_t>(mix.packets_last_minute[index] -
                                          mix.malformed_by_protocol_last_minute[index]);
    };
    snapshot.rows = {{
        nonmalformed(simulator::SimulatedProtocol::Meshtastic),
        nonmalformed(simulator::SimulatedProtocol::MeshCore),
        nonmalformed(simulator::SimulatedProtocol::Reticulum),
        0U,
        nonmalformed(simulator::SimulatedProtocol::Unknown),
        mix.malformed_last_minute,
    }};
    snapshot.total = mix.total_last_minute;
    // "DECODED" means a protocol decoder classified the frame without a
    // structural error. Header-only/opaque protected bodies still count, just
    // as they do on the device; UNKNOWN/RAW and MALFORMED do not.
    snapshot.decoded = snapshot.rows[0] + snapshot.rows[1] + snapshot.rows[2] +
                       snapshot.rows[3];
    for(const std::uint16_t failures : mix.crc_failures_last_minute) {
        snapshot.crc_bad += failures;
    }
    const auto copy_health = [&](std::size_t row,
                                 simulator::SimulatedProtocol protocol) noexcept {
        const std::size_t index = static_cast<std::size_t>(protocol);
        snapshot.crc_bad_by_row[row] =
            mix.nonmalformed_crc_failures_last_minute[index];
        snapshot.mean_snr_db_x10[row] = mix.nonmalformed_mean_snr_db_x10[index];
        snapshot.health_metrics_available[row] = snapshot.rows[row] != 0U;
    };
    copy_health(0U, simulator::SimulatedProtocol::Meshtastic);
    copy_health(1U, simulator::SimulatedProtocol::MeshCore);
    copy_health(2U, simulator::SimulatedProtocol::Reticulum);
    copy_health(4U, simulator::SimulatedProtocol::Unknown);
#endif
    return snapshot;
}

void build_protocols(lv_obj_t *parent)
{
#if defined(LILYSHARK_DEVICE)
    add_status_bar(parent, "PROTOCOLS", "BAT 100%", "GPS LOCK", "60 SEC");
#else
    add_simulator_live_status_bar(parent, "PROTOCOLS");
#endif
    const ProtocolHealthSnapshot snapshot = current_protocol_health();
    char line[64]{};
    const std::uint32_t decoded_percent = snapshot.total == 0U ? 0U :
        (snapshot.decoded * 100U) / snapshot.total;
    put_label(parent, "FRAMES", 8, 28, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%lu", static_cast<unsigned long>(snapshot.total));
    put_label(parent, line, 56, 28, theme::text(), &font_pixel_6x8);
    put_label(parent, "DEC", 120, 28, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%lu%%", static_cast<unsigned long>(decoded_percent));
    put_label(parent, line, 146, 28, theme::lime(), &font_pixel_6x8);
    put_label(parent, "CRC", 210, 28, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%lu", static_cast<unsigned long>(snapshot.crc_bad));
    put_label(parent, line, 236, 28,
              snapshot.crc_bad == 0U ? theme::cyan() : theme::amber(), &font_pixel_6x8);
    put_label(parent, "/60S", 280, 28, theme::text_muted(), &font_pixel_6x8);
    theme::rule_line(parent, 6, 42, 308, 1, theme::pink());

    const std::array<lv_color_t, 6> colors = {{
        theme::lime(), theme::cyan(), theme::pink(), theme::amber(),
        theme::text_muted(), theme::fault(),
    }};
    std::uint32_t largest = 1U;
    for(const std::uint32_t count : snapshot.rows) if(count > largest) largest = count;
    for(std::size_t index = 0; index < protocol_health_labels.size(); ++index) {
        const lv_coord_t y = 51 + static_cast<lv_coord_t>(index) * 26;
        const bool selected = index == protocols_selection;
        if(selected) {
            theme::rect(parent, 3, y - 1, 314, 24, lv_color_hex(0x0C1A18));
            theme::rect(parent, 3, y - 1, 3, 24, theme::pink());
        }
        const lv_color_t text_color = selected ? theme::pink() : theme::text();
        put_label(parent, protocol_health_labels[index], 9, y + 6, text_color, &font_pixel_6x8);
        theme::rect(parent, 113, y + 4, 102, 10,
                    selected ? theme::rule() : theme::surface());
        const lv_coord_t fill = static_cast<lv_coord_t>(
            (static_cast<std::uint64_t>(snapshot.rows[index]) * 98ULL) / largest);
        if(fill > 0) theme::rect(parent, 115, y + 6, fill, 6,
                                 selected ? theme::pink() : colors[index]);
        const std::uint32_t percent = snapshot.total == 0U ? 0U :
            (snapshot.rows[index] * 100U) / snapshot.total;
        std::snprintf(line, sizeof(line), "%3lu  %2lu%%",
                      static_cast<unsigned long>(snapshot.rows[index]),
                      static_cast<unsigned long>(percent));
        put_label(parent, line, 230, y + 6, text_color, &font_pixel_6x8);
        theme::rule_line(parent, 6, y + 23, 308, 1, theme::grid());
    }
}

void protocol_detail_activity(std::array<std::uint16_t, 30> &activity) noexcept
{
    const std::size_t selected = protocols_selection % protocol_health_labels.size();
#if defined(LILYSHARK_DEVICE)
    for(std::size_t index = 0U; index < activity.size(); ++index) {
        const std::size_t older_age = (activity.size() - 1U - index) * 2U + 1U;
        std::uint64_t count = 0U;
        for(std::size_t pair = 0U; pair < 2U; ++pair) {
            const DiagnosticBucket *bucket = rolling_diagnostics.newest(older_age - pair);
            if(bucket == nullptr) continue;
            if(selected == 5U) {
                count += bucket->counters.malformed_frames;
                continue;
            }
            const ProtocolId protocol = selected == 0U ? ProtocolId::Meshtastic :
                (selected == 1U ? ProtocolId::MeshCore :
                 (selected == 2U ? ProtocolId::Reticulum :
                  (selected == 3U ? ProtocolId::Custom : ProtocolId::Unknown)));
            const DiagnosticProtocolMetrics metrics = bucket->protocolMetrics(protocol);
            count += metrics.frames - metrics.malformed_frames;
        }
        activity[index] = static_cast<std::uint16_t>(count > 0xffffU ? 0xffffU : count);
    }
#else
    if(selected == 3U) return;
    for(std::size_t index = 0U; index < activity.size(); ++index) {
        const std::size_t older_age = (activity.size() - 1U - index) * 2U + 1U;
        std::uint32_t count = 0U;
        for(std::size_t pair = 0U; pair < 2U; ++pair) {
            if(selected == 5U) {
                count += simulator_live_telemetry.timelineOutcomeFrames(
                    simulator::SimulatedDecodeOutcome::Malformed, older_age - pair);
            } else {
                const simulator::SimulatedProtocol protocol = selected == 0U
                    ? simulator::SimulatedProtocol::Meshtastic
                    : (selected == 1U ? simulator::SimulatedProtocol::MeshCore
                       : (selected == 2U ? simulator::SimulatedProtocol::Reticulum
                          : simulator::SimulatedProtocol::Unknown));
                const simulator::RfTimelineProtocolBucket bucket =
                    simulator_live_telemetry.timelineProtocolBucket(protocol, older_age - pair);
                count += bucket.frames - bucket.malformed_frames;
            }
        }
        activity[index] = static_cast<std::uint16_t>(count);
    }
#endif
}

void build_protocol_detail(lv_obj_t *parent)
{
#if defined(LILYSHARK_DEVICE)
    add_status_bar(parent, "PROTO", "BAT 100%", "GPS LOCK", "60 SEC");
#else
    add_simulator_live_status_bar(parent, "PROTO");
#endif
    const ProtocolHealthSnapshot snapshot = current_protocol_health();
    const std::size_t selected = protocols_selection % protocol_health_labels.size();
    const std::uint32_t frames = snapshot.rows[selected];
    const std::uint32_t share = snapshot.total == 0U ? 0U :
        (frames * 100U) / snapshot.total;
    const std::uint32_t bad = snapshot.crc_bad_by_row[selected];
    const bool health_available = snapshot.health_metrics_available[selected];
    const std::uint32_t valid = frames == 0U ? 0U :
        ((frames > bad ? frames - bad : 0U) * 100U) / frames;
    char line[64]{};
    put_label(parent, protocol_health_labels[selected], 8, 28, theme::pink(),
              &font_pixel_6x8);
    put_label(parent, "FRAMES", 8, 46, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%lu", static_cast<unsigned long>(frames));
    put_label(parent, line, 8, 56, theme::cyan(), &font_pixel_18x24);
    std::snprintf(line, sizeof(line), "%lu%%", static_cast<unsigned long>(share));
    put_label(parent, "SHARE", 120, 46, theme::pink(), &font_pixel_6x8);
    put_label(parent, line, 120, 56, theme::text(), &font_pixel_18x24);
    put_label(parent, "CRC", 200, 46, theme::pink(), &font_pixel_6x8);
    if (health_available) {
        std::snprintf(line, sizeof(line), "%lu%%", static_cast<unsigned long>(valid));
    } else {
        std::snprintf(line, sizeof(line), "--");
    }
    put_label(parent, line, 200, 56,
              !health_available ? theme::text_muted() :
              (valid < 90U ? theme::fault() : theme::lime()),
              &font_pixel_18x24);
    if (health_available) {
        std::snprintf(line, sizeof(line), "MEAN  %+.1f DB",
                      static_cast<double>(snapshot.mean_snr_db_x10[selected]) / 10.0);
    } else {
        std::snprintf(line, sizeof(line), "MEAN  --");
    }
    put_label(parent, line, 8, 86, theme::cyan(), &font_pixel_6x8);
    put_label(parent, "ACTIVITY / 60S", 8, 98, theme::text_muted(), &font_pixel_6x8);
    add_grid(parent, 7, 107, 306, 68, 50, 22);
    std::array<std::uint16_t, 30> activity{};
    protocol_detail_activity(activity);
    std::uint16_t maximum = 1U;
    for(const std::uint16_t count : activity) if(count > maximum) maximum = count;
    for(std::size_t index = 0U; index < activity.size(); ++index) {
        const lv_coord_t height = static_cast<lv_coord_t>(
            (static_cast<std::uint32_t>(activity[index]) * 56U) / maximum);
        if(height > 0) {
            theme::rect(parent, 12 + static_cast<lv_coord_t>(index) * 10,
                        169 - height, 6, height,
                        selected == 5U ? theme::fault() : theme::lime());
        }
    }
    char scale[8]{};
    std::snprintf(scale, sizeof(scale), "%u", static_cast<unsigned>(maximum));
    const lv_color_t count_ink = selected == 5U ? theme::fault() : theme::lime();
    draw_axis_chip(parent, 8, 108, scale, count_ink);
    draw_axis_chip(parent, 8, 158, "0", theme::text());
    draw_axis_chip(parent, 8, 176, "-60S", theme::text_muted());
    draw_axis_chip(parent, 284, 176, "NOW", theme::pink());
    constexpr std::array<const char *, 6> explanations = {{
        "HEADERS, ROUTES, HOPS, CHANNEL.",
        "TRANSPORT, PATH, PROTECTED BODY.",
        "HEADERS, CONTEXT, HOPS, IFAC.",
        "APP DECODERS AND CAPTURE POINTERS.",
        "RAW BYTES, NO MATCHING DECODER.",
        "FAILED STRUCTURE OR CRC CHECK.",
    }};
    draw_back_strip(parent, explanations[selected]);
}

struct TimelineBucketView {
    std::uint16_t frames = 0U;
    std::uint16_t crc_bad = 0U;
    std::int32_t snr_sum_x10 = 0;
    std::uint16_t snr_samples = 0U;
    bool event_marker = false;
};

bool timeline_protocol_matches(ProtocolId protocol) noexcept
{
    switch(timeline_filter_selection) {
        case 1U: return protocol == ProtocolId::Meshtastic;
        case 2U: return protocol == ProtocolId::MeshCore;
        case 3U: return protocol == ProtocolId::Reticulum;
        case 4U: return protocol == ProtocolId::Unknown || protocol == ProtocolId::Custom;
        default: return true;
    }
}

void current_timeline(std::array<TimelineBucketView, 60> &buckets) noexcept
{
#if defined(LILYSHARK_DEVICE)
    for(std::size_t index = 0U; index < buckets.size(); ++index) {
        const std::size_t older_age = buckets.size() - 1U - index;
        for(std::size_t pair = 0U; pair < 1U; ++pair) {
            const DiagnosticBucket *source = rolling_diagnostics.newest(older_age - pair);
            if(source == nullptr) continue;
            std::uint64_t frames = source->counters.total_frames;
            std::uint64_t crc_bad = source->counters.crc_invalid_frames;
            std::int64_t snr_sum = source->counters.snr_sum_db_x10;
            std::uint64_t snr_samples = source->counters.snr_sample_count;
            if(timeline_filter_selection != 0U) {
                DiagnosticProtocolMetrics metrics{};
                if(timeline_filter_selection == 1U) {
                    metrics = source->protocolMetrics(ProtocolId::Meshtastic);
                } else if(timeline_filter_selection == 2U) {
                    metrics = source->protocolMetrics(ProtocolId::MeshCore);
                } else if(timeline_filter_selection == 3U) {
                    metrics = source->protocolMetrics(ProtocolId::Reticulum);
                } else {
                    const DiagnosticProtocolMetrics unknown =
                        source->protocolMetrics(ProtocolId::Unknown);
                    const DiagnosticProtocolMetrics custom =
                        source->protocolMetrics(ProtocolId::Custom);
                    metrics.frames = unknown.frames + custom.frames;
                    metrics.crc_invalid_frames = unknown.crc_invalid_frames +
                                                 custom.crc_invalid_frames;
                    metrics.snr_sum_db_x10 = unknown.snr_sum_db_x10 + custom.snr_sum_db_x10;
                    metrics.snr_sample_count = unknown.snr_sample_count +
                                               custom.snr_sample_count;
                }
                frames = metrics.frames;
                crc_bad = metrics.crc_invalid_frames;
                snr_sum = metrics.snr_sum_db_x10;
                snr_samples = metrics.snr_sample_count;
            }
            buckets[index].frames = static_cast<std::uint16_t>(
                buckets[index].frames + frames);
            buckets[index].crc_bad = static_cast<std::uint16_t>(
                buckets[index].crc_bad + crc_bad);
            buckets[index].snr_sum_x10 += static_cast<std::int32_t>(snr_sum);
            buckets[index].snr_samples = static_cast<std::uint16_t>(
                buckets[index].snr_samples + snr_samples);
            buckets[index].event_marker = buckets[index].event_marker ||
                                           source->counters.event_marker_count != 0U;
        }
    }
#else
    const simulator::RfTimelineSnapshot &timeline = simulator_live_telemetry.timeline();
    for(std::size_t index = 0U; index < buckets.size(); ++index) {
        const std::size_t older_age = buckets.size() - 1U - index;
        for(std::size_t pair = 0U; pair < 1U; ++pair) {
            const std::size_t age = older_age - pair;
            const simulator::RfTimelineBucket *sample = timeline.newest(age);
            if(sample == nullptr) continue;
            if(timeline_filter_selection == 0U) {
                buckets[index].frames = static_cast<std::uint16_t>(
                    buckets[index].frames + sample->packets_per_second);
                buckets[index].crc_bad = static_cast<std::uint16_t>(
                    buckets[index].crc_bad + sample->crc_failures);
                buckets[index].snr_sum_x10 += sample->snr_sum_db_x10;
                buckets[index].snr_samples = static_cast<std::uint16_t>(
                    buckets[index].snr_samples + sample->snr_sample_count);
            } else {
                const simulator::SimulatedProtocol protocol =
                    timeline_filter_selection == 1U ? simulator::SimulatedProtocol::Meshtastic :
                    (timeline_filter_selection == 2U ? simulator::SimulatedProtocol::MeshCore :
                     (timeline_filter_selection == 3U ? simulator::SimulatedProtocol::Reticulum :
                                                       simulator::SimulatedProtocol::Unknown));
                const simulator::RfTimelineProtocolBucket filtered =
                    simulator_live_telemetry.timelineProtocolBucket(protocol, age);
                buckets[index].frames = static_cast<std::uint16_t>(
                    buckets[index].frames + filtered.frames);
                buckets[index].crc_bad = static_cast<std::uint16_t>(
                    buckets[index].crc_bad + filtered.crc_failures);
                buckets[index].snr_sum_x10 += filtered.snr_sum_db_x10;
                buckets[index].snr_samples = static_cast<std::uint16_t>(
                    buckets[index].snr_samples + filtered.snr_sample_count);
            }
            buckets[index].event_marker = buckets[index].event_marker ||
                sample->markers != simulator::TimelineMarker::None;
        }
    }
#endif
}

void build_timeline(lv_obj_t *parent)
{
#if defined(LILYSHARK_DEVICE)
    add_status_bar(parent, "TIMELINE", "BAT 100%", "GPS LOCK", "60 SEC");
#else
    add_simulator_live_status_bar(parent, "TIMELINE");
#endif
    constexpr std::array<const char *, 5> filters = {{
        // The filter is where a reader learns what the short tag in the traffic
        // table means, so it spends its 58 px on the whole protocol name.
        "ALL", "MESH", "MESHCORE", "RETICULUM", "RAW",
    }};
    for (std::size_t index = 0; index < filters.size(); ++index) {
        const lv_coord_t x = kTlChipX0 + static_cast<lv_coord_t>(index) * kTlChipGap;
        const bool selected = index == (timeline_filter_selection % filters.size());
        if (selected) {
            theme::rect(parent, x, kTlChipY, kTlChipW, kTlChipH, theme::pink());
            const lv_coord_t text_w = static_cast<lv_coord_t>(std::strlen(filters[index]) * 6);
            put_label(parent, filters[index], x + (kTlChipW - text_w) / 2, kTlChipY + 3,
                      theme::on_accent(), &font_pixel_6x8);
        } else {
            draw_outline_rect(parent, x, kTlChipY, kTlChipW, kTlChipH, theme::pink());
            const lv_coord_t text_w = static_cast<lv_coord_t>(std::strlen(filters[index]) * 6);
            put_label(parent, filters[index], x + (kTlChipW - text_w) / 2, kTlChipY + 3,
                      theme::pink(), &font_pixel_6x8);
        }
    }

    std::array<TimelineBucketView, 60> buckets{};
    current_timeline(buckets);
    constexpr lv_coord_t chart_x = 8;
    constexpr lv_coord_t chart_width = 300;
    put_label(parent, "PKT", 10, 44, theme::cyan(), &font_pixel_6x8);
    put_label(parent, "SNR", 10, 90, theme::lime(), &font_pixel_6x8);
    put_label(parent, "CRC", 10, 136, theme::fault(), &font_pixel_6x8);

    std::uint16_t max_frames = 1U;
    std::uint32_t total_frames = 0U;
    std::uint32_t total_crc = 0U;
    std::int64_t total_snr = 0;
    std::uint32_t total_snr_samples = 0U;
    int snr_vals[60]{};
    for(std::size_t index = 0; index < buckets.size(); ++index) {
        if(buckets[index].frames > max_frames) max_frames = buckets[index].frames;
        total_frames += buckets[index].frames;
        total_crc += buckets[index].crc_bad;
        total_snr += buckets[index].snr_sum_x10;
        total_snr_samples += buckets[index].snr_samples;
        if (buckets[index].snr_samples > 0U) {
            snr_vals[index] = buckets[index].snr_sum_x10 /
                              static_cast<int>(buckets[index].snr_samples);
        }
    }
    theme::rect(parent, chart_x, 54, chart_width, 34, lv_color_hex(0x040C0B));
    for (std::size_t index = 0; index < buckets.size(); ++index) {
        const lv_coord_t bx = chart_x + static_cast<lv_coord_t>(index) * 5;
        const lv_coord_t packet_height = static_cast<lv_coord_t>(
            (static_cast<std::uint32_t>(buckets[index].frames) * 32U) / max_frames);
        if (packet_height > 0) {
            theme::rect(parent, bx, 88 - packet_height, 4, packet_height, theme::cyan());
        }
        if (buckets[index].event_marker) {
            theme::rect(parent, bx + 1, 54, 2, 3, theme::amber());
        }
    }
    draw_field_plot(parent, 0, chart_x, 98, chart_width, 36, snr_vals, buckets.size(),
                    -250, 50, theme::lime(), theme::text(), true);
    theme::rect(parent, chart_x, 138, chart_width, 32, lv_color_hex(0x040C0B));
    std::uint16_t max_crc = 1U;
    for (const TimelineBucketView &bucket : buckets) {
        if (bucket.crc_bad > max_crc) max_crc = bucket.crc_bad;
    }
    for (std::size_t index = 0; index < buckets.size(); ++index) {
        if (buckets[index].crc_bad == 0U) continue;
        const lv_coord_t bx = chart_x + static_cast<lv_coord_t>(index) * 5;
        const lv_coord_t crc_height = static_cast<lv_coord_t>(
            2U + (static_cast<std::uint32_t>(buckets[index].crc_bad) * 28U) / max_crc);
        theme::rect(parent, bx, 170 - crc_height, 4, crc_height, theme::fault());
    }

    char scale[12]{};
    std::snprintf(scale, sizeof(scale), "%u", static_cast<unsigned>(max_frames));
    draw_axis_chip(parent, chart_x + 2, 55, scale, theme::cyan());
    draw_axis_chip(parent, chart_x + 2, 77, "0", theme::text());
    draw_axis_chip(parent, chart_x + 2, 99, "+5", theme::lime());
    draw_axis_chip(parent, chart_x + 2, 123, "-25", theme::text());
    std::snprintf(scale, sizeof(scale), "%u", static_cast<unsigned>(max_crc));
    draw_axis_chip(parent, chart_x + 2, 139, scale, theme::fault());
    draw_axis_chip(parent, chart_x + 2, 159, "0", theme::text());
    draw_axis_chip(parent, chart_x + 36, 160, "-60S", theme::text_muted());
    draw_axis_chip(parent, chart_x + chart_width - 28, 160, "NOW", theme::pink());

    char line[24]{};
    theme::rect(parent, 0, 204, 320, 20, lv_color_hex(0x050808));
    put_label(parent, "RATE", 8, 210, theme::pink(), &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%lu/MIN", static_cast<unsigned long>(total_frames));
    put_label(parent, line, 38, 209, theme::text(), &font_mono_10);
    put_label(parent, "MEAN", 110, 210, theme::pink(), &font_pixel_6x8);
    const double mean_snr = total_snr_samples == 0U ? 0.0 :
        static_cast<double>(total_snr) / (10.0 * static_cast<double>(total_snr_samples));
    std::snprintf(line, sizeof(line), "%+.1f DB", mean_snr);
    put_label(parent, line, 140, 209, theme::lime(), &font_mono_10);
    put_label(parent, "CRC", 230, 210, theme::pink(), &font_pixel_6x8);
    const std::uint32_t crc_percent = total_frames == 0U ? 0U :
        (total_crc * 100U) / total_frames;
    std::snprintf(line, sizeof(line), "%lu%%", static_cast<unsigned long>(crc_percent));
    put_label(parent, line, 254, 209,
              crc_percent == 0U ? theme::cyan() : theme::fault(), &font_mono_10);
}

const RadioProfile &shell_active_profile() noexcept
{
#if defined(LILYSHARK_DEVICE)
    return radio_service.activeProfile();
#else
    const std::size_t count = builtinProfileCount();
    return builtinProfiles()[count == 0U ? 0U : simulator_active_profile_index % count];
#endif
}

bool capture_session_active() noexcept
{
#if defined(LILYSHARK_DEVICE)
    return native_capture_recording || pcap_recording;
#else
    return app_settings.capture_enabled;
#endif
}

bool capture_data_recording() noexcept
{
#if defined(LILYSHARK_DEVICE)
    if(app_settings.simulate_mode) return native_capture_recording;
    const bool compatible_pcap = pcap_recording &&
                                 last_pcap_result != PcapWriteResult::InvalidBandwidth;
    return native_capture_recording || compatible_pcap;
#else
    return app_settings.capture_enabled;
#endif
}

const char *capture_summary_value() noexcept
{
#if defined(LILYSHARK_DEVICE)
    if(app_settings.simulate_mode) {
        if(native_capture_recording) return "SIM LSCAP";
        return app_settings.capture_enabled ? "SIM RETRY" : "OFF";
    }
    const bool compatible_pcap = pcap_recording &&
                                 last_pcap_result != PcapWriteResult::InvalidBandwidth;
    if(native_capture_recording && compatible_pcap) return "LSCAP + PCAP";
    if(native_capture_recording) return "LSCAP ONLY";
    if(compatible_pcap) return "PCAP ONLY";
    if(pcap_recording) return "PCAP LIMIT";
    return app_settings.capture_enabled ? "RETRY NEEDED" : "OFF";
#else
    return app_settings.capture_enabled ? "RECORDING" : "OFF";
#endif
}

lv_color_t capture_summary_color() noexcept
{
#if defined(LILYSHARK_DEVICE)
    if(app_settings.simulate_mode) {
        return native_capture_recording ? theme::lime() :
               (app_settings.capture_enabled ? theme::amber() : theme::text_muted());
    }
    const bool compatible_pcap = pcap_recording &&
                                 last_pcap_result != PcapWriteResult::InvalidBandwidth;
    if(native_capture_recording && compatible_pcap) return theme::lime();
    if(native_capture_recording || compatible_pcap || pcap_recording ||
       app_settings.capture_enabled) {
        return theme::amber();
    }
    return theme::text_muted();
#else
    return app_settings.capture_enabled ? theme::lime() : theme::text_muted();
#endif
}

const char *shell_protocol_name(ProtocolId protocol) noexcept
{
    switch(protocol) {
        case ProtocolId::Meshtastic: return "MESHTASTIC";
        case ProtocolId::MeshCore: return "MESHCORE";
        case ProtocolId::Reticulum: return "RETICULUM / RNODE";
        case ProtocolId::Custom: return "OTHER LORA";
        case ProtocolId::Unknown: default: return "RAW LORA";
    }
}

std::size_t onboarding_profile_count() noexcept
{
    switch(onboarding_network_selection) {
        case 0: return 1;
        case 1: return 2;
        case 2: return 2;
        default: return builtinProfileCount();
    }
}

std::size_t onboarding_profile_index(std::size_t selection) noexcept
{
    constexpr std::array<std::size_t, 1> meshtastic = {{0}};
    constexpr std::array<std::size_t, 2> meshcore = {{1, 2}};
    constexpr std::array<std::size_t, 2> reticulum = {{4, 3}};
    switch(onboarding_network_selection) {
        case 0: return meshtastic[selection % meshtastic.size()];
        case 1: return meshcore[selection % meshcore.size()];
        case 2: return reticulum[selection % reticulum.size()];
        default: {
            const std::size_t count = builtinProfileCount();
            return count == 0U ? 0U : selection % count;
        }
    }
}

